--
-- Name: admin_get_product_order_bumps(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_get_product_order_bumps(product_id_param uuid) RETURNS TABLE(bump_id uuid, bump_product_id uuid, bump_product_name text, bump_price numeric, bump_title text, bump_description text, is_active boolean, display_order integer, access_duration_days integer, urgency_duration_minutes integer, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT ( select public.is_admin() ) THEN
    RAISE EXCEPTION 'Access denied: Admin privileges required';
  END IF;

  RETURN QUERY
  SELECT
    ob.id as bump_id,
    ob.bump_product_id,
    p.name as bump_product_name,
    ob.bump_price,
    ob.bump_title,
    ob.bump_description,
    ob.is_active,
    ob.display_order,
    ob.access_duration_days,
    ob.urgency_duration_minutes,
    ob.created_at,
    ob.updated_at
  FROM public.order_bumps ob
  INNER JOIN public.products p ON p.id = ob.bump_product_id
  WHERE ob.main_product_id = product_id_param
  ORDER BY ob.display_order ASC, ob.created_at DESC;
END;
$$;


