-- Name: affiliate_admin(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_admin(p_actor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF (select auth.role()) IS DISTINCT FROM 'service_role' OR p_actor IS NULL
 OR ((select auth.uid()) IS NOT NULL AND (select auth.uid())<>p_actor)
 OR NOT EXISTS(SELECT 1 FROM public.admin_users WHERE user_id=p_actor) THEN
 RAISE EXCEPTION 'Admin required' USING ERRCODE='42501'; END IF;
END $$;


ALTER FUNCTION public.affiliate_admin(p_actor uuid) OWNER TO postgres;

--
-- Name: affiliate_valid_reference(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_valid_reference(p_value text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 SELECT p_value IS NOT NULL AND length(btrim(p_value)) BETWEEN 1 AND 200 AND p_value !~ E'[\r\n]';
$$;


ALTER FUNCTION public.affiliate_valid_reference(p_value text) OWNER TO postgres;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: affiliate_memberships; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.affiliate_memberships (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid,
    code text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    display_name text NOT NULL,
    channel text,
    accepted_terms_version text,
    accepted_at timestamp with time zone,
    version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    is_partner boolean DEFAULT true NOT NULL,
    creator_terms_version text,
    creator_accepted_at timestamp with time zone,
    CONSTRAINT affiliate_memberships_accepted_terms_version_check CHECK (((accepted_terms_version IS NULL) OR public.affiliate_valid_reference(accepted_terms_version))),
    CONSTRAINT affiliate_memberships_channel_check CHECK ((length(channel) <= 500)),
    CONSTRAINT affiliate_memberships_code_check CHECK ((code ~ '^[a-z0-9_-]{3,40}$'::text)),
    CONSTRAINT affiliate_memberships_creator_terms CHECK ((((creator_terms_version IS NULL) = (creator_accepted_at IS NULL)) AND ((creator_terms_version IS NULL) OR public.affiliate_valid_reference(creator_terms_version)))),
    CONSTRAINT affiliate_memberships_display_name_check CHECK (((length(display_name) >= 1) AND (length(display_name) <= 120))),
    CONSTRAINT affiliate_memberships_partner_terms CHECK (((NOT is_partner) OR ((accepted_terms_version IS NOT NULL) AND (accepted_at IS NOT NULL)))),
    CONSTRAINT affiliate_memberships_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'suspended'::text, 'terminated'::text]))),
    CONSTRAINT affiliate_memberships_version_check CHECK ((version > 0))
);


ALTER TABLE public.affiliate_memberships OWNER TO postgres;

--
-- Name: affiliate_apply(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_apply(p_user uuid, p_code text, p_display_name text, p_channel text, p_terms_version text) RETURNS public.affiliate_memberships
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE result public.affiliate_memberships; prog public.affiliate_programs; old public.affiliate_memberships;
BEGIN
 IF (select auth.role()) IS DISTINCT FROM 'service_role' OR p_user IS NULL
  OR ((select auth.uid()) IS NOT NULL AND (select auth.uid())<>p_user)
  OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=p_user AND email_confirmed_at IS NOT NULL) THEN
  RAISE EXCEPTION 'Verified account required' USING ERRCODE='42501'; END IF;
 SELECT * INTO prog FROM public.affiliate_programs FOR SHARE;
 IF NOT prog.enabled OR prog.terms_version IS DISTINCT FROM p_terms_version THEN RAISE EXCEPTION 'Terms changed' USING ERRCODE='PT409'; END IF;
 SELECT * INTO old FROM public.affiliate_memberships WHERE user_id=p_user FOR UPDATE;
 IF old.id IS NOT NULL AND NOT old.is_partner THEN
  UPDATE public.affiliate_memberships SET is_partner=true,status=CASE WHEN old.status='approved' THEN 'pending' ELSE old.status END,
   code=p_code,display_name=p_display_name,channel=p_channel,
   accepted_terms_version=p_terms_version,accepted_at=now(),version=version+1 WHERE id=old.id RETURNING * INTO result;
  INSERT INTO public.affiliate_membership_events(member_id,version,status) VALUES(result.id,result.version,result.status);
  PERFORM public.affiliate_audit('affiliate_memberships',to_jsonb(old),to_jsonb(result),p_user);
  RETURN result;
 END IF;
 INSERT INTO public.affiliate_memberships(user_id,code,display_name,channel,accepted_terms_version,accepted_at)
 VALUES(p_user,p_code,p_display_name,p_channel,p_terms_version,now()) RETURNING * INTO result;
 INSERT INTO public.affiliate_membership_events(member_id,version,status) VALUES(result.id,result.version,result.status);
 PERFORM public.affiliate_audit('affiliate_memberships',NULL,to_jsonb(result),p_user);
 RETURN result;
END $$;


ALTER FUNCTION public.affiliate_apply(p_user uuid, p_code text, p_display_name text, p_channel text, p_terms_version text) OWNER TO postgres;

--
-- Name: affiliate_apply_sync(uuid, uuid, bigint, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_apply_sync(p_payment uuid, p_token uuid, p_generation bigint, p_session_created_at timestamp with time zone, p_livemode boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE pt public.payment_transactions; w public.affiliate_work; b public.affiliate_coupon_bindings;
 prog public.affiliate_programs; rule public.affiliate_rules; cprog public.affiliate_programs; crule public.affiliate_cocreator_rules;
 c public.affiliate_commissions; li record; red public.coupon_redemptions; member_status text;
 base bigint; earned bigint; target bigint; automatic numeric; loss bigint; delta bigint; paid timestamptz;
 self_match boolean; mature timestamptz; waiting boolean:=false; net_missing boolean:=false; blocked boolean:=false; creator_due boolean;
BEGIN
 SELECT * INTO pt FROM public.payment_transactions WHERE id=p_payment FOR UPDATE;
 SELECT * INTO w FROM public.affiliate_work WHERE payment_id=p_payment FOR UPDATE;
 IF w.payment_id IS NULL OR p_token IS NULL OR p_generation IS NULL OR w.status<>'leased' OR w.lease_token IS DISTINCT FROM p_token OR w.leased_until<=now()
  OR p_generation>w.requested_generation OR p_generation<=w.processed_generation THEN RETURN false; END IF;
 IF p_session_created_at IS NULL OR p_session_created_at>now() OR p_livemode IS NULL THEN
  RAISE EXCEPTION 'Session required' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM public.affiliate_commissions WHERE payment_id=p_payment
  AND (session_created_at<>p_session_created_at OR livemode<>p_livemode)) THEN
  RAISE EXCEPTION 'Session differs' USING ERRCODE='23514'; END IF;
 SELECT * INTO red FROM public.coupon_redemptions WHERE transaction_id=p_payment ORDER BY redeemed_at,id LIMIT 1;
 IF red.id IS NOT NULL THEN
  SELECT * INTO b FROM public.affiliate_coupon_bindings WHERE coupon_id=red.coupon_id
   AND created_at<=p_session_created_at AND (retired_at IS NULL OR retired_at>p_session_created_at) ORDER BY version DESC LIMIT 1;
 END IF;
 IF b.id IS NOT NULL THEN
  PERFORM pg_advisory_xact_lock(hashtextextended(b.member_id::text||upper(pt.currency),0));
  SELECT v.program_id,true,v.enabled,v.version,v.hold_days,v.buffer_days,v.terms_version,v.terms,v.thresholds
   INTO prog FROM public.affiliate_program_versions v WHERE v.created_at<=p_session_created_at
   ORDER BY v.created_at DESC,v.version DESC LIMIT 1;
  SELECT e.status INTO member_status FROM public.affiliate_membership_events e
   WHERE e.member_id=b.member_id AND e.created_at<=p_session_created_at ORDER BY e.created_at DESC,e.version DESC LIMIT 1;
  IF prog.id IS NULL OR member_status IS NULL THEN
   UPDATE public.affiliate_work SET status='needs_review',lease_token=NULL,leased_until=NULL,last_error_code='history_unavailable'
    WHERE payment_id=p_payment;
   RETURN false;
  END IF;
 END IF;
 IF pt.amount<>trunc(pt.amount) OR coalesce(pt.refunded_amount,0)<>trunc(coalesce(pt.refunded_amount,0)) THEN
  RAISE EXCEPTION 'Integer amounts required' USING ERRCODE='23514'; END IF;
 -- Existing corrections remain processable while new lines await fulfillment.
 FOR c IN SELECT * FROM public.affiliate_commissions WHERE payment_id=p_payment ORDER BY member_id,currency,id FOR UPDATE LOOP
  PERFORM pg_advisory_xact_lock(hashtextextended(c.member_id::text||c.currency,0));
  blocked:=c.dispute_seen OR w.dispute_seen OR pt.status='disputed';
  loss:=CASE WHEN c.base_minor=0 THEN 0 ELSE round(c.base_minor::numeric*least(pt.amount,greatest(0,coalesce(pt.refunded_amount,0)))/pt.amount)::bigint END;
  target:=CASE WHEN blocked OR c.base_minor=0 THEN 0 ELSE greatest(0,c.accrued_minor-round(c.accrued_minor::numeric*loss/c.base_minor)::bigint) END;
  SELECT coalesce(sum(amount_minor),0) INTO automatic FROM public.affiliate_ledger WHERE commission_id=c.id AND kind<>'manual_adjustment';
  delta:=target-automatic;
  IF delta<>0 THEN
   INSERT INTO public.affiliate_ledger(member_id,commission_id,kind,amount_minor,currency,economic_key)
    VALUES(c.member_id,c.id,CASE WHEN delta>0 THEN 'restoration' ELSE 'reversal' END,delta,c.currency,'sync:'||c.id||':'||p_generation);
  END IF;
  UPDATE public.affiliate_commissions SET observed_refunded_gross=coalesce(pt.refunded_amount,0)::bigint,observed_status=pt.status,
   dispute_seen=blocked,version=version+1 WHERE id=c.id;
  PERFORM public.affiliate_audit('affiliate_commissions',to_jsonb(c),(SELECT to_jsonb(updated) FROM public.affiliate_commissions updated WHERE id=c.id),NULL);
 END LOOP;
 IF b.id IS NOT NULL AND prog.enabled AND member_status='approved' AND pt.status IN ('completed','refunded','disputed') THEN
  SELECT EXISTS(SELECT 1 FROM public.affiliate_memberships am JOIN auth.users u ON u.id=am.user_id
   WHERE am.id=b.member_id AND (u.id=pt.user_id OR lower(btrim(u.email))=lower(btrim(pt.customer_email)))) INTO self_match;
  waiting:=pt.fulfillment_pending;
  net_missing:=NOT waiting AND EXISTS(
   SELECT 1 FROM public.payment_line_items l JOIN public.products p ON p.id=l.product_id
   CROSS JOIN LATERAL (SELECT r.enabled,r.currency FROM public.affiliate_rules r
    WHERE r.product_id=l.product_id AND r.created_at<=p_session_created_at ORDER BY r.created_at DESC,r.revision DESC LIMIT 1) r
   WHERE l.transaction_id=p_payment AND p.product_type='one_time' AND r.enabled
    AND (r.currency IS NULL OR r.currency=upper(l.currency)) AND l.net_amount IS NULL);
  IF NOT waiting AND NOT net_missing THEN
   FOR li IN SELECT l.*,p.is_refundable,p.refund_period_days,p.product_type FROM public.payment_line_items l
    JOIN public.products p ON p.id=l.product_id WHERE l.transaction_id=p_payment ORDER BY l.id LOOP
    IF li.product_type<>'one_time' THEN CONTINUE; END IF;
    SELECT * INTO rule FROM public.affiliate_rules WHERE product_id=li.product_id AND created_at<=p_session_created_at
     ORDER BY created_at DESC,revision DESC LIMIT 1;
    IF rule.id IS NULL OR NOT rule.enabled OR (rule.currency IS NOT NULL AND rule.currency<>upper(li.currency)) THEN CONTINUE; END IF;
    IF EXISTS(SELECT 1 FROM public.affiliate_commissions WHERE payment_id=p_payment AND line_item_id=li.id AND livemode=p_livemode AND kind='referral') THEN CONTINUE; END IF;
    base:=li.net_amount;
    earned:=CASE WHEN self_match THEN 0 WHEN rule.percentage_bps IS NOT NULL THEN round(base::numeric*rule.percentage_bps/10000)::bigint ELSE least(base,rule.fixed_minor) END;
    mature:=CASE WHEN li.is_refundable AND li.refund_period_days IS NULL THEN NULL ELSE
     red.redeemed_at+greatest(prog.hold_days,CASE WHEN li.is_refundable THEN li.refund_period_days+prog.buffer_days ELSE 0 END)*interval '1 day' END;
    INSERT INTO public.affiliate_commissions(payment_id,line_item_id,member_id,rule_id,binding_id,livemode,session_created_at,paid_at,
     currency,base_minor,accrued_minor,self_referral,is_refundable,refund_period_days,hold_days,buffer_days,eligible_at,observed_refunded_gross,observed_status,dispute_seen)
    VALUES(p_payment,li.id,b.member_id,rule.id,b.id,p_livemode,p_session_created_at,red.redeemed_at,upper(li.currency),base,earned,self_match,
     li.is_refundable,li.refund_period_days,prog.hold_days,prog.buffer_days,mature,coalesce(pt.refunded_amount,0)::bigint,pt.status,w.dispute_seen OR pt.status='disputed') RETURNING * INTO c;
    PERFORM public.affiliate_audit('affiliate_commissions',NULL,to_jsonb(c),NULL);
    IF earned>0 THEN
     INSERT INTO public.affiliate_ledger(member_id,commission_id,kind,amount_minor,currency,economic_key)
     VALUES(c.member_id,c.id,'accrual',earned,c.currency,'accrual:'||c.id);
     loss:=CASE WHEN base=0 THEN 0 ELSE round(base::numeric*least(pt.amount,greatest(0,coalesce(pt.refunded_amount,0)))/pt.amount)::bigint END;
     target:=CASE WHEN c.dispute_seen THEN 0 ELSE greatest(0,earned-round(earned::numeric*loss/base)::bigint) END;
     IF target<earned THEN
      INSERT INTO public.affiliate_ledger(member_id,commission_id,kind,amount_minor,currency,economic_key)
      VALUES(c.member_id,c.id,'reversal',target-earned,c.currency,'sync:'||c.id||':'||p_generation);
     END IF;
    END IF;
   END LOOP;
  END IF;
 ELSIF b.id IS NOT NULL AND pt.status NOT IN ('completed','refunded','disputed') THEN waiting:=true;
 END IF;
 -- Co-creator shares: no coupon; the rule in force when the checkout session started (never retroactive).
 -- Unpaid orders and pending fulfilment are queued again by the payment change itself.
 SELECT EXISTS(SELECT 1 FROM public.payment_line_items l JOIN public.products p ON p.id=l.product_id
  CROSS JOIN LATERAL (SELECT r.member_id,r.currency FROM public.affiliate_cocreator_rules r
   WHERE r.product_id=l.product_id AND r.created_at<=p_session_created_at ORDER BY r.created_at DESC,r.revision DESC LIMIT 1) r
  WHERE l.transaction_id=p_payment AND p.product_type='one_time' AND r.member_id IS NOT NULL
   AND (r.currency IS NULL OR r.currency=upper(l.currency))
   AND NOT EXISTS(SELECT 1 FROM public.affiliate_commissions x WHERE x.payment_id=p_payment AND x.line_item_id=l.id AND x.livemode=p_livemode AND x.kind='cocreator'))
  INTO creator_due;
 IF creator_due AND NOT waiting AND NOT net_missing AND pt.status IN ('completed','refunded','disputed') AND NOT pt.fulfillment_pending THEN
  net_missing:=EXISTS(SELECT 1 FROM public.payment_line_items l JOIN public.products p ON p.id=l.product_id
   CROSS JOIN LATERAL (SELECT r.member_id,r.currency FROM public.affiliate_cocreator_rules r
    WHERE r.product_id=l.product_id AND r.created_at<=p_session_created_at ORDER BY r.created_at DESC,r.revision DESC LIMIT 1) r
   WHERE l.transaction_id=p_payment AND p.product_type='one_time' AND r.member_id IS NOT NULL
    AND (r.currency IS NULL OR r.currency=upper(l.currency)) AND l.net_amount IS NULL);
  IF NOT net_missing THEN
   SELECT v.program_id,true,v.enabled,v.version,v.hold_days,v.buffer_days,v.terms_version,v.terms,v.thresholds
    INTO cprog FROM public.affiliate_program_versions v WHERE v.created_at<=p_session_created_at
    ORDER BY v.created_at DESC,v.version DESC LIMIT 1;
   IF cprog.id IS NULL THEN
    UPDATE public.affiliate_work SET status='needs_review',lease_token=NULL,leased_until=NULL,last_error_code='history_unavailable'
     WHERE payment_id=p_payment;
    RETURN false;
   END IF;
   paid:=coalesce(red.redeemed_at,pt.paid_at,pt.created_at);
   FOR li IN SELECT l.*,p.is_refundable,p.refund_period_days,p.product_type FROM public.payment_line_items l
    JOIN public.products p ON p.id=l.product_id WHERE l.transaction_id=p_payment ORDER BY l.id LOOP
    IF li.product_type<>'one_time' THEN CONTINUE; END IF;
    crule:=NULL;
    SELECT * INTO crule FROM public.affiliate_cocreator_rules WHERE product_id=li.product_id AND created_at<=p_session_created_at
     ORDER BY created_at DESC,revision DESC LIMIT 1;
    IF crule.id IS NULL OR crule.member_id IS NULL OR (crule.currency IS NOT NULL AND crule.currency<>upper(li.currency)) THEN CONTINUE; END IF;
    IF EXISTS(SELECT 1 FROM public.affiliate_commissions WHERE payment_id=p_payment AND line_item_id=li.id AND livemode=p_livemode AND kind='cocreator') THEN CONTINUE; END IF;
    member_status:=NULL;
    SELECT e.status INTO member_status FROM public.affiliate_membership_events e
     WHERE e.member_id=crule.member_id AND e.created_at<=p_session_created_at ORDER BY e.created_at DESC,e.version DESC LIMIT 1;
    -- 'pending' here only means a co-creator's own partner application awaits the seller: shares keep accruing.
    IF member_status IS NULL OR member_status NOT IN ('approved','pending') THEN CONTINUE; END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended(crule.member_id::text||upper(li.currency),0));
    SELECT EXISTS(SELECT 1 FROM public.affiliate_memberships am JOIN auth.users u ON u.id=am.user_id
     WHERE am.id=crule.member_id AND (u.id=pt.user_id OR lower(btrim(u.email))=lower(btrim(pt.customer_email)))) INTO self_match;
    base:=li.net_amount;
    earned:=CASE WHEN self_match THEN 0 WHEN crule.percentage_bps IS NOT NULL THEN round(base::numeric*crule.percentage_bps/10000)::bigint ELSE least(base,crule.fixed_minor) END;
    mature:=CASE WHEN li.is_refundable AND li.refund_period_days IS NULL THEN NULL ELSE
     paid+greatest(cprog.hold_days,CASE WHEN li.is_refundable THEN li.refund_period_days+cprog.buffer_days ELSE 0 END)*interval '1 day' END;
    INSERT INTO public.affiliate_commissions(payment_id,line_item_id,member_id,kind,cocreator_rule_id,livemode,session_created_at,paid_at,
     currency,base_minor,accrued_minor,self_referral,is_refundable,refund_period_days,hold_days,buffer_days,eligible_at,observed_refunded_gross,observed_status,dispute_seen)
    VALUES(p_payment,li.id,crule.member_id,'cocreator',crule.id,p_livemode,p_session_created_at,paid,upper(li.currency),base,earned,self_match,
     li.is_refundable,li.refund_period_days,cprog.hold_days,cprog.buffer_days,mature,coalesce(pt.refunded_amount,0)::bigint,pt.status,w.dispute_seen OR pt.status='disputed') RETURNING * INTO c;
    PERFORM public.affiliate_audit('affiliate_commissions',NULL,to_jsonb(c),NULL);
    IF earned>0 THEN
     INSERT INTO public.affiliate_ledger(member_id,commission_id,kind,amount_minor,currency,economic_key)
     VALUES(c.member_id,c.id,'accrual',earned,c.currency,'accrual:'||c.id);
     loss:=CASE WHEN base=0 THEN 0 ELSE round(base::numeric*least(pt.amount,greatest(0,coalesce(pt.refunded_amount,0)))/pt.amount)::bigint END;
     target:=CASE WHEN c.dispute_seen THEN 0 ELSE greatest(0,earned-round(earned::numeric*loss/base)::bigint) END;
     IF target<earned THEN
      INSERT INTO public.affiliate_ledger(member_id,commission_id,kind,amount_minor,currency,economic_key)
      VALUES(c.member_id,c.id,'reversal',target-earned,c.currency,'sync:'||c.id||':'||p_generation);
     END IF;
    END IF;
   END LOOP;
  END IF;
 END IF;
 UPDATE public.affiliate_work SET processed_generation=CASE WHEN waiting OR net_missing THEN processed_generation ELSE p_generation END,
  status=CASE WHEN net_missing THEN 'needs_review' WHEN waiting OR requested_generation>p_generation THEN 'pending' ELSE 'done' END,
  next_attempt_at=CASE WHEN waiting THEN now()+interval '1 minute' ELSE now() END,
  lease_token=NULL,leased_until=NULL,last_error_code=CASE WHEN net_missing THEN 'net_unavailable' WHEN waiting THEN 'awaiting_fulfillment' ELSE NULL END,
  attempts=CASE WHEN waiting OR net_missing THEN attempts ELSE 0 END
 WHERE payment_id=p_payment;
 RETURN NOT waiting AND NOT net_missing;
END $$;


ALTER FUNCTION public.affiliate_apply_sync(p_payment uuid, p_token uuid, p_generation bigint, p_session_created_at timestamp with time zone, p_livemode boolean) OWNER TO postgres;

--
-- Name: affiliate_audit(text, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_audit(p_table text, p_old jsonb, p_new jsonb, p_actor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 INSERT INTO public.audit_log(table_name,operation,old_values,new_values,performed_by)
 VALUES(p_table,CASE WHEN p_old IS NULL THEN 'INSERT' ELSE 'UPDATE' END,p_old,p_new,p_actor);
END $$;


ALTER FUNCTION public.affiliate_audit(p_table text, p_old jsonb, p_new jsonb, p_actor uuid) OWNER TO postgres;

--
-- Name: affiliate_binding_check(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_binding_check() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 PERFORM 1 FROM public.coupons WHERE id=NEW.coupon_id FOR UPDATE;
 IF TG_OP='INSERT' AND NOT EXISTS(SELECT 1 FROM public.affiliate_memberships WHERE id=NEW.member_id AND status='approved' AND is_partner AND user_id IS NOT NULL) THEN
  RAISE EXCEPTION 'Approved member required' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM public.affiliate_coupon_bindings b WHERE b.coupon_id=NEW.coupon_id AND b.id<>NEW.id
  AND tstzrange(b.created_at,b.retired_at,'[)') && tstzrange(NEW.created_at,NEW.retired_at,'[)')) THEN
  RAISE EXCEPTION 'Binding periods overlap' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION public.affiliate_binding_check() OWNER TO postgres;

--
-- Name: affiliate_payouts; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.affiliate_payouts (
    livemode boolean DEFAULT true NOT NULL,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    member_id uuid NOT NULL,
    currency text NOT NULL,
    earnings_minor bigint NOT NULL,
    status text NOT NULL,
    needs_review boolean DEFAULT false NOT NULL,
    version bigint DEFAULT 1 NOT NULL,
    cutoff timestamp with time zone NOT NULL,
    payee_reference text NOT NULL,
    bank_reference text,
    invoice_reference text,
    bank_amount_minor bigint,
    paid_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT affiliate_payouts_bank_amount_minor_check CHECK ((bank_amount_minor > 0)),
    CONSTRAINT affiliate_payouts_bank_reference_check CHECK (((bank_reference IS NULL) OR public.affiliate_valid_reference(bank_reference))),
    CONSTRAINT affiliate_payouts_check CHECK (((status <> 'paid'::text) OR ((bank_reference IS NOT NULL) AND (invoice_reference IS NOT NULL) AND (bank_amount_minor IS NOT NULL) AND (paid_at IS NOT NULL)))),
    CONSTRAINT affiliate_payouts_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT affiliate_payouts_earnings_minor_check CHECK ((earnings_minor > 0)),
    CONSTRAINT affiliate_payouts_invoice_reference_check CHECK (((invoice_reference IS NULL) OR public.affiliate_valid_reference(invoice_reference))),
    CONSTRAINT affiliate_payouts_payee_reference_check CHECK (public.affiliate_valid_reference(payee_reference)),
    CONSTRAINT affiliate_payouts_status_check CHECK ((status = ANY (ARRAY['reserved'::text, 'paid'::text, 'cancelled'::text]))),
    CONSTRAINT affiliate_payouts_version_check CHECK ((version > 0))
);


ALTER TABLE public.affiliate_payouts OWNER TO postgres;

--
-- Name: affiliate_cancel_payout(uuid, uuid, bigint, boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_cancel_payout(p_actor uuid, p_payout uuid, p_expected_version bigint, p_no_transfer boolean, p_reason text) RETURNS public.affiliate_payouts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE old public.affiliate_payouts; result public.affiliate_payouts;
BEGIN
 PERFORM public.affiliate_admin(p_actor);
 SELECT * INTO old FROM public.affiliate_payouts WHERE id=p_payout;
 PERFORM public.affiliate_lock_member(old.member_id,old.currency,ARRAY(
  SELECT DISTINCT c.payment_id FROM public.affiliate_payout_allocations a JOIN public.affiliate_ledger l ON l.id=a.entry_id
   JOIN public.affiliate_commissions c ON c.id=l.commission_id WHERE a.payout_id=old.id AND a.released_at IS NULL),old.livemode);
 SELECT * INTO old FROM public.affiliate_payouts WHERE id=p_payout FOR UPDATE;
 IF old.id IS NULL OR old.version IS DISTINCT FROM p_expected_version OR old.status<>'reserved' THEN RAISE EXCEPTION 'Version changed' USING ERRCODE='PT409'; END IF;
 IF p_no_transfer IS DISTINCT FROM true OR NOT public.affiliate_valid_reference(p_reason) THEN RAISE EXCEPTION 'Confirmation required' USING ERRCODE='22023'; END IF;
 UPDATE public.affiliate_payouts SET status='cancelled',version=version+1 WHERE id=p_payout RETURNING * INTO result;
 UPDATE public.affiliate_payout_allocations SET released_at=now() WHERE payout_id=p_payout AND released_at IS NULL;
 PERFORM public.affiliate_audit('affiliate_payouts',to_jsonb(old),to_jsonb(result)||jsonb_build_object('reason',p_reason),p_actor);
 RETURN result;
END $$;


ALTER FUNCTION public.affiliate_cancel_payout(p_actor uuid, p_payout uuid, p_expected_version bigint, p_no_transfer boolean, p_reason text) OWNER TO postgres;

--
-- Name: affiliate_check_relations(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_check_relations() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE c public.affiliate_commissions; p public.affiliate_payouts; l public.affiliate_ledger; total numeric;
BEGIN
 IF TG_TABLE_NAME='affiliate_commissions' THEN
  SELECT * INTO c FROM public.affiliate_commissions WHERE id=NEW.id;
  IF c.kind='cocreator' THEN
   IF NOT EXISTS(SELECT 1 FROM public.payment_line_items li JOIN public.affiliate_cocreator_rules r ON r.id=c.cocreator_rule_id
    JOIN public.payment_transactions pt ON pt.id=c.payment_id
    WHERE li.id=c.line_item_id AND li.transaction_id=c.payment_id AND li.product_id=r.product_id
     AND upper(li.currency)=c.currency AND upper(pt.currency)=c.currency AND r.member_id=c.member_id) THEN
    RAISE EXCEPTION 'Commission references differ' USING ERRCODE='23514'; END IF;
  ELSIF NOT EXISTS(SELECT 1 FROM public.payment_line_items li JOIN public.affiliate_rules r ON r.id=c.rule_id
   JOIN public.affiliate_coupon_bindings b ON b.id=c.binding_id
   JOIN public.payment_transactions pt ON pt.id=c.payment_id
   WHERE li.id=c.line_item_id AND li.transaction_id=c.payment_id AND li.product_id=r.product_id
    AND upper(li.currency)=c.currency AND upper(pt.currency)=c.currency AND b.member_id=c.member_id) THEN
   RAISE EXCEPTION 'Commission references differ' USING ERRCODE='23514'; END IF;
 ELSIF TG_TABLE_NAME='affiliate_ledger' THEN
  SELECT * INTO l FROM public.affiliate_ledger WHERE id=NEW.id;
  IF l.commission_id IS NOT NULL THEN
   SELECT * INTO c FROM public.affiliate_commissions WHERE id=l.commission_id;
   IF l.member_id<>c.member_id OR l.currency<>c.currency OR (l.kind='accrual' AND l.amount_minor<>c.accrued_minor) THEN RAISE EXCEPTION 'Entry references differ' USING ERRCODE='23514'; END IF;
   SELECT coalesce(sum(amount_minor),0) INTO total FROM public.affiliate_ledger WHERE commission_id=c.id AND kind<>'manual_adjustment';
   IF total<0 OR total>c.accrued_minor THEN RAISE EXCEPTION 'Automatic total outside commission' USING ERRCODE='23514'; END IF;
   IF c.dispute_seen AND (SELECT coalesce(sum(amount_minor),0) FROM public.affiliate_ledger WHERE commission_id=c.id AND kind='manual_adjustment')>c.accrued_minor THEN
    RAISE EXCEPTION 'Adjustment outside commission' USING ERRCODE='23514'; END IF;
  ELSE
   SELECT * INTO p FROM public.affiliate_payouts WHERE id=l.payout_id;
   IF l.member_id<>p.member_id OR l.currency<>p.currency OR l.amount_minor<>-p.earnings_minor OR p.status<>'paid' THEN
    RAISE EXCEPTION 'Settlement differs' USING ERRCODE='23514'; END IF;
  END IF;
 ELSIF TG_TABLE_NAME='affiliate_payouts' THEN
  SELECT * INTO p FROM public.affiliate_payouts WHERE id=NEW.id;
 ELSE
  SELECT * INTO p FROM public.affiliate_payouts WHERE id=NEW.payout_id;
 END IF;
 IF p.id IS NOT NULL THEN
  IF EXISTS(SELECT 1 FROM public.affiliate_payout_allocations a JOIN public.affiliate_ledger e ON e.id=a.entry_id
    WHERE a.payout_id=p.id AND (e.member_id<>p.member_id OR e.currency<>p.currency OR e.kind='settlement' OR NOT EXISTS(SELECT 1 FROM public.affiliate_commissions comm WHERE comm.id=e.commission_id AND comm.livemode=p.livemode)))
   OR (SELECT coalesce(sum(e.amount_minor),0) FROM public.affiliate_payout_allocations a JOIN public.affiliate_ledger e ON e.id=a.entry_id
    WHERE a.payout_id=p.id AND a.released_at IS NULL)<>(CASE WHEN p.status='cancelled' THEN 0 ELSE p.earnings_minor END)
   OR (p.status='paid' AND NOT EXISTS(SELECT 1 FROM public.affiliate_ledger WHERE payout_id=p.id)) THEN
   RAISE EXCEPTION 'Payout allocation differs' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION public.affiliate_check_relations() OWNER TO postgres;

--
-- Name: affiliate_work; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.affiliate_work (
    payment_id uuid NOT NULL,
    kind text DEFAULT 'sync'::text NOT NULL,
    requested_generation bigint DEFAULT 1 NOT NULL,
    processed_generation bigint DEFAULT 0 NOT NULL,
    dispute_seen boolean DEFAULT false NOT NULL,
    status text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    next_attempt_at timestamp with time zone DEFAULT now() NOT NULL,
    leased_until timestamp with time zone,
    lease_token uuid,
    last_error_code text,
    CONSTRAINT affiliate_work_attempts_check CHECK ((attempts >= 0)),
    CONSTRAINT affiliate_work_check CHECK (((processed_generation >= 0) AND (requested_generation >= processed_generation))),
    CONSTRAINT affiliate_work_check1 CHECK (((status = 'leased'::text) = ((lease_token IS NOT NULL) AND (leased_until IS NOT NULL)))),
    CONSTRAINT affiliate_work_check2 CHECK (((requested_generation > 0) AND ((status <> 'done'::text) OR (requested_generation = processed_generation)))),
    CONSTRAINT affiliate_work_kind_check CHECK ((kind = 'sync'::text)),
    CONSTRAINT affiliate_work_last_error_code_check CHECK (((last_error_code IS NULL) OR (last_error_code ~ '^[a-z0-9_]{1,80}$'::text))),
    CONSTRAINT affiliate_work_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'leased'::text, 'done'::text, 'needs_review'::text])))
);


ALTER TABLE public.affiliate_work OWNER TO postgres;

--
-- Name: affiliate_claim_work(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_claim_work(p_limit integer DEFAULT 25) RETURNS SETOF public.affiliate_work
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Invalid limit' USING ERRCODE='22023'; END IF;
 RETURN QUERY WITH due AS (
 SELECT payment_id FROM public.affiliate_work WHERE
 (status='pending' AND next_attempt_at<=now()) OR (status='leased' AND leased_until<=now())
 ORDER BY next_attempt_at,payment_id FOR UPDATE SKIP LOCKED LIMIT p_limit)
 UPDATE public.affiliate_work w SET status='leased',lease_token=gen_random_uuid(),leased_until=now()+interval '5 minutes',attempts=attempts+1
 FROM due WHERE w.payment_id=due.payment_id RETURNING w.*;
END $$;


ALTER FUNCTION public.affiliate_claim_work(p_limit integer) OWNER TO postgres;

--
-- Name: affiliate_cocreator_candidate(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_cocreator_candidate(p_payment uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT EXISTS(SELECT 1 FROM public.payment_line_items l JOIN public.products p ON p.id = l.product_id
    WHERE l.transaction_id = p_payment AND p.product_type = 'one_time'
      AND EXISTS(SELECT 1 FROM public.affiliate_cocreator_rules r WHERE r.product_id = l.product_id AND r.member_id IS NOT NULL));
$$;


ALTER FUNCTION public.affiliate_cocreator_candidate(p_payment uuid) OWNER TO postgres;

--
-- Name: affiliate_cocreator_rules; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.affiliate_cocreator_rules (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    product_id uuid NOT NULL,
    revision integer NOT NULL,
    member_id uuid,
    percentage_bps integer,
    fixed_minor bigint,
    currency text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT affiliate_cocreator_rules_check CHECK ((((member_id IS NULL) AND (percentage_bps IS NULL) AND (fixed_minor IS NULL) AND (currency IS NULL)) OR ((member_id IS NOT NULL) AND (((percentage_bps IS NOT NULL) AND (fixed_minor IS NULL) AND (currency IS NULL)) OR ((percentage_bps IS NULL) AND (fixed_minor IS NOT NULL) AND (currency IS NOT NULL)))))),
    CONSTRAINT affiliate_cocreator_rules_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT affiliate_cocreator_rules_fixed_minor_check CHECK ((fixed_minor > 0)),
    CONSTRAINT affiliate_cocreator_rules_percentage_bps_check CHECK (((percentage_bps >= 1) AND (percentage_bps <= 10000))),
    CONSTRAINT affiliate_cocreator_rules_revision_check CHECK ((revision > 0))
);


ALTER TABLE public.affiliate_cocreator_rules OWNER TO postgres;

--
-- Name: affiliate_cocreator_set(uuid, uuid, integer, text, text, integer, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_cocreator_set(p_actor uuid, p_product uuid, p_expected_revision integer, p_email text, p_display_name text, p_percentage_bps integer, p_fixed_minor bigint, p_currency text) RETURNS public.affiliate_cocreator_rules
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE result public.affiliate_cocreator_rules; revision integer; target uuid; m public.affiliate_memberships;
BEGIN
 PERFORM public.affiliate_admin(p_actor);
 PERFORM 1 FROM public.products WHERE id=p_product AND product_type='one_time' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'One-time product required' USING ERRCODE='22023'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.affiliate_programs) THEN RAISE EXCEPTION 'Program settings required' USING ERRCODE='22023'; END IF;
 SELECT coalesce(max(r.revision),0) INTO revision FROM public.affiliate_cocreator_rules r WHERE r.product_id=p_product;
 IF revision IS DISTINCT FROM p_expected_revision THEN RAISE EXCEPTION 'Revision changed' USING ERRCODE='PT409'; END IF;
 IF p_email IS NOT NULL THEN
  SELECT u.id INTO target FROM auth.users u WHERE lower(btrim(u.email))=lower(btrim(p_email)) AND u.deleted_at IS NULL
   ORDER BY u.created_at LIMIT 1;
  IF target IS NULL THEN RAISE EXCEPTION 'Account required' USING ERRCODE='P0002'; END IF;
  SELECT * INTO m FROM public.affiliate_memberships WHERE user_id=target FOR UPDATE;
  IF m.id IS NULL THEN
   INSERT INTO public.affiliate_memberships(user_id,code,status,display_name,is_partner)
    VALUES(target,'creator-'||replace(target::text,'-',''),'approved',
     left(coalesce(nullif(btrim(p_display_name),''),split_part(btrim(p_email),'@',1)),120),false) RETURNING * INTO m;
   INSERT INTO public.affiliate_membership_events(member_id,version,status) VALUES(m.id,m.version,m.status);
   PERFORM public.affiliate_audit('affiliate_memberships',NULL,to_jsonb(m),p_actor);
  -- The seller's own assignment is the approval of the creator role; a partner application still
  -- awaiting review ('pending') does not block it, a rejected/suspended/terminated membership does.
  ELSIF m.status NOT IN ('approved','pending') THEN RAISE EXCEPTION 'Approved member required' USING ERRCODE='22023';
  END IF;
 ELSIF p_percentage_bps IS NOT NULL OR p_fixed_minor IS NOT NULL OR p_currency IS NOT NULL THEN
  RAISE EXCEPTION 'Person required' USING ERRCODE='22023';
 END IF;
 INSERT INTO public.affiliate_cocreator_rules(product_id,revision,member_id,percentage_bps,fixed_minor,currency)
  VALUES(p_product,revision+1,m.id,p_percentage_bps,p_fixed_minor,p_currency) RETURNING * INTO result;
 PERFORM public.affiliate_audit('affiliate_cocreator_rules',NULL,to_jsonb(result),p_actor);
 RETURN result;
END $$;


ALTER FUNCTION public.affiliate_cocreator_set(p_actor uuid, p_product uuid, p_expected_revision integer, p_email text, p_display_name text, p_percentage_bps integer, p_fixed_minor bigint, p_currency text) OWNER TO postgres;

--
-- Name: affiliate_complete_unbound_work(uuid, uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_complete_unbound_work(p_payment uuid, p_token uuid, p_generation bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 PERFORM 1 FROM public.payment_transactions WHERE id=p_payment FOR UPDATE;
 IF EXISTS(SELECT 1 FROM public.coupon_redemptions r JOIN public.affiliate_coupon_bindings b ON b.coupon_id=r.coupon_id WHERE r.transaction_id=p_payment)
  OR EXISTS(SELECT 1 FROM public.affiliate_commissions WHERE payment_id=p_payment)
  OR public.affiliate_cocreator_candidate(p_payment) THEN RETURN false; END IF;
 UPDATE public.affiliate_work SET processed_generation=p_generation,
  status=CASE WHEN requested_generation>p_generation THEN 'pending' ELSE 'done' END,
  lease_token=NULL,leased_until=NULL,last_error_code=NULL,attempts=0,next_attempt_at=now()
 WHERE payment_id=p_payment AND status='leased' AND lease_token=p_token AND leased_until>now()
  AND p_generation>processed_generation AND p_generation<=requested_generation;
 RETURN FOUND;
END $$;


ALTER FUNCTION public.affiliate_complete_unbound_work(p_payment uuid, p_token uuid, p_generation bigint) OWNER TO postgres;

--
-- Name: affiliate_coupon_bindings; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.affiliate_coupon_bindings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    coupon_id uuid NOT NULL,
    member_id uuid NOT NULL,
    version bigint NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    retired_at timestamp with time zone,
    CONSTRAINT affiliate_coupon_bindings_check CHECK (((retired_at IS NULL) OR (retired_at >= created_at))),
    CONSTRAINT affiliate_coupon_bindings_version_check CHECK ((version > 0))
);


ALTER TABLE public.affiliate_coupon_bindings OWNER TO postgres;

--
-- Name: affiliate_coupon_bind(uuid, uuid, uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_coupon_bind(p_actor uuid, p_coupon uuid, p_member uuid, p_expected_version bigint) RETURNS public.affiliate_coupon_bindings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE old public.affiliate_coupon_bindings; result public.affiliate_coupon_bindings; revision bigint;
BEGIN
 PERFORM public.affiliate_admin(p_actor);
 PERFORM 1 FROM public.coupons WHERE id=p_coupon FOR UPDATE;
 PERFORM 1 FROM public.affiliate_memberships WHERE id=p_member AND status='approved' AND user_id IS NOT NULL FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Approved member required' USING ERRCODE='22023'; END IF;
 SELECT coalesce(max(version),0) INTO revision FROM public.affiliate_coupon_bindings WHERE coupon_id=p_coupon;
 IF revision IS DISTINCT FROM p_expected_version THEN RAISE EXCEPTION 'Version changed' USING ERRCODE='PT409'; END IF;
 SELECT * INTO old FROM public.affiliate_coupon_bindings WHERE coupon_id=p_coupon AND retired_at IS NULL;
 UPDATE public.affiliate_coupon_bindings SET retired_at=now() WHERE id=old.id;
 INSERT INTO public.affiliate_coupon_bindings(coupon_id,member_id,version) VALUES(p_coupon,p_member,revision+1) RETURNING * INTO result;
 PERFORM public.affiliate_audit('affiliate_coupon_bindings',CASE WHEN old.id IS NULL THEN NULL ELSE to_jsonb(old) END,to_jsonb(result),p_actor);
 RETURN result;
END $$;


ALTER FUNCTION public.affiliate_coupon_bind(p_actor uuid, p_coupon uuid, p_member uuid, p_expected_version bigint) OWNER TO postgres;

--
-- Name: affiliate_creator_accept(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_creator_accept(p_user uuid, p_terms_version text) RETURNS public.affiliate_memberships
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE old public.affiliate_memberships; result public.affiliate_memberships; t public.affiliate_creator_terms;
BEGIN
 IF (select auth.role()) IS DISTINCT FROM 'service_role' OR p_user IS NULL
  OR ((select auth.uid()) IS NOT NULL AND (select auth.uid())<>p_user) THEN
  RAISE EXCEPTION 'Account required' USING ERRCODE='42501'; END IF;
 SELECT * INTO old FROM public.affiliate_memberships WHERE user_id=p_user FOR UPDATE;
 IF old.id IS NULL OR NOT EXISTS(SELECT 1 FROM public.affiliate_cocreator_rules WHERE member_id=old.id) THEN
  RAISE EXCEPTION 'Co-creator required' USING ERRCODE='P0002'; END IF;
 SELECT * INTO t FROM public.affiliate_creator_terms ORDER BY id DESC LIMIT 1;
 IF t.id IS NULL OR t.terms_version IS DISTINCT FROM p_terms_version THEN RAISE EXCEPTION 'Terms changed' USING ERRCODE='PT409'; END IF;
 IF old.creator_terms_version=p_terms_version THEN RETURN old; END IF;
 UPDATE public.affiliate_memberships SET creator_terms_version=p_terms_version,creator_accepted_at=now(),version=version+1
  WHERE id=old.id RETURNING * INTO result;
 INSERT INTO public.affiliate_membership_events(member_id,version,status) VALUES(result.id,result.version,result.status);
 PERFORM public.affiliate_audit('affiliate_memberships',to_jsonb(old),to_jsonb(result),p_user);
 RETURN result;
END $$;


ALTER FUNCTION public.affiliate_creator_accept(p_user uuid, p_terms_version text) OWNER TO postgres;

--
-- Name: affiliate_valid_program(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_valid_program(p_terms jsonb, p_thresholds jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
BEGIN
 IF octet_length(p_terms::text)>32768 OR octet_length(p_thresholds::text)>32768
 OR jsonb_typeof(p_terms)<>'object' OR jsonb_typeof(p_thresholds)<>'object'
 OR NOT (p_terms ?& ARRAY['en','pl']) OR (p_terms - ARRAY['en','pl'])<>'{}'::jsonb
 OR jsonb_typeof(p_terms->'en')<>'string' OR jsonb_typeof(p_terms->'pl')<>'string'
 OR length(btrim(p_terms->>'en'))=0 OR length(btrim(p_terms->>'pl'))=0 THEN RETURN false; END IF;
 RETURN NOT EXISTS(SELECT 1 FROM jsonb_each(p_thresholds) t
 WHERE t.key !~ '^[A-Z]{3}$' OR jsonb_typeof(t.value)<>'string' OR t.value#>>'{}' !~ '^[1-9][0-9]{0,18}$'
 OR (t.value#>>'{}')::numeric>9223372036854775807);
END $_$;


ALTER FUNCTION public.affiliate_valid_program(p_terms jsonb, p_thresholds jsonb) OWNER TO postgres;

--
-- Name: affiliate_creator_terms; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.affiliate_creator_terms (
    id bigint NOT NULL,
    terms_version text NOT NULL,
    terms jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT affiliate_creator_terms_terms_check CHECK (public.affiliate_valid_program(terms, '{}'::jsonb)),
    CONSTRAINT affiliate_creator_terms_terms_version_check CHECK (public.affiliate_valid_reference(terms_version))
);


ALTER TABLE public.affiliate_creator_terms OWNER TO postgres;

--
-- Name: affiliate_creator_terms_publish(uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_creator_terms_publish(p_actor uuid, p_expected_version text, p_terms_version text, p_terms jsonb) RETURNS public.affiliate_creator_terms
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE current public.affiliate_creator_terms; result public.affiliate_creator_terms;
BEGIN
 PERFORM public.affiliate_admin(p_actor);
 PERFORM pg_advisory_xact_lock(hashtextextended('affiliate_creator_terms',0));
 SELECT * INTO current FROM public.affiliate_creator_terms ORDER BY id DESC LIMIT 1;
 IF current.terms_version IS DISTINCT FROM p_expected_version THEN RAISE EXCEPTION 'Version changed' USING ERRCODE='PT409'; END IF;
 IF current.terms_version=p_terms_version THEN
  IF current.terms<>p_terms THEN RAISE EXCEPTION 'Terms version changed' USING ERRCODE='PT409'; END IF;
  RETURN current;
 END IF;
 IF EXISTS(SELECT 1 FROM public.affiliate_creator_terms WHERE terms_version=p_terms_version) THEN
  RAISE EXCEPTION 'Terms version changed' USING ERRCODE='PT409'; END IF;
 INSERT INTO public.affiliate_creator_terms(terms_version,terms) VALUES(p_terms_version,p_terms) RETURNING * INTO result;
 PERFORM public.affiliate_audit('affiliate_creator_terms',NULL,to_jsonb(result),p_actor);
 RETURN result;
END $$;


ALTER FUNCTION public.affiliate_creator_terms_publish(p_actor uuid, p_expected_version text, p_terms_version text, p_terms jsonb) OWNER TO postgres;

--
-- Name: affiliate_enqueue(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_enqueue() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE pid uuid; disputed boolean;
BEGIN
 IF TG_TABLE_NAME='coupon_redemptions' THEN
  pid:=NEW.transaction_id;
  IF NOT EXISTS(SELECT 1 FROM public.affiliate_coupon_bindings WHERE coupon_id=NEW.coupon_id) THEN RETURN NEW; END IF;
 ELSIF TG_TABLE_NAME='payment_line_items' THEN
  pid:=NEW.transaction_id;
  -- Unpaid orders are queued later by the payment status change.
  IF NOT EXISTS(SELECT 1 FROM public.payment_transactions WHERE id=pid AND status IN ('completed','refunded','disputed'))
   OR NOT EXISTS(SELECT 1 FROM public.products p WHERE p.id=NEW.product_id AND p.product_type='one_time'
    AND EXISTS(SELECT 1 FROM public.affiliate_cocreator_rules r WHERE r.product_id=p.id AND r.member_id IS NOT NULL)) THEN RETURN NEW; END IF;
 ELSE
  IF NEW.status IS NOT DISTINCT FROM OLD.status AND NEW.refunded_amount IS NOT DISTINCT FROM OLD.refunded_amount
    AND NEW.fulfillment_pending IS NOT DISTINCT FROM OLD.fulfillment_pending THEN RETURN NEW; END IF;
  pid:=NEW.id;
  IF NOT EXISTS(SELECT 1 FROM public.coupon_redemptions r JOIN public.affiliate_coupon_bindings b ON b.coupon_id=r.coupon_id WHERE r.transaction_id=pid)
   AND NOT EXISTS(SELECT 1 FROM public.affiliate_commissions WHERE payment_id=pid)
   AND NOT public.affiliate_cocreator_candidate(pid) THEN RETURN NEW; END IF;
 END IF;
 IF pid IS NULL THEN RETURN NEW; END IF;
 SELECT status='disputed' INTO disputed FROM public.payment_transactions WHERE id=pid;
 INSERT INTO public.affiliate_work(payment_id,status,dispute_seen) VALUES(pid,'pending',disputed)
 ON CONFLICT(payment_id) DO UPDATE SET requested_generation=public.affiliate_work.requested_generation+1,
  dispute_seen=public.affiliate_work.dispute_seen OR excluded.dispute_seen,
  status=CASE WHEN public.affiliate_work.status='leased' THEN 'leased' ELSE 'pending' END,next_attempt_at=now();
 UPDATE public.affiliate_payouts p SET needs_review=true,version=version+1
 WHERE p.status='reserved' AND NOT p.needs_review AND EXISTS(
  SELECT 1 FROM public.affiliate_payout_allocations a JOIN public.affiliate_ledger l ON l.id=a.entry_id
  JOIN public.affiliate_commissions c ON c.id=l.commission_id
  WHERE a.payout_id=p.id AND c.payment_id=pid AND a.released_at IS NULL);
 RETURN NEW;
END $$;


ALTER FUNCTION public.affiliate_enqueue() OWNER TO postgres;

--
-- Name: affiliate_entry_eligible(text, bigint, boolean, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_entry_eligible(p_kind text, p_amount bigint, p_previously_paid boolean, p_ready boolean, p_referral_ok boolean, p_creator_ok boolean) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 SELECT (p_amount<0 AND p_previously_paid) OR (p_ready AND CASE WHEN p_kind='cocreator' THEN p_creator_ok ELSE p_referral_ok END)
$$;


ALTER FUNCTION public.affiliate_entry_eligible(p_kind text, p_amount bigint, p_previously_paid boolean, p_ready boolean, p_referral_ok boolean, p_creator_ok boolean) OWNER TO postgres;

--
-- Name: affiliate_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF TG_TABLE_NAME='affiliate_coupon_bindings' THEN
  IF (to_jsonb(NEW)-'retired_at')<>(to_jsonb(OLD)-'retired_at') OR OLD.retired_at IS NOT NULL OR NEW.retired_at IS NULL THEN
   RAISE EXCEPTION 'Binding already fixed' USING ERRCODE='23514'; END IF;
 ELSIF TG_TABLE_NAME='affiliate_commissions' THEN
  IF (to_jsonb(NEW)-ARRAY['observed_refunded_gross','observed_status','dispute_seen','dispute_reviewed_at','hold_days','eligible_at','version'])
   <>(to_jsonb(OLD)-ARRAY['observed_refunded_gross','observed_status','dispute_seen','dispute_reviewed_at','hold_days','eligible_at','version'])
   OR NEW.hold_days<OLD.hold_days OR (OLD.dispute_seen AND NOT NEW.dispute_seen)
   OR (OLD.eligible_at IS NULL AND NEW.eligible_at IS NOT NULL)
   OR NEW.eligible_at<OLD.eligible_at OR (OLD.dispute_reviewed_at IS NOT NULL AND NEW.dispute_reviewed_at IS NULL) OR NEW.version<>OLD.version+1 THEN
   RAISE EXCEPTION 'Commission snapshot fixed' USING ERRCODE='23514'; END IF;
 ELSIF TG_TABLE_NAME='affiliate_work' THEN
  IF EXISTS(SELECT 1 FROM public.affiliate_commissions WHERE payment_id=OLD.payment_id)
   AND (OLD.status<>'done' OR OLD.requested_generation<>OLD.processed_generation OR OLD.dispute_seen) THEN
   RAISE EXCEPTION 'Work remains due' USING ERRCODE='23514'; END IF;
 ELSIF TG_TABLE_NAME='affiliate_payout_allocations' THEN
  IF NEW.payout_id<>OLD.payout_id OR NEW.entry_id<>OLD.entry_id OR OLD.released_at IS NOT NULL
   OR NEW.released_at IS NULL OR NOT EXISTS(SELECT 1 FROM public.affiliate_payouts WHERE id=NEW.payout_id AND status='cancelled') THEN
   RAISE EXCEPTION 'Allocation remains reserved' USING ERRCODE='23514'; END IF;
 ELSIF TG_TABLE_NAME='affiliate_payouts' THEN
  IF OLD.status<>'reserved' OR (to_jsonb(NEW)-ARRAY['status','needs_review','version','bank_reference','invoice_reference','bank_amount_minor','paid_at'])
   <>(to_jsonb(OLD)-ARRAY['status','needs_review','version','bank_reference','invoice_reference','bank_amount_minor','paid_at']) OR NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'Payout fixed' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$;


ALTER FUNCTION public.affiliate_guard() OWNER TO postgres;

--
-- Name: affiliate_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN RAISE EXCEPTION 'Append only record' USING ERRCODE='23514'; END $$;


ALTER FUNCTION public.affiliate_immutable() OWNER TO postgres;

--
-- Name: affiliate_lock_member(uuid, text, uuid[], boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_lock_member(p_member uuid, p_currency text, p_payments uuid[] DEFAULT '{}'::uuid[], p_livemode boolean DEFAULT true) RETURNS uuid[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE locked uuid[];
BEGIN
 SELECT coalesce(array_agg(id),'{}'::uuid[]) INTO locked FROM (
  SELECT pt.id FROM public.payment_transactions pt WHERE pt.id=ANY(p_payments)
   OR EXISTS(SELECT 1 FROM public.affiliate_commissions c JOIN public.affiliate_work w ON w.payment_id=c.payment_id
    WHERE c.payment_id=pt.id AND c.member_id=p_member AND c.currency=p_currency AND c.livemode=p_livemode
     AND w.requested_generation>w.processed_generation)
  ORDER BY pt.id FOR UPDATE
 ) payments;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_member::text||p_currency,0));
 RETURN locked;
END $$;


ALTER FUNCTION public.affiliate_lock_member(p_member uuid, p_currency text, p_payments uuid[], p_livemode boolean) OWNER TO postgres;

--
-- Name: affiliate_ledger; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.affiliate_ledger (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    member_id uuid NOT NULL,
    commission_id uuid,
    payout_id uuid,
    kind text NOT NULL,
    amount_minor bigint NOT NULL,
    currency text NOT NULL,
    economic_key text NOT NULL,
    reason text,
    evidence_reference text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT affiliate_ledger_amount_minor_check CHECK ((amount_minor <> 0)),
    CONSTRAINT affiliate_ledger_check CHECK ((((kind = 'settlement'::text) AND (amount_minor < 0) AND (payout_id IS NOT NULL) AND (commission_id IS NULL)) OR ((kind = ANY (ARRAY['accrual'::text, 'reversal'::text, 'restoration'::text])) AND (commission_id IS NOT NULL) AND (payout_id IS NULL)) OR ((kind = 'manual_adjustment'::text) AND (commission_id IS NOT NULL) AND (payout_id IS NULL) AND (reason IS NOT NULL) AND (evidence_reference IS NOT NULL)))),
    CONSTRAINT affiliate_ledger_check1 CHECK (((kind <> ALL (ARRAY['accrual'::text, 'restoration'::text])) OR (amount_minor > 0))),
    CONSTRAINT affiliate_ledger_check2 CHECK (((kind <> 'reversal'::text) OR (amount_minor < 0))),
    CONSTRAINT affiliate_ledger_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT affiliate_ledger_economic_key_check CHECK (((length(economic_key) >= 1) AND (length(economic_key) <= 200))),
    CONSTRAINT affiliate_ledger_evidence_reference_check CHECK (((evidence_reference IS NULL) OR public.affiliate_valid_reference(evidence_reference))),
    CONSTRAINT affiliate_ledger_kind_check CHECK ((kind = ANY (ARRAY['accrual'::text, 'reversal'::text, 'restoration'::text, 'settlement'::text, 'manual_adjustment'::text]))),
    CONSTRAINT affiliate_ledger_reason_check CHECK (((reason IS NULL) OR public.affiliate_valid_reference(reason)))
);


ALTER TABLE public.affiliate_ledger OWNER TO postgres;

--
-- Name: affiliate_manual_adjustment(uuid, uuid, bigint, bigint, text, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_manual_adjustment(p_actor uuid, p_commission uuid, p_expected_version bigint, p_amount_minor bigint, p_reason text, p_evidence_reference text, p_review_dispute boolean) RETURNS public.affiliate_ledger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE c public.affiliate_commissions; result public.affiliate_ledger; total numeric;
BEGIN
 PERFORM public.affiliate_admin(p_actor);
 SELECT * INTO c FROM public.affiliate_commissions WHERE id=p_commission;
 PERFORM public.affiliate_lock_member(c.member_id,c.currency,ARRAY[c.payment_id],c.livemode);
 SELECT * INTO c FROM public.affiliate_commissions WHERE id=p_commission FOR UPDATE;
 IF c.id IS NULL OR c.version IS DISTINCT FROM p_expected_version THEN RAISE EXCEPTION 'Version changed' USING ERRCODE='PT409'; END IF;
 IF p_amount_minor IS NULL OR p_amount_minor=0 OR NOT public.affiliate_valid_reference(p_reason) OR NOT public.affiliate_valid_reference(p_evidence_reference) THEN
  RAISE EXCEPTION 'Evidence required' USING ERRCODE='22023'; END IF;
 SELECT coalesce(sum(amount_minor),0)+p_amount_minor INTO total FROM public.affiliate_ledger WHERE commission_id=c.id;
 IF total<0 OR total>c.accrued_minor OR (p_review_dispute AND NOT c.dispute_seen)
  OR EXISTS(SELECT 1 FROM public.affiliate_work WHERE payment_id=c.payment_id AND requested_generation>processed_generation) THEN
  RAISE EXCEPTION 'Adjustment unavailable' USING ERRCODE='22023'; END IF;
 INSERT INTO public.affiliate_ledger(member_id,commission_id,kind,amount_minor,currency,economic_key,reason,evidence_reference)
 VALUES(c.member_id,c.id,'manual_adjustment',p_amount_minor,c.currency,'manual:'||c.id||':'||c.version,p_reason,p_evidence_reference) RETURNING * INTO result;
 UPDATE public.affiliate_commissions SET dispute_reviewed_at=CASE WHEN p_review_dispute THEN now() ELSE dispute_reviewed_at END,version=version+1 WHERE id=c.id;
 UPDATE public.affiliate_payouts p SET needs_review=true,version=version+1
 WHERE p.status='reserved' AND NOT p.needs_review AND EXISTS(SELECT 1 FROM public.affiliate_payout_allocations a
  JOIN public.affiliate_ledger l ON l.id=a.entry_id WHERE a.payout_id=p.id AND a.released_at IS NULL AND l.commission_id=c.id);
 PERFORM public.affiliate_audit('affiliate_ledger',NULL,to_jsonb(result),p_actor);
 RETURN result;
END $$;


ALTER FUNCTION public.affiliate_manual_adjustment(p_actor uuid, p_commission uuid, p_expected_version bigint, p_amount_minor bigint, p_reason text, p_evidence_reference text, p_review_dispute boolean) OWNER TO postgres;

--
-- Name: affiliate_mark_paid(uuid, uuid, bigint, text, text, bigint, text, timestamp with time zone, boolean, text, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_mark_paid(p_actor uuid, p_payout uuid, p_expected_version bigint, p_bank_reference text, p_invoice_reference text, p_bank_amount_minor bigint, p_currency text, p_paid_at timestamp with time zone, p_full_settlement boolean, p_reason text DEFAULT NULL::text, p_evidence_reference text DEFAULT NULL::text, p_livemode boolean DEFAULT true) RETURNS public.affiliate_payouts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE old public.affiliate_payouts; result public.affiliate_payouts;
BEGIN
 PERFORM public.affiliate_admin(p_actor);
 SELECT * INTO old FROM public.affiliate_payouts WHERE id=p_payout;
 PERFORM public.affiliate_lock_member(old.member_id,old.currency,ARRAY(
  SELECT DISTINCT c.payment_id FROM public.affiliate_payout_allocations a JOIN public.affiliate_ledger l ON l.id=a.entry_id
   JOIN public.affiliate_commissions c ON c.id=l.commission_id WHERE a.payout_id=old.id AND a.released_at IS NULL),old.livemode);
 SELECT * INTO old FROM public.affiliate_payouts WHERE id=p_payout FOR UPDATE;
 IF old.livemode IS DISTINCT FROM p_livemode THEN RAISE EXCEPTION 'Stripe mode changed' USING ERRCODE='PT409'; END IF;
 IF old.status='paid' AND old.bank_reference=p_bank_reference AND old.invoice_reference=p_invoice_reference
  AND old.bank_amount_minor=p_bank_amount_minor AND old.currency=p_currency AND old.paid_at=p_paid_at AND p_full_settlement THEN RETURN old; END IF;
 IF old.id IS NULL OR old.version IS DISTINCT FROM p_expected_version OR old.status<>'reserved' THEN RAISE EXCEPTION 'Version changed' USING ERRCODE='PT409'; END IF;
 IF p_full_settlement IS DISTINCT FROM true OR p_currency IS DISTINCT FROM old.currency OR p_paid_at IS NULL OR p_paid_at>now()
 OR NOT public.affiliate_valid_reference(p_bank_reference) OR NOT public.affiliate_valid_reference(p_invoice_reference)
 OR p_bank_amount_minor IS NULL OR p_bank_amount_minor<=0
 OR (old.needs_review AND (NOT public.affiliate_valid_reference(p_reason) OR NOT public.affiliate_valid_reference(p_evidence_reference))) THEN
  RAISE EXCEPTION 'Payment evidence required' USING ERRCODE='22023'; END IF;
 UPDATE public.affiliate_payouts SET status='paid',version=version+1,bank_reference=p_bank_reference,
  invoice_reference=p_invoice_reference,bank_amount_minor=p_bank_amount_minor,paid_at=p_paid_at WHERE id=p_payout RETURNING * INTO result;
 INSERT INTO public.affiliate_ledger(member_id,payout_id,kind,amount_minor,currency,economic_key,reason,evidence_reference)
  VALUES(old.member_id,old.id,'settlement',-old.earnings_minor,old.currency,'settlement:'||old.id,p_reason,p_evidence_reference);
 PERFORM public.affiliate_audit('affiliate_payouts',to_jsonb(old),to_jsonb(result)||jsonb_build_object('reason',p_reason,'evidence_reference',p_evidence_reference),p_actor);
 RETURN result;
END $$;


ALTER FUNCTION public.affiliate_mark_paid(p_actor uuid, p_payout uuid, p_expected_version bigint, p_bank_reference text, p_invoice_reference text, p_bank_amount_minor bigint, p_currency text, p_paid_at timestamp with time zone, p_full_settlement boolean, p_reason text, p_evidence_reference text, p_livemode boolean) OWNER TO postgres;

--
-- Name: affiliate_member_update(uuid, uuid, bigint, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_member_update(p_actor uuid, p_member uuid, p_expected_version bigint, p_status text, p_reason text) RETURNS public.affiliate_memberships
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE old public.affiliate_memberships; result public.affiliate_memberships;
BEGIN
 PERFORM public.affiliate_admin(p_actor);
 IF NOT public.affiliate_valid_reference(p_reason) THEN RAISE EXCEPTION 'Reason required' USING ERRCODE='22023'; END IF;
 SELECT * INTO old FROM public.affiliate_memberships WHERE id=p_member FOR UPDATE;
 IF old.id IS NULL OR old.version IS DISTINCT FROM p_expected_version THEN RAISE EXCEPTION 'Version changed' USING ERRCODE='PT409'; END IF;
 UPDATE public.affiliate_memberships SET status=p_status,version=version+1 WHERE id=p_member RETURNING * INTO result;
 INSERT INTO public.affiliate_membership_events(member_id,version,status) VALUES(result.id,result.version,result.status);
 PERFORM public.affiliate_audit('affiliate_memberships',to_jsonb(old),to_jsonb(result)||jsonb_build_object('reason',p_reason),p_actor);
 RETURN result;
END $$;


ALTER FUNCTION public.affiliate_member_update(p_actor uuid, p_member uuid, p_expected_version bigint, p_status text, p_reason text) OWNER TO postgres;

--
-- Name: affiliate_payout_exportable(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_payout_exportable(p_payout uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT coalesce(bool_and(coalesce(public.affiliate_entry_eligible(c.kind,l.amount_minor,
   EXISTS(SELECT 1 FROM public.affiliate_ledger e JOIN public.affiliate_payout_allocations pa ON pa.entry_id=e.id AND pa.released_at IS NULL
    JOIN public.affiliate_payouts pp ON pp.id=pa.payout_id AND pp.status='paid' WHERE e.commission_id=c.id),
   true,coalesce((SELECT enabled FROM public.affiliate_programs),false),m.creator_accepted_at IS NOT NULL),false)),false)
 FROM public.affiliate_payouts p JOIN public.affiliate_memberships m ON m.id=p.member_id
 JOIN public.affiliate_payout_allocations a ON a.payout_id=p.id AND a.released_at IS NULL
 JOIN public.affiliate_ledger l ON l.id=a.entry_id JOIN public.affiliate_commissions c ON c.id=l.commission_id
 WHERE p.id=p_payout;
$$;


ALTER FUNCTION public.affiliate_payout_exportable(p_payout uuid) OWNER TO postgres;

--
-- Name: affiliate_portal_page(uuid, text, uuid, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_portal_page(p_member uuid, p_currency text DEFAULT NULL::text, p_cursor uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 25, p_as_of timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE result jsonb; creator_ok boolean;
BEGIN
 IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Invalid limit' USING ERRCODE='22023'; END IF;
 SELECT coalesce((SELECT creator_accepted_at IS NOT NULL FROM public.affiliate_memberships WHERE id=p_member),false) INTO creator_ok;
 WITH page AS MATERIALIZED (
  SELECT c.* FROM public.affiliate_commissions c WHERE c.member_id=p_member AND (p_currency IS NULL OR c.currency=p_currency)
   AND (p_cursor IS NULL OR (c.paid_at,c.id)<(SELECT own.paid_at,own.id FROM public.affiliate_commissions own
    WHERE own.id=p_cursor AND own.member_id=p_member AND (p_currency IS NULL OR own.currency=p_currency)))
  ORDER BY c.paid_at DESC,c.id DESC LIMIT p_limit+1
 ), rows AS (
  SELECT c.id,c.paid_at,jsonb_build_object('product',coalesce(prod.name,li.product_name),'reference',c.id,'kind',c.kind,'currency',c.currency,'paid_at',c.paid_at,
   'eligible_at',c.eligible_at,'accrued_minor',c.accrued_minor::text,'current_minor',l.current::text,'livemode',c.livemode,
   'terms_required',c.kind='cocreator' AND NOT creator_ok,
   'status',CASE WHEN l.current<=0 THEN 'reversed' WHEN l.reserved THEN 'reserved' WHEN l.paid>=l.current THEN 'paid'
    WHEN c.eligible_at<=p_as_of AND ((NOT c.dispute_seen AND pt.status<>'disputed') OR c.dispute_reviewed_at IS NOT NULL)
     AND (c.kind<>'cocreator' OR creator_ok) THEN 'eligible' ELSE 'held' END,
   'sync_pending',c.observed_status<>pt.status OR c.observed_refunded_gross<>coalesce(pt.refunded_amount,0)
    OR coalesce(w.status<>'done' OR w.requested_generation>w.processed_generation,false),
   'needs_review',coalesce(w.status='needs_review',false) OR (c.dispute_seen AND c.dispute_reviewed_at IS NULL)) AS row
  FROM (SELECT * FROM page ORDER BY paid_at DESC,id DESC LIMIT p_limit) c
  JOIN public.payment_line_items li ON li.id=c.line_item_id LEFT JOIN public.products prod ON prod.id=li.product_id
  JOIN public.payment_transactions pt ON pt.id=c.payment_id LEFT JOIN public.affiliate_work w ON w.payment_id=c.payment_id
  CROSS JOIN LATERAL (
   SELECT coalesce(sum(e.amount_minor),0) AS current,coalesce(bool_or(p.status='reserved'),false) AS reserved,
    coalesce(sum(e.amount_minor) FILTER(WHERE p.status='paid'),0) AS paid
   FROM public.affiliate_ledger e LEFT JOIN public.affiliate_payout_allocations a ON a.entry_id=e.id AND a.released_at IS NULL
   LEFT JOIN public.affiliate_payouts p ON p.id=a.payout_id WHERE e.commission_id=c.id
  ) l
 ) SELECT jsonb_build_object('commissions',coalesce((SELECT jsonb_agg(row ORDER BY paid_at DESC,id DESC) FROM rows),'[]'::jsonb),
  'next_cursor',CASE WHEN (SELECT count(*) FROM page)>p_limit THEN (SELECT id FROM rows ORDER BY paid_at,id LIMIT 1) ELSE NULL END) INTO result;
 RETURN result;
END $$;


ALTER FUNCTION public.affiliate_portal_page(p_member uuid, p_currency text, p_cursor uuid, p_limit integer, p_as_of timestamp with time zone) OWNER TO postgres;

--
-- Name: affiliate_portal_summary(uuid, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_portal_summary(p_member uuid, p_as_of timestamp with time zone, p_livemode boolean DEFAULT true) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 WITH balances AS (
  SELECT c.currency,v.* FROM (SELECT DISTINCT currency FROM public.affiliate_commissions WHERE member_id=p_member AND livemode=p_livemode) c
  CROSS JOIN LATERAL public.affiliate_preview(p_member,c.currency,p_as_of,p_livemode) v
 ), bindings AS MATERIALIZED (
  SELECT b.coupon_id,c.code,c.is_active,c.allowed_product_ids FROM public.affiliate_coupon_bindings b
  JOIN public.coupons c ON c.id=b.coupon_id WHERE b.member_id=p_member AND b.retired_at IS NULL
 ), rules AS (
  SELECT DISTINCT ON (r.product_id) r.*,p.name FROM public.affiliate_rules r JOIN public.products p ON p.id=r.product_id
  WHERE p.is_active AND p.product_type='one_time' AND EXISTS(SELECT 1 FROM bindings b WHERE b.is_active
   AND (coalesce(jsonb_array_length(b.allowed_product_ids),0)=0 OR b.allowed_product_ids ? r.product_id::text))
  ORDER BY r.product_id,r.revision DESC
 ), creator_rules AS (
  SELECT cr.*,p.name FROM (SELECT DISTINCT ON (r.product_id) r.* FROM public.affiliate_cocreator_rules r
   WHERE r.product_id IN (SELECT product_id FROM public.affiliate_cocreator_rules WHERE member_id=p_member)
   ORDER BY r.product_id,r.revision DESC) cr JOIN public.products p ON p.id=cr.product_id WHERE cr.member_id=p_member
 ), member AS (SELECT * FROM public.affiliate_memberships WHERE id=p_member),
 terms AS (SELECT * FROM public.affiliate_creator_terms ORDER BY id DESC LIMIT 1)
 SELECT jsonb_build_object(
  'is_partner',coalesce((SELECT is_partner FROM member),true),
  'balances',coalesce((SELECT jsonb_agg(jsonb_build_object('currency',currency,'accrued',accrued,'reversed',reversed,'paid',paid,'reserved',reserved,
   'held',held_minor,'eligible',greatest(payable_minor::numeric,0)::text,'debt',greatest(-payable_minor::numeric,0)::text,'balance',balance) ORDER BY currency) FROM balances),'[]'::jsonb),
  'codes',coalesce((SELECT jsonb_agg(jsonb_build_object('code',code,'active',is_active) ORDER BY code) FROM bindings),'[]'::jsonb),
  'rules',coalesce((SELECT jsonb_agg(jsonb_build_object('product',name,'percentage_bps',percentage_bps,'fixed_minor',fixed_minor::text,'currency',currency,'enabled',enabled) ORDER BY name) FROM rules),'[]'::jsonb),
  'creator',jsonb_build_object(
   'active',EXISTS(SELECT 1 FROM public.affiliate_cocreator_rules WHERE member_id=p_member),
   'rules',coalesce((SELECT jsonb_agg(jsonb_build_object('product',name,'percentage_bps',percentage_bps,'fixed_minor',fixed_minor::text,'currency',currency) ORDER BY name) FROM creator_rules),'[]'::jsonb),
   'accepted_version',(SELECT creator_terms_version FROM member),'accepted_at',(SELECT creator_accepted_at FROM member),
   'terms',(SELECT jsonb_build_object('version',terms_version,'en',terms->>'en','pl',terms->>'pl') FROM terms)),
  'sync_pending',EXISTS(SELECT 1 FROM balances WHERE sync_required),
  'needs_review',EXISTS(SELECT 1 FROM public.affiliate_payouts WHERE member_id=p_member AND livemode=p_livemode AND needs_review)
   OR EXISTS(SELECT 1 FROM public.affiliate_commissions c LEFT JOIN public.affiliate_work w ON w.payment_id=c.payment_id
    WHERE c.member_id=p_member AND c.livemode=p_livemode AND (w.status='needs_review' OR (c.dispute_seen AND c.dispute_reviewed_at IS NULL))))
$$;


ALTER FUNCTION public.affiliate_portal_summary(p_member uuid, p_as_of timestamp with time zone, p_livemode boolean) OWNER TO postgres;

--
-- Name: affiliate_preview(uuid, text, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_preview(p_member uuid, p_currency text, p_cutoff timestamp with time zone, p_livemode boolean DEFAULT true) RETURNS TABLE(member_version text, program_version text, earnings_minor text, debt_offset_minor text, payable_minor text, held_minor text, threshold_minor text, sync_required boolean, available boolean, entry_ids uuid[], accrued text, reversed text, paid text, reserved text, balance text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 WITH gate AS (
  SELECT coalesce((SELECT enabled FROM public.affiliate_programs),false) AS referral_ok,
   coalesce((SELECT creator_accepted_at IS NOT NULL FROM public.affiliate_memberships WHERE id=p_member),false) AS creator_ok
 ), facts AS MATERIALIZED (
  SELECT c.id,c.kind,c.eligible_at,c.dispute_seen,c.dispute_reviewed_at,pt.status,
   (c.observed_status<>pt.status OR c.observed_refunded_gross<>coalesce(pt.refunded_amount,0)
    OR coalesce(w.status<>'done' OR w.requested_generation>w.processed_generation,false)) AS dirty,
   EXISTS(SELECT 1 FROM public.affiliate_ledger l WHERE l.commission_id=c.id AND l.kind='accrual' AND l.created_at<=p_cutoff) AS earned,
   EXISTS(SELECT 1 FROM public.affiliate_ledger l JOIN public.affiliate_payout_allocations a ON a.entry_id=l.id AND a.released_at IS NULL
    JOIN public.affiliate_payouts p ON p.id=a.payout_id AND p.status='paid' WHERE l.commission_id=c.id) AS previously_paid
  FROM public.affiliate_commissions c JOIN public.payment_transactions pt ON pt.id=c.payment_id
  LEFT JOIN public.affiliate_work w ON w.payment_id=c.payment_id
  WHERE c.member_id=p_member AND c.currency=p_currency AND c.livemode=p_livemode
 ), entries AS MATERIALIZED (
  SELECT l.id,l.commission_id,l.kind,l.amount_minor,p.status AS allocation_status,
   coalesce(a.entry_id IS NULL AND public.affiliate_entry_eligible(f.kind,l.amount_minor,f.previously_paid,
    f.earned AND f.eligible_at<=p_cutoff AND ((NOT f.dispute_seen AND f.status<>'disputed') OR f.dispute_reviewed_at IS NOT NULL),
    g.referral_ok,g.creator_ok),false) AS selectable
  FROM public.affiliate_ledger l JOIN facts f ON f.id=l.commission_id CROSS JOIN gate g
  LEFT JOIN public.affiliate_payout_allocations a ON a.entry_id=l.id AND a.released_at IS NULL
  LEFT JOIN public.affiliate_payouts p ON p.id=a.payout_id
 ), totals AS (
  SELECT coalesce(sum(amount_minor) FILTER(WHERE selectable AND amount_minor>0),0) AS earnings,
   -coalesce(sum(amount_minor) FILTER(WHERE selectable AND amount_minor<0),0) AS debt,
   coalesce(sum(amount_minor) FILTER(WHERE kind='accrual'),0) AS accrued,
   -coalesce(sum(amount_minor) FILTER(WHERE kind IN ('reversal','restoration')),0) AS reversed,
   coalesce(sum(amount_minor) FILTER(WHERE allocation_status='reserved'),0) AS reserved,
   coalesce(sum(amount_minor),0) AS balance,
   coalesce(array_agg(id ORDER BY id) FILTER(WHERE selectable),'{}'::uuid[]) AS ids
  FROM entries
 ), held AS (
  SELECT coalesce(sum(greatest(amount,0)),0) AS amount FROM (
   SELECT sum(amount_minor) AS amount FROM entries WHERE allocation_status IS NULL AND NOT selectable GROUP BY commission_id
  ) h
 ), settlements AS (
  SELECT -coalesce(sum(l.amount_minor),0) AS amount FROM public.affiliate_ledger l
  JOIN public.affiliate_payouts p ON p.id=l.payout_id WHERE l.member_id=p_member AND l.currency=p_currency AND p.livemode=p_livemode
 ), readiness AS (SELECT coalesce(bool_or(dirty),false) AS dirty FROM facts)
 SELECT m.version::text,p.version::text,t.earnings::text,t.debt::text,(t.earnings-t.debt)::text,h.amount::text,
  p.thresholds->>p_currency,r.dirty,
  m.status='approved' AND m.user_id IS NOT NULL AND NOT r.dirty
   AND p_cutoff IS NOT NULL AND p_cutoff<=now() AND p.thresholds ? p_currency
   AND t.earnings-t.debt>0 AND t.earnings-t.debt>=(p.thresholds->>p_currency)::bigint
   AND NOT EXISTS(SELECT 1 FROM public.affiliate_payouts ap WHERE ap.member_id=p_member AND ap.currency=p_currency AND ap.livemode=p_livemode AND ap.status='reserved'),
  t.ids,t.accrued::text,t.reversed::text,s.amount::text,t.reserved::text,(t.balance-s.amount)::text
 FROM public.affiliate_memberships m CROSS JOIN public.affiliate_programs p CROSS JOIN totals t
 CROSS JOIN held h CROSS JOIN settlements s CROSS JOIN readiness r WHERE m.id=p_member;
$$;


ALTER FUNCTION public.affiliate_preview(p_member uuid, p_currency text, p_cutoff timestamp with time zone, p_livemode boolean) OWNER TO postgres;

--
-- Name: affiliate_programs; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.affiliate_programs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    singleton boolean DEFAULT true NOT NULL,
    enabled boolean DEFAULT false NOT NULL,
    version bigint DEFAULT 1 NOT NULL,
    hold_days integer DEFAULT 30 NOT NULL,
    buffer_days integer DEFAULT 2 NOT NULL,
    terms_version text NOT NULL,
    terms jsonb NOT NULL,
    thresholds jsonb DEFAULT '{"PLN": "10000"}'::jsonb NOT NULL,
    CONSTRAINT affiliate_programs_buffer_days_check CHECK (((buffer_days >= 0) AND (buffer_days <= 365))),
    CONSTRAINT affiliate_programs_check CHECK (public.affiliate_valid_program(terms, thresholds)),
    CONSTRAINT affiliate_programs_hold_days_check CHECK (((hold_days >= 0) AND (hold_days <= 3650))),
    CONSTRAINT affiliate_programs_singleton_check CHECK (singleton),
    CONSTRAINT affiliate_programs_terms_check CHECK ((jsonb_typeof(terms) = 'object'::text)),
    CONSTRAINT affiliate_programs_terms_version_check CHECK (public.affiliate_valid_reference(terms_version)),
    CONSTRAINT affiliate_programs_thresholds_check CHECK ((jsonb_typeof(thresholds) = 'object'::text)),
    CONSTRAINT affiliate_programs_version_check CHECK ((version > 0))
);


ALTER TABLE public.affiliate_programs OWNER TO postgres;

--
-- Name: affiliate_program_update(uuid, bigint, boolean, text, jsonb, integer, integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_program_update(p_actor uuid, p_expected_version bigint, p_enabled boolean, p_terms_version text, p_terms jsonb, p_hold_days integer, p_buffer_days integer, p_thresholds jsonb) RETURNS public.affiliate_programs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE old public.affiliate_programs; result public.affiliate_programs;
BEGIN
 PERFORM public.affiliate_admin(p_actor);
 SELECT * INTO old FROM public.affiliate_programs FOR UPDATE;
 IF EXISTS(SELECT 1 FROM public.affiliate_program_versions WHERE terms_version=p_terms_version AND terms<>p_terms) THEN
  RAISE EXCEPTION 'Terms version changed' USING ERRCODE='PT409'; END IF;
 IF old.id IS NULL THEN
  IF p_expected_version IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'Version changed' USING ERRCODE='PT409'; END IF;
  INSERT INTO public.affiliate_programs(enabled,terms_version,terms,hold_days,buffer_days,thresholds)
   VALUES(p_enabled,p_terms_version,p_terms,p_hold_days,p_buffer_days,p_thresholds) RETURNING * INTO result;
 ELSE
  IF old.version IS DISTINCT FROM p_expected_version THEN RAISE EXCEPTION 'Version changed' USING ERRCODE='PT409'; END IF;
  UPDATE public.affiliate_programs SET enabled=p_enabled,terms_version=p_terms_version,terms=p_terms,hold_days=p_hold_days,
   buffer_days=p_buffer_days,thresholds=p_thresholds,version=version+1 WHERE id=old.id RETURNING * INTO result;
 END IF;
 INSERT INTO public.affiliate_program_versions(program_id,version,enabled,hold_days,buffer_days,terms_version,terms,thresholds)
 VALUES(result.id,result.version,result.enabled,result.hold_days,result.buffer_days,result.terms_version,result.terms,result.thresholds);
 PERFORM public.affiliate_audit('affiliate_programs',CASE WHEN old.id IS NULL THEN NULL ELSE to_jsonb(old) END,to_jsonb(result),p_actor);
 RETURN result;
END $$;


ALTER FUNCTION public.affiliate_program_update(p_actor uuid, p_expected_version bigint, p_enabled boolean, p_terms_version text, p_terms jsonb, p_hold_days integer, p_buffer_days integer, p_thresholds jsonb) OWNER TO postgres;

--
-- Name: affiliate_reserve(uuid, uuid, text, timestamp with time zone, bigint, bigint, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_reserve(p_actor uuid, p_member uuid, p_currency text, p_cutoff timestamp with time zone, p_member_version bigint, p_program_version bigint, p_payee_reference text, p_livemode boolean DEFAULT true) RETURNS public.affiliate_payouts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE m public.affiliate_memberships; prog public.affiliate_programs; result public.affiliate_payouts; preview record; locked uuid[];
BEGIN
 PERFORM public.affiliate_admin(p_actor);
 SELECT * INTO preview FROM public.affiliate_preview(p_member,p_currency,p_cutoff,p_livemode);
 locked:=public.affiliate_lock_member(p_member,p_currency,ARRAY(
  SELECT DISTINCT c.payment_id FROM public.affiliate_ledger l JOIN public.affiliate_commissions c ON c.id=l.commission_id
   WHERE l.id=ANY(preview.entry_ids)),p_livemode);

 SELECT * INTO m FROM public.affiliate_memberships WHERE id=p_member FOR SHARE;
 SELECT * INTO prog FROM public.affiliate_programs FOR SHARE;
 IF m.id IS NULL OR m.version IS DISTINCT FROM p_member_version OR prog.version IS DISTINCT FROM p_program_version THEN RAISE EXCEPTION 'Version changed' USING ERRCODE='PT409'; END IF;
 IF p_livemode IS NULL OR m.status<>'approved' OR m.user_id IS NULL OR p_currency !~ '^[A-Z]{3}$'
  OR p_cutoff IS NULL OR p_cutoff>now() OR NOT(prog.thresholds ? p_currency) THEN
  RAISE EXCEPTION 'Payout unavailable' USING ERRCODE='22023'; END IF;
 SELECT * INTO preview FROM public.affiliate_preview(p_member,p_currency,p_cutoff,p_livemode);
 IF preview.sync_required OR EXISTS(SELECT 1 FROM public.affiliate_ledger l JOIN public.affiliate_commissions c ON c.id=l.commission_id
  WHERE l.id=ANY(preview.entry_ids) AND NOT(c.payment_id=ANY(locked))) THEN RAISE EXCEPTION 'Sync required' USING ERRCODE='PT409'; END IF;
 IF NOT preview.available THEN RAISE EXCEPTION 'Threshold not met' USING ERRCODE='22023'; END IF;
 INSERT INTO public.affiliate_payouts(member_id,currency,earnings_minor,status,cutoff,payee_reference,livemode)
  VALUES(p_member,p_currency,preview.payable_minor::bigint,'reserved',p_cutoff,p_payee_reference,p_livemode) RETURNING * INTO result;
 INSERT INTO public.affiliate_payout_allocations(payout_id,entry_id) SELECT result.id,unnest(preview.entry_ids);
 PERFORM public.affiliate_audit('affiliate_payouts',NULL,to_jsonb(result),p_actor);
 RETURN result;
END $_$;


ALTER FUNCTION public.affiliate_reserve(p_actor uuid, p_member uuid, p_currency text, p_cutoff timestamp with time zone, p_member_version bigint, p_program_version bigint, p_payee_reference text, p_livemode boolean) OWNER TO postgres;

--
-- Name: affiliate_retry_work(uuid, uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_retry_work(p_payment uuid, p_token uuid, p_generation bigint, p_error text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 UPDATE public.affiliate_work SET status=CASE WHEN attempts>=10 THEN 'needs_review' ELSE 'pending' END,
 next_attempt_at=now()+least(3600,60*power(2,least(attempts-1,6))) * interval '1 second',
 lease_token=NULL,leased_until=NULL,last_error_code=p_error
 WHERE payment_id=p_payment AND lease_token=p_token AND status='leased' AND leased_until>now()
 AND p_generation<=requested_generation AND p_generation>processed_generation;
 RETURN FOUND;
END $$;


ALTER FUNCTION public.affiliate_retry_work(p_payment uuid, p_token uuid, p_generation bigint, p_error text) OWNER TO postgres;

--
-- Name: affiliate_rules; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.affiliate_rules (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    product_id uuid NOT NULL,
    revision integer NOT NULL,
    enabled boolean NOT NULL,
    percentage_bps integer,
    fixed_minor bigint,
    currency text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT affiliate_rules_check CHECK ((((percentage_bps IS NOT NULL) AND (fixed_minor IS NULL) AND (currency IS NULL)) OR ((percentage_bps IS NULL) AND (fixed_minor IS NOT NULL) AND (currency IS NOT NULL)))),
    CONSTRAINT affiliate_rules_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT affiliate_rules_fixed_minor_check CHECK ((fixed_minor >= 0)),
    CONSTRAINT affiliate_rules_percentage_bps_check CHECK (((percentage_bps >= 0) AND (percentage_bps <= 10000))),
    CONSTRAINT affiliate_rules_revision_check CHECK ((revision > 0))
);


ALTER TABLE public.affiliate_rules OWNER TO postgres;

--
-- Name: affiliate_rule_create(uuid, uuid, integer, boolean, integer, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_rule_create(p_actor uuid, p_product uuid, p_expected_revision integer, p_enabled boolean, p_percentage_bps integer, p_fixed_minor bigint, p_currency text) RETURNS public.affiliate_rules
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE result public.affiliate_rules; revision integer;
BEGIN
 PERFORM public.affiliate_admin(p_actor);
 PERFORM 1 FROM public.products WHERE id=p_product AND product_type='one_time' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'One-time product required' USING ERRCODE='22023'; END IF;
 SELECT coalesce(max(r.revision),0) INTO revision FROM public.affiliate_rules r WHERE product_id=p_product;
 IF revision IS DISTINCT FROM p_expected_revision THEN RAISE EXCEPTION 'Revision changed' USING ERRCODE='PT409'; END IF;
 INSERT INTO public.affiliate_rules(product_id,revision,enabled,percentage_bps,fixed_minor,currency)
 VALUES(p_product,revision+1,p_enabled,p_percentage_bps,p_fixed_minor,p_currency) RETURNING * INTO result;
 PERFORM public.affiliate_audit('affiliate_rules',NULL,to_jsonb(result),p_actor);
 RETURN result;
END $$;


ALTER FUNCTION public.affiliate_rule_create(p_actor uuid, p_product uuid, p_expected_revision integer, p_enabled boolean, p_percentage_bps integer, p_fixed_minor bigint, p_currency text) OWNER TO postgres;

--
-- Name: affiliate_rule_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_rule_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND OLD.product_id::text = current_setting('sellf.deleting_product', true) THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'Append only record' USING ERRCODE = '23514';
END $$;


ALTER FUNCTION public.affiliate_rule_guard() OWNER TO postgres;

--
-- Name: affiliate_work_retry(uuid, uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.affiliate_work_retry(p_actor uuid, p_payment uuid, p_generation bigint, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE old public.affiliate_work; result public.affiliate_work;
BEGIN
 PERFORM public.affiliate_admin(p_actor);
 IF NOT public.affiliate_valid_reference(p_reason) THEN RAISE EXCEPTION 'Reason required' USING ERRCODE='22023'; END IF;
 SELECT * INTO old FROM public.affiliate_work WHERE payment_id=p_payment FOR UPDATE;
 IF old.payment_id IS NULL OR old.requested_generation IS DISTINCT FROM p_generation OR old.status='leased' THEN RAISE EXCEPTION 'Version changed' USING ERRCODE='PT409'; END IF;
 UPDATE public.affiliate_work SET status='pending',attempts=0,next_attempt_at=now(),last_error_code=NULL,
 requested_generation=requested_generation+1 WHERE payment_id=p_payment RETURNING * INTO result;
 PERFORM public.affiliate_audit('affiliate_work',to_jsonb(old),to_jsonb(result)||jsonb_build_object('reason',p_reason),p_actor);
END $$;


ALTER FUNCTION public.affiliate_work_retry(p_actor uuid, p_payment uuid, p_generation bigint, p_reason text) OWNER TO postgres;

--
-- Name: apply_migration(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.apply_migration(migration_version text, migration_sql text, content_checksum text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_start TIMESTAMPTZ;
  v_elapsed_ms INTEGER;
  v_version_ts TEXT;
  v_version_name TEXT;
BEGIN
  -- LAYER 1: Role check
  IF (select auth.role()) IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Forbidden: only service_role can apply migrations'
      USING ERRCODE = '42501';
  END IF;

  -- LAYER 2: Rate limit
  IF NOT public.check_rate_limit('apply_migration', 50, 600) THEN
    RAISE EXCEPTION 'Rate limited: too many migration attempts'
      USING ERRCODE = '54000';
  END IF;

  -- LAYER 3: Validate version format (YYYYMMDDHHMMSS_lowercase_with_underscores)
  IF migration_version !~ '^[0-9]{14}_[a-z0-9_]+$' THEN
    RAISE EXCEPTION 'Invalid migration version format: %', migration_version
      USING ERRCODE = '22023';
  END IF;

  -- Split version into timestamp + name parts (schema_migrations stores them separately)
  v_version_ts := substring(migration_version from 1 for 14);
  v_version_name := substring(migration_version from 16);

  -- LAYER 4: Idempotency — check by timestamp (the actual PK of schema_migrations)
  IF EXISTS (
    SELECT 1 FROM supabase_migrations.schema_migrations WHERE version = v_version_ts
  ) THEN
    RETURN jsonb_build_object(
      'version', migration_version,
      'success', true,
      'skipped', true,
      'message', 'Already applied'
    );
  END IF;

  -- LAYER 5: Advisory lock
  PERFORM pg_advisory_xact_lock(hashtext('sellf_apply_migration'));

  -- Re-check after lock
  IF EXISTS (
    SELECT 1 FROM supabase_migrations.schema_migrations WHERE version = v_version_ts
  ) THEN
    RETURN jsonb_build_object(
      'version', migration_version,
      'success', true,
      'skipped', true,
      'message', 'Already applied (concurrent)'
    );
  END IF;

  -- LAYER 6: Checksum verify
  IF encode(sha256(convert_to(migration_sql, 'UTF8')), 'hex') IS DISTINCT FROM content_checksum THEN
    RAISE EXCEPTION 'Checksum mismatch for migration %: expected %, got %',
      migration_version,
      content_checksum,
      encode(sha256(convert_to(migration_sql, 'UTF8')), 'hex')
      USING ERRCODE = '22023';
  END IF;

  -- LAYER 7: Execute
  v_start := clock_timestamp();
  EXECUTE migration_sql;
  v_elapsed_ms := extract(milliseconds FROM clock_timestamp() - v_start)::INTEGER;

  -- Record into the single source of truth
  INSERT INTO supabase_migrations.schema_migrations (version, name)
  VALUES (v_version_ts, v_version_name)
  ON CONFLICT (version) DO NOTHING;

  RETURN jsonb_build_object(
    'version', migration_version,
    'success', true,
    'skipped', false,
    'execution_ms', v_elapsed_ms
  );
END;
$_$;


ALTER FUNCTION public.apply_migration(migration_version text, migration_sql text, content_checksum text) OWNER TO postgres;

--
-- Name: apply_payment_dispute(uuid, text, text, boolean, text, integer, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.apply_payment_dispute(p_transaction_id uuid, p_dispute_id text, p_status text, p_closed boolean, p_reason text, p_amount integer, p_currency text, p_created timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE result jsonb; claim json; buyer uuid; guest_ids uuid[]; item jsonb; restored jsonb:='[]';
BEGIN
  IF (select auth.role()) IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Service role required' USING ERRCODE='42501'; END IF;
  result:=public.apply_payment_dispute_before_guest_claim(p_transaction_id,p_dispute_id,p_status,p_closed,p_reason,p_amount,p_currency,p_created);
  IF result IS NULL OR p_status<>'won' THEN RETURN result; END IF;
  SELECT array_agg((value->>'guestPurchaseId')::uuid) INTO guest_ids
    FROM jsonb_array_elements(result->'dispute'->'restoredAccess') WHERE value->>'guestPurchaseId' IS NOT NULL;
  IF guest_ids IS NULL THEN RETURN result; END IF;
  SELECT u.id INTO buyer FROM auth.users u JOIN public.payment_transactions t ON lower(u.email)=lower(t.customer_email)
    WHERE t.id=p_transaction_id AND u.email_confirmed_at IS NOT NULL;
  IF buyer IS NULL OR NOT EXISTS(SELECT 1 FROM public.guest_purchases g WHERE g.id=ANY(guest_ids)
    AND g.claimed_by_user_id IS NULL AND g.customer_email=(SELECT email FROM auth.users WHERE id=buyer)) THEN RETURN result; END IF;
  claim:=public.claim_guest_purchases_for_user(buyer);
  IF (claim->>'success')::boolean IS DISTINCT FROM true OR EXISTS(SELECT 1 FROM public.guest_purchases g
    WHERE g.id=ANY(guest_ids) AND g.claimed_by_user_id IS NULL) THEN
    RAISE EXCEPTION 'Restored purchase claim pending' USING ERRCODE='40001';
  END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(result->'dispute'->'restoredAccess') LOOP
    IF item->>'guestPurchaseId' IS NOT NULL AND EXISTS(SELECT 1 FROM public.guest_purchases g
      WHERE g.id=(item->>'guestPurchaseId')::uuid AND g.claimed_by_user_id=buyer) THEN
      item:=item||jsonb_build_object('userId',buyer);
    END IF;
    restored:=restored||jsonb_build_array(item);
  END LOOP;
  result:=jsonb_set(result,'{dispute,restoredAccess}',restored);
  result:=jsonb_set(result,'{customer,userId}',to_jsonb(buyer));
  UPDATE public.payment_disputes SET payload=result WHERE stripe_dispute_id=p_dispute_id;
  RETURN result;
END $$;


ALTER FUNCTION public.apply_payment_dispute(p_transaction_id uuid, p_dispute_id text, p_status text, p_closed boolean, p_reason text, p_amount integer, p_currency text, p_created timestamp with time zone) OWNER TO postgres;

--
-- Name: apply_payment_dispute_before_guest_claim(uuid, text, text, boolean, text, integer, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.apply_payment_dispute_before_guest_claim(p_transaction_id uuid, p_dispute_id text, p_status text, p_closed boolean, p_reason text, p_amount integer, p_currency text, p_created timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  t public.payment_transactions;
  d public.payment_disputes;
  original jsonb; item jsonb; result jsonb; product_ids uuid[]; buyer_ids uuid[];
  stamp timestamptz := now();
  restored_access jsonb := '[]'; term record; restored_until timestamptz;
  restored boolean := false; changed integer; entitled boolean; can_restore boolean;
  next_status text; stripe_subscription text;
  license record; restored_license public.issued_licenses; restored_licenses jsonb:='[]'; can_restore_license boolean;
BEGIN
  IF (select auth.role()) IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Service role required' USING ERRCODE='42501'; END IF;
  IF p_dispute_id IS NULL OR length(p_dispute_id)>255 OR p_status NOT IN
    ('needs_response','under_review','won','lost','warning_needs_response','warning_under_review','warning_closed')
    OR p_amount<0 OR p_currency IS NULL THEN RAISE EXCEPTION 'Invalid dispute'; END IF;
  SELECT * INTO STRICT t FROM public.payment_transactions WHERE id=p_transaction_id FOR UPDATE;
  IF t.status='pending' THEN RAISE EXCEPTION 'Payment awaiting completion' USING ERRCODE='40001'; END IF;
  SELECT * INTO d FROM public.payment_disputes WHERE stripe_dispute_id=p_dispute_id FOR UPDATE;
  IF FOUND THEN
    IF d.transaction_id<>t.id THEN RAISE EXCEPTION 'Dispute binding differs'; END IF;
    IF d.closed AND (NOT p_closed OR d.status<>p_status) THEN RETURN NULL; END IF;
    IF d.status=p_status AND d.closed=p_closed THEN RETURN d.payload; END IF;
  ELSE
    SELECT array_agg(DISTINCT id) INTO product_ids FROM (
      SELECT t.product_id id UNION SELECT product_id FROM public.payment_line_items WHERE transaction_id=t.id
      UNION SELECT public.order_granted_components(t.id)
      UNION SELECT b.component_product_id FROM public.bundle_items b JOIN public.payment_line_items l
        ON l.product_id=b.bundle_product_id WHERE l.transaction_id=t.id AND l.product_id IS DISTINCT FROM t.product_id
    ) products;
    SELECT array_agg(DISTINCT id) INTO buyer_ids FROM (
      SELECT t.user_id id UNION SELECT claimed_by_user_id FROM public.guest_purchases
        WHERE session_id=t.session_id OR transaction_id=t.id
    ) buyers WHERE id IS NOT NULL;
    entitled := t.status NOT IN ('refunded','cancelled') AND coalesce(t.refunded_amount,0)<t.amount;
    INSERT INTO public.payment_disputes(stripe_dispute_id,transaction_id,status,previous_payment_status,suspended_at)
      VALUES(p_dispute_id,t.id,p_status,CASE WHEN t.status='disputed' THEN
        CASE WHEN coalesce(t.refunded_amount,0)>0 THEN 'partially_refunded' ELSE 'completed' END ELSE t.status END,stamp)
      RETURNING * INTO d;
    IF entitled AND p_status<>'won' THEN
      FOR license IN SELECT l.id FROM public.issued_licenses l WHERE l.order_id=ANY(public.license_order_references(t)) AND l.revoked_at IS NULL ORDER BY l.id FOR UPDATE
      LOOP
        UPDATE public.issued_licenses l SET revoked_at=stamp,revoked_by_dispute_id=p_dispute_id WHERE l.id=license.id;
        d.revoked_license_ids:=array_append(d.revoked_license_ids,license.id);
      END LOOP;
      UPDATE public.payment_disputes SET revoked_license_ids=d.revoked_license_ids WHERE stripe_dispute_id=p_dispute_id;
      PERFORM set_config('sellf.event_context','{"reason":"stripe_dispute"}',true);
      FOR original IN SELECT to_jsonb(a) FROM public.user_product_access a
        WHERE a.user_id=ANY(buyer_ids) AND a.product_id=ANY(product_ids)
        AND (a.access_expires_at IS NULL OR a.access_expires_at>stamp)
        AND (a.subscription_id IS NULL OR a.subscription_id=t.subscription_id)
        AND (a.transfer_transaction_id IS NULL OR a.transfer_transaction_id=t.id) FOR UPDATE
      LOOP
        d.account_access := d.account_access||jsonb_build_array(original);
        UPDATE public.user_product_access SET access_expires_at=stamp,expiry_notified_at=stamp WHERE id=(original->>'id')::uuid;
      END LOOP;
      WITH removed AS (
        DELETE FROM public.guest_purchases WHERE (session_id=t.session_id OR transaction_id=t.id)
          AND claimed_by_user_id IS NULL RETURNING *
      ) SELECT coalesce(jsonb_agg(jsonb_set(to_jsonb(removed),'{metadata}',coalesce(removed.metadata,'{}')||
        jsonb_build_object('_dispute_access_terms',coalesce(removed.metadata->'_dispute_access_terms',(
          SELECT jsonb_object_agg(p.id::text,jsonb_build_object('grantedAt',removed.created_at,'expiresAt',
            CASE WHEN coalesce((SELECT l.access_duration_override FROM public.payment_line_items l
              WHERE l.transaction_id=t.id AND l.product_id=p.id LIMIT 1),p.auto_grant_duration_days) IS NULL THEN NULL
            ELSE removed.created_at+make_interval(days=>coalesce((SELECT l.access_duration_override FROM public.payment_line_items l
              WHERE l.transaction_id=t.id AND l.product_id=p.id LIMIT 1),p.auto_grant_duration_days)) END))
          FROM public.products p WHERE p.id=ANY(product_ids)
        ))))),'[]') INTO d.guest_access FROM removed;
      UPDATE public.payment_disputes SET account_access=d.account_access,guest_access=d.guest_access WHERE stripe_dispute_id=p_dispute_id;
    END IF;
  END IF;

  next_status := t.status;
  IF p_status='won' THEN
    next_status := CASE WHEN t.status IN ('refunded','cancelled') THEN t.status
      WHEN coalesce(t.refunded_amount,0)>=t.amount THEN 'refunded'
      WHEN coalesce(t.refunded_amount,0)>0 THEN 'partially_refunded'
      ELSE d.previous_payment_status END;
    can_restore := next_status IN ('completed','partially_refunded') AND NOT EXISTS(
      SELECT 1 FROM public.payment_disputes other WHERE other.transaction_id=t.id AND other.stripe_dispute_id<>p_dispute_id AND other.status<>'won');
    can_restore_license:=can_restore;
    IF can_restore_license THEN
      PERFORM l.id FROM public.issued_licenses l WHERE l.order_id=ANY(public.license_order_references(t)) ORDER BY l.id FOR UPDATE;
      FOR license IN SELECT l.id FROM public.issued_licenses l WHERE l.id=ANY(d.revoked_license_ids)
        AND l.revoked_by_dispute_id=p_dispute_id AND l.revoked_at IS NOT NULL
        AND NOT EXISTS(SELECT 1 FROM public.issued_licenses other WHERE other.original_seller_id=l.original_seller_id
          AND other.order_id=l.order_id AND other.revoked_at IS NOT NULL AND other.revoked_by_dispute_id IS DISTINCT FROM p_dispute_id)
        ORDER BY l.id FOR UPDATE
      LOOP
        UPDATE public.issued_licenses l SET revoked_at=NULL,revoked_by_dispute_id=NULL WHERE l.id=license.id RETURNING l.* INTO restored_license;
        restored_licenses:=restored_licenses||jsonb_build_array(public.license_event_snapshot(restored_license));
      END LOOP;
    END IF;
    IF t.subscription_id IS NOT NULL THEN
      can_restore := can_restore AND EXISTS(SELECT 1 FROM public.subscriptions s WHERE s.id=t.subscription_id
        AND s.status IN ('active','trialing','past_due') AND (s.current_period_end IS NULL OR s.current_period_end>stamp));
    END IF;
    IF can_restore THEN
      PERFORM set_config('sellf.event_context','{"reason":"dispute_won"}',true);
      FOR item IN SELECT value FROM jsonb_array_elements(d.account_access) LOOP
        IF item->>'access_expires_at' IS NULL OR (item->>'access_expires_at')::timestamptz>stamp THEN
          UPDATE public.user_product_access a SET access_expires_at=CASE WHEN item ? 'retainedVersion' THEN
              CASE WHEN a.access_expires_at IS NULL OR item->>'access_expires_at' IS NULL THEN NULL
                ELSE greatest(a.access_expires_at, (item->>'access_expires_at')::timestamptz) END
              ELSE (item->>'access_expires_at')::timestamptz END,
            expiry_notified_at=(item->>'expiry_notified_at')::timestamptz
            WHERE id=(item->>'id')::uuid AND (access_expires_at=d.suspended_at
              OR (version=(item->>'retainedVersion')::integer
                AND access_expires_at IS NOT DISTINCT FROM (item->>'retainedExpiresAt')::timestamptz))
              AND user_id=(item->>'user_id')::uuid AND product_id=(item->>'product_id')::uuid
              AND subscription_id IS NOT DISTINCT FROM (item->>'subscription_id')::uuid
              AND access_duration_days IS NOT DISTINCT FROM CASE WHEN item ? 'retainedVersion'
                THEN (item->>'retainedDuration')::integer ELSE (item->>'access_duration_days')::integer END
            RETURNING a.access_expires_at INTO restored_until;
          GET DIAGNOSTICS changed=ROW_COUNT; restored := restored OR changed>0;
          IF changed>0 THEN restored_access:=restored_access||jsonb_build_array(jsonb_build_object(
            'productId',item->'product_id','userId',item->'user_id','grantedAt',item->'access_granted_at','expiresAt',restored_until)); END IF;
        END IF;
      END LOOP;
      FOR item IN SELECT value FROM jsonb_array_elements(d.guest_access) LOOP
        IF EXISTS(SELECT 1 FROM jsonb_each(item->'metadata'->'_dispute_access_terms') saved
          WHERE saved.value->>'expiresAt' IS NULL OR (saved.value->>'expiresAt')::timestamptz>stamp) THEN
          INSERT INTO public.guest_purchases SELECT (jsonb_populate_record(NULL::public.guest_purchases,item)).*
            ON CONFLICT DO NOTHING;
          GET DIAGNOSTICS changed=ROW_COUNT; restored := restored OR changed>0;
          IF changed>0 THEN
            FOR term IN SELECT * FROM jsonb_each(item->'metadata'->'_dispute_access_terms') LOOP
              IF term.value->>'expiresAt' IS NULL OR (term.value->>'expiresAt')::timestamptz>stamp THEN
                restored_access:=restored_access||jsonb_build_array(jsonb_build_object('productId',term.key,'userId',NULL,
                  'guestPurchaseId',item->'id','grantedAt',term.value->'grantedAt','expiresAt',term.value->'expiresAt'));
              END IF;
            END LOOP;
          END IF;
        END IF;
      END LOOP;
    END IF;
  ELSIF t.status NOT IN ('refunded','cancelled') THEN next_status := 'disputed';
  END IF;
  UPDATE public.payment_transactions SET status=next_status,updated_at=stamp,
    metadata=coalesce(metadata,'{}')||jsonb_build_object('dispute_id',p_dispute_id,'dispute_reason',p_reason,
      'dispute_status',p_status,'dispute_created',p_created)
    WHERE id=t.id;
  SELECT stripe_subscription_id INTO stripe_subscription FROM public.subscriptions WHERE id=t.subscription_id;
  result := jsonb_build_object(
    'customer',jsonb_build_object('email',t.customer_email,'userId',t.user_id),
    'product',jsonb_build_object('id',t.product_id),
    'payment',jsonb_build_object('id',t.id,'amount',t.amount,'currency',t.currency,'sessionId',t.session_id,
      'paymentIntentId',t.stripe_payment_intent_id,'stripeInvoiceId',t.stripe_invoice_id,'subscriptionId',t.subscription_id,
      'statusBefore',t.status,'statusAfter',next_status),
    'dispute',jsonb_build_object('stripeDisputeId',p_dispute_id,'status',p_status,'reason',p_reason,'amount',p_amount,
      'currency',upper(p_currency),'createdAt',p_created,'accessRevoked',p_status<>'won','accessRestored',restored,
      'licenseRestored',jsonb_array_length(restored_licenses)>0,'restoredLicenses',restored_licenses,'restoredAccess',restored_access));
  IF t.subscription_id IS NOT NULL THEN result:=result||jsonb_build_object('subscription',jsonb_build_object(
    'id',t.subscription_id,'stripeSubscriptionId',stripe_subscription)); END IF;
  UPDATE public.payment_disputes SET status=p_status,closed=p_closed,payload=result WHERE stripe_dispute_id=p_dispute_id;
  PERFORM set_config('sellf.event_context','',true);
  RETURN result;
END $$;


ALTER FUNCTION public.apply_payment_dispute_before_guest_claim(p_transaction_id uuid, p_dispute_id text, p_status text, p_closed boolean, p_reason text, p_amount integer, p_currency text, p_created timestamp with time zone) OWNER TO postgres;

--
-- Name: apply_shop_vat_defaults(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.apply_shop_vat_defaults() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tax_rate numeric;
  v_vat_exempt boolean;
  v_exempt_note text;
BEGIN
  SELECT tax_rate, is_vat_exempt, vat_exempt_note
    INTO v_tax_rate, v_vat_exempt, v_exempt_note
    FROM public.shop_config
    ORDER BY created_at
    LIMIT 1;

  IF NEW.vat_rate IS NULL AND NEW.vat_exempt = false THEN
    IF v_vat_exempt THEN
      NEW.vat_exempt := true;
    ELSIF v_tax_rate IS NOT NULL THEN
      NEW.vat_rate := CASE WHEN v_tax_rate < 1 THEN v_tax_rate * 100 ELSE v_tax_rate END;
    END IF;
  END IF;

  IF NEW.vat_exempt = true AND NEW.vat_exempt_note IS NULL THEN
    NEW.vat_exempt_note := v_exempt_note;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.apply_shop_vat_defaults() OWNER TO postgres;

--
-- Name: attach_order_payment_session(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.attach_order_payment_session(p_attempt uuid, p_session_id text, p_url text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  UPDATE public.order_payment_attempts SET stripe_session_id=p_session_id,checkout_url=p_url,status='open'
    WHERE id=p_attempt AND status='opening';
  IF NOT FOUND THEN RAISE EXCEPTION 'Attempt not opening' USING ERRCODE='22023'; END IF;
END $$;


ALTER FUNCTION public.attach_order_payment_session(p_attempt uuid, p_session_id text, p_url text) OWNER TO postgres;

--
-- Name: attribution_text(jsonb, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.attribution_text(p jsonb, k text, max_len integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT CASE WHEN jsonb_typeof(p) = 'object' AND jsonb_typeof(p->k) = 'string'
    THEN left(nullif(btrim(regexp_replace(p->>k, '[[:cntrl:]]', '', 'g')), ''), max_len) END
$$;


ALTER FUNCTION public.attribution_text(p jsonb, k text, max_len integer) OWNER TO postgres;

--
-- Name: attribution_time(jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.attribution_time(p jsonb, k text) RETURNS timestamp with time zone
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
BEGIN
  IF jsonb_typeof(p) IS DISTINCT FROM 'object' OR jsonb_typeof(p->k) IS DISTINCT FROM 'string' THEN
    RETURN NULL;
  END IF;
  BEGIN
    RETURN (p->>k)::timestamptz;
  EXCEPTION WHEN OTHERS THEN
    RETURN NULL;
  END;
END $$;


ALTER FUNCTION public.attribution_time(p jsonb, k text) OWNER TO postgres;

--
-- Name: audit_checkout_profile(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.audit_checkout_profile() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF (TG_OP = 'INSERT' AND NEW.checkout_profile IS NOT NULL)
     OR (TG_OP = 'UPDATE' AND OLD.checkout_profile IS DISTINCT FROM NEW.checkout_profile) THEN
    INSERT INTO public.audit_log(table_name, operation, new_values, user_id, performed_by)
    VALUES ('products', 'UPDATE', jsonb_build_object('action', 'product.checkout_profile.update', 'product_id', NEW.id,
      'enabled', NEW.checkout_profile IS NOT NULL), (select auth.uid()), (select auth.uid()));
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.audit_checkout_profile() OWNER TO postgres;

--
-- Name: audit_trigger_function(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.audit_trigger_function() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    INSERT INTO public.audit_log (table_name, operation, old_values, user_id)
    VALUES (TG_TABLE_NAME, TG_OP, row_to_json(OLD), auth.uid());
    RETURN OLD;
  ELSIF TG_OP = 'UPDATE' THEN
    INSERT INTO public.audit_log (table_name, operation, old_values, new_values, user_id)
    VALUES (TG_TABLE_NAME, TG_OP, row_to_json(OLD), row_to_json(NEW), auth.uid());
    RETURN NEW;
  ELSIF TG_OP = 'INSERT' THEN
    INSERT INTO public.audit_log (table_name, operation, new_values, user_id)
    VALUES (TG_TABLE_NAME, TG_OP, row_to_json(NEW), auth.uid());
    RETURN NEW;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.audit_trigger_function() OWNER TO postgres;

--
-- Name: bank_transfer_order(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.bank_transfer_order(p_order jsonb, p_lines jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE cfg public.bank_transfer_config%ROWTYPE; result jsonb; txid uuid; buyer_type text;
  email text:=lower(btrim(p_order->>'customer_email')); profile jsonb; transfer jsonb; person record;
  is_event boolean; starts timestamptz; remind timestamptz; release timestamptz; due timestamptz;
BEGIN
  SELECT * INTO STRICT cfg FROM public.bank_transfer_config WHERE id;
  SELECT checkout_profile,event_mode INTO profile,is_event FROM public.products WHERE id=(p_order->>'product_id')::uuid AND is_active
    AND product_type='one_time' AND NOT is_bundle AND NOT allow_custom_price FOR SHARE;
  buyer_type:=p_order->'order_details'->'buyer'->>'type';
  IF NOT cfg.bank_transfer_enabled OR profile IS NULL OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(profile->'modules') m
    WHERE m->>'id'='buyer' AND m->'bank_transfer_for' ? buyer_type AND m->'types' ? buyer_type)
    OR NOT public.validate_email_format(email) OR (p_order->'terms_required' IS DISTINCT FROM 'false'::jsonb
      AND (p_order->'order_details'->'buyer'->>'terms_accepted') IS DISTINCT FROM 'true') THEN
    RAISE EXCEPTION 'Transfer unavailable' USING ERRCODE='22023';
  END IF;
  IF coalesce(is_event,false) AND cfg.reservation_enabled THEN
    remind:=now()+make_interval(hours=>cfg.reservation_reminder_hours);
    release:=now()+make_interval(hours=>cfg.reservation_release_hours);
    SELECT s.starts_at INTO starts FROM jsonb_array_elements(p_lines) l
      JOIN public.product_sessions s ON s.id=(l->>'session_id')::uuid WHERE l->>'item_type'='main_product';
    -- A transfer cannot hold a seat past the start of the session; the buyer pays online instead.
    IF starts IS NOT NULL AND starts<=release THEN RAISE EXCEPTION 'Transfer unavailable' USING ERRCODE='22023'; END IF;
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(email,1));
  IF (SELECT count(*) FROM public.payment_transactions WHERE payment_provider='bank_transfer' AND status='awaiting_payment'
    AND lower(customer_email)=email)>=cfg.bank_transfer_max_unpaid_per_email THEN RAISE EXCEPTION 'unpaid_limit' USING ERRCODE='P0429'; END IF;
  p_order:=p_order||jsonb_build_object('payment_provider','bank_transfer','customer_email',email,'session_id',NULL,'stripe_payment_intent_id',NULL,
    'metadata',coalesce(p_order->'metadata','{}')||jsonb_build_object('access_on_placement',cfg.bank_transfer_grant_access_on_placement));
  result:=public.place_order(p_order,p_lines); txid:=(result->>'transaction_id')::uuid;
  transfer:=jsonb_build_object('holder',cfg.bank_account_holder,'account',cfg.bank_account_number,'bank',cfg.bank_name,
    'title',replace(cfg.bank_transfer_title_template,'{order_number}',result->>'order_number'));
  -- The payment term (invoice deadline) stays the seller's due days; the timed reservation is separate.
  due:=now()+make_interval(days=>cfg.bank_transfer_due_days);
  UPDATE public.payment_transactions SET payment_due_at=due,reminder_at=remind,release_at=release,transfer_details=transfer WHERE id=txid;
  IF cfg.bank_transfer_grant_access_on_placement THEN
    INSERT INTO public.guest_purchases(customer_email,product_id,transaction_amount,transaction_id)
      SELECT email,product_id,0,txid FROM public.payment_line_items WHERE transaction_id=txid ON CONFLICT DO NOTHING;
    INSERT INTO public.guest_purchases(customer_email,product_id,transaction_amount,transaction_id)
      SELECT DISTINCT lower(btrim(p->>'email')),li.product_id,0,txid
      FROM jsonb_array_elements(coalesce(p_order->'order_details'->'participants'->'people','[]')) p
      CROSS JOIN public.payment_line_items li WHERE li.transaction_id=txid AND li.item_type='order_bump'
      AND public.validate_email_format(lower(btrim(p->>'email'))) ON CONFLICT DO NOTHING;
    FOR person IN SELECT DISTINCT u.id FROM auth.users u JOIN public.guest_purchases gp ON gp.customer_email=lower(u.email)
      WHERE gp.transaction_id=txid AND u.email_confirmed_at IS NOT NULL LOOP
      PERFORM public.claim_guest_purchases_for_user(person.id);
    END LOOP;
  END IF;
  RETURN result||jsonb_build_object('currency',p_order->>'currency','dueAt',due,'reminderAt',remind,'releaseAt',release,'transfer',transfer);
END $$;


ALTER FUNCTION public.bank_transfer_order(p_order jsonb, p_lines jsonb) OWNER TO postgres;

--
-- Name: batch_check_user_product_access(text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.batch_check_user_product_access(product_slugs_param text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '2s'
    AS $$
DECLARE
    result JSONB := '{}';
    slug TEXT;
    has_access BOOLEAN;
    current_user_id UUID;
    clean_slug TEXT;
    safe_key TEXT;
BEGIN
    -- Rate limiting: 200 calls per hour per user (increased for checkout)
    IF NOT public.check_rate_limit('batch_check_user_product_access'::TEXT, 200, 3600) THEN
        RAISE EXCEPTION 'Rate limit exceeded for batch_check_user_product_access';
    END IF;

    -- Input validation
    IF product_slugs_param IS NULL OR array_length(product_slugs_param, 1) IS NULL THEN
        RETURN result;
    END IF;
    
    -- Limit array size to prevent DoS attacks (reduced from 50 to 20)
    IF array_length(product_slugs_param, 1) > 20 THEN
        RAISE EXCEPTION 'Too many product slugs requested (maximum 20)';
    END IF;
    
    -- Get current authenticated user ID
    current_user_id := auth.uid();
    IF current_user_id IS NULL THEN
        RETURN result;
    END IF;
    
    -- Check access for each product slug with proper sanitization
    FOREACH slug IN ARRAY product_slugs_param
    LOOP
        -- Validate input length first
        IF slug IS NULL OR length(slug) = 0 OR length(slug) > 100 THEN
            CONTINUE; -- Skip invalid slugs completely
        END IF;
        
        -- Sanitize slug: only allow alphanumeric, hyphens, and underscores
        clean_slug := regexp_replace(slug, '[^a-zA-Z0-9_-]', '', 'g');
        
        -- Skip empty or invalid slugs after sanitization
        IF clean_slug IS NULL OR length(clean_slug) = 0 THEN
            CONTINUE;
        END IF;
        
        -- Create safe JSON key (use clean_slug for both query and key)
        safe_key := clean_slug;
        
        -- Use parameterized query to prevent SQL injection
        -- NOTE: is_active controls product visibility for NEW purchases only
        -- Users who already have access keep it regardless of is_active status
        SELECT EXISTS (
            SELECT 1
            FROM public.user_product_access upa
            JOIN public.products p ON upa.product_id = p.id
            WHERE upa.user_id = current_user_id
              AND p.slug = clean_slug
              -- Check temporal access for user (only condition that revokes access)
              AND (upa.access_expires_at IS NULL OR upa.access_expires_at >= NOW())
        ) INTO has_access;
        
        -- Use sanitized key for JSON to prevent injection
        result := result || jsonb_build_object(safe_key, has_access);
    END LOOP;
    
    RETURN result;
END;
$$;


ALTER FUNCTION public.batch_check_user_product_access(product_slugs_param text[]) OWNER TO postgres;

--
-- Name: FUNCTION batch_check_user_product_access(product_slugs_param text[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.batch_check_user_product_access(product_slugs_param text[]) IS 'Batch check user access for multiple products. Limited to 20 products per call with rate limiting.';


--
-- Name: begin_pending_order_update(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.begin_pending_order_update(p_order jsonb, p_lines jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  tx public.payment_transactions%ROWTYPE;
  priced jsonb;
  next_version integer;
  base_metadata jsonb;
BEGIN
  IF jsonb_typeof(p_order) IS DISTINCT FROM 'object' OR coalesce(p_order->>'payment_provider', 'stripe') <> 'stripe'
    OR coalesce(p_order->>'session_id', '') = '' THEN
    RAISE EXCEPTION 'Invalid order payload' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO tx FROM public.payment_transactions WHERE session_id = p_order->>'session_id' FOR UPDATE;
  -- Only an unpaid online order of the same product, buyer and currency; event orders hold seats
  -- for the ordered quantity and get a new session instead.
  IF NOT FOUND OR tx.status <> 'pending' OR tx.payment_provider <> 'stripe'
    OR tx.product_id IS DISTINCT FROM (p_order->>'product_id')::uuid
    OR tx.user_id IS DISTINCT FROM (p_order->>'user_id')::uuid
    OR lower(tx.customer_email) IS DISTINCT FROM lower(trim(p_order->>'customer_email'))
    OR upper(tx.currency) IS DISTINCT FROM upper(p_order->>'currency')
    OR EXISTS (SELECT 1 FROM public.products WHERE id = tx.product_id AND event_mode)
    OR EXISTS (SELECT 1 FROM public.seat_reservations WHERE transaction_id = tx.id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'order_not_replaceable');
  END IF;
  IF EXISTS (SELECT 1 FROM public.checkout_cart_versions WHERE transaction_id = tx.id
    AND state = 'updating' AND created_at > now() - interval '60 seconds') THEN
    RETURN jsonb_build_object('success', false, 'error', 'update_in_progress');
  END IF;
  -- An update that never finished: Stripe may or may not carry it, so it stays payable.
  UPDATE public.checkout_cart_versions SET state = 'unconfirmed' WHERE transaction_id = tx.id AND state = 'updating';
  priced := public._price_order_lines(p_order, p_lines);
  IF NOT EXISTS (SELECT 1 FROM public.checkout_cart_versions WHERE transaction_id = tx.id) THEN
    INSERT INTO public.checkout_cart_versions (transaction_id, version, lines, amount, coupon_id, metadata, state)
    SELECT tx.id, 1, coalesce(jsonb_agg(to_jsonb(li)), '[]'::jsonb), tx.amount, tx.coupon_id,
      coalesce(tx.metadata, '{}'::jsonb), 'placed'
    FROM public.payment_line_items li WHERE li.transaction_id = tx.id;
  END IF;
  SELECT max(version) + 1, (array_agg(metadata ORDER BY version))[1] INTO next_version, base_metadata
    FROM public.checkout_cart_versions WHERE transaction_id = tx.id;
  IF next_version > 100 THEN
    RETURN jsonb_build_object('success', false, 'error', 'order_not_replaceable');
  END IF;
  INSERT INTO public.checkout_cart_versions (transaction_id, version, lines, amount, coupon_id, metadata, state)
  VALUES (tx.id, next_version, priced->'lines', (priced->>'charge')::numeric, (p_order->>'coupon_id')::uuid,
    base_metadata || coalesce(p_order->'metadata', '{}'::jsonb), 'updating');
  RETURN jsonb_build_object('success', true, 'transaction_id', tx.id, 'version', next_version, 'amount', (priced->>'charge')::numeric);
END;
$$;


ALTER FUNCTION public.begin_pending_order_update(p_order jsonb, p_lines jsonb) OWNER TO postgres;

--
-- Name: bind_access_license(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.bind_access_license() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE a public.user_product_access;
BEGIN
  IF NEW.access_grant_id IS NULL THEN RETURN NEW; END IF;
  SELECT * INTO a FROM public.user_product_access WHERE id = NEW.access_grant_id FOR UPDATE;
  IF NOT FOUND OR NOT a.license_requested OR a.user_id IS DISTINCT FROM NEW.user_id
    OR a.product_id IS DISTINCT FROM NEW.product_id OR NEW.order_id <> 'access_' || a.id::text THEN
    RAISE EXCEPTION 'Access grant is not available for license issuance';
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.bind_access_license() OWNER TO postgres;

