--
-- Name: check_application_rate_limit(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_application_rate_limit(identifier_param text, action_type_param text, max_requests integer, window_minutes integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  window_start_param TIMESTAMPTZ;
  current_count INTEGER;
BEGIN
  -- Input validation
  IF identifier_param IS NULL OR length(identifier_param) = 0 OR length(identifier_param) > 200 THEN
    RETURN FALSE;
  END IF;

  IF action_type_param IS NULL OR length(action_type_param) = 0 OR length(action_type_param) > 100 THEN
    RETURN FALSE;
  END IF;

  IF window_minutes IS NULL OR window_minutes < 1 OR window_minutes > 10080 THEN
    RETURN FALSE;
  END IF;

  -- Calculate window start (round down to an epoch-aligned window boundary,
  -- so windows longer than 60 minutes stay correctly sized).
  window_start_param := to_timestamp(
    floor(extract(epoch FROM now()) / (window_minutes * 60)) * (window_minutes * 60)
  );

  -- Try to increment existing record or insert new one
  INSERT INTO public.application_rate_limits (identifier, action_type, window_start, call_count)
  VALUES (identifier_param, action_type_param, window_start_param, 1)
  ON CONFLICT (identifier, action_type, window_start)
  DO UPDATE SET
    call_count = public.application_rate_limits.call_count + 1,
    updated_at = NOW()
  RETURNING public.application_rate_limits.call_count INTO current_count;

  -- Check if we're over the limit
  RETURN current_count <= max_requests;
END;
$$;


ALTER FUNCTION public.check_application_rate_limit(identifier_param text, action_type_param text, max_requests integer, window_minutes integer) OWNER TO postgres;

--
-- Name: FUNCTION check_application_rate_limit(identifier_param text, action_type_param text, max_requests integer, window_minutes integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.check_application_rate_limit(identifier_param text, action_type_param text, max_requests integer, window_minutes integer) IS 'Application-level rate limiting for Next.js API routes. Use this from /lib/rate-limiting.ts. Windows are epoch-aligned so sizes > 60 minutes work correctly.';


--
-- Name: check_rate_limit(text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_rate_limit(function_name_param text, max_calls integer DEFAULT 100, time_window_seconds integer DEFAULT 3600, identifier_param text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    bucket_id UUID;
    window_start_param TIMESTAMPTZ;
    current_count INTEGER;
BEGIN
    IF function_name_param IS NULL OR length(function_name_param) = 0 OR length(function_name_param) > 100 THEN
        RETURN FALSE;
    END IF;

    IF identifier_param IS NOT NULL AND length(identifier_param) > 200 THEN
        RETURN FALSE;
    END IF;

    IF COALESCE(current_setting('request.jwt.claims', true), '') = ''
       OR (select auth.role()) = 'service_role' THEN
        RETURN TRUE;
    END IF;

    window_start_param := date_trunc('hour', NOW()) +
                   INTERVAL '1 second' * (FLOOR(EXTRACT(EPOCH FROM NOW() - date_trunc('hour', NOW())) / time_window_seconds) * time_window_seconds);

    IF identifier_param IS NOT NULL AND length(identifier_param) > 0 THEN
        bucket_id := md5('id:' || identifier_param || ':' || function_name_param)::uuid;
    ELSE
        bucket_id := COALESCE(
            (select auth.uid()),
            md5('anon:' || function_name_param)::uuid
        );
    END IF;

    INSERT INTO public.rate_limits (user_id, function_name, window_start, call_count)
    VALUES (bucket_id, function_name_param, window_start_param, 1)
    ON CONFLICT (user_id, function_name, window_start)
    DO UPDATE SET
        call_count = public.rate_limits.call_count + 1,
        updated_at = NOW()
    RETURNING public.rate_limits.call_count INTO current_count;

    RETURN current_count <= max_calls;
END;
$$;


ALTER FUNCTION public.check_rate_limit(function_name_param text, max_calls integer, time_window_seconds integer, identifier_param text) OWNER TO postgres;

--
-- Name: check_refund_eligibility(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_refund_eligibility(transaction_id_param uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '5s'
    AS $$
DECLARE
    transaction_record RECORD;
    days_since_purchase INTEGER;
    existing_request RECORD;
    is_service BOOLEAN;
BEGIN
    is_service := (select auth.role()) = 'service_role';

    IF NOT is_service AND NOT public.check_rate_limit('check_refund_eligibility', 60, 3600) THEN
        RETURN jsonb_build_object('eligible', false, 'reason', 'rate_limited');
    END IF;

    -- Get transaction details with product info. Customers only see their own
    -- purchases; anything else reads as not found.
    SELECT pt.*, p.is_refundable, p.refund_period_days, p.name as product_name
    INTO transaction_record
    FROM public.payment_transactions pt
    JOIN public.products p ON pt.product_id = p.id
    WHERE pt.id = transaction_id_param
      AND (is_service OR (
        (select auth.uid()) IS NOT NULL
        AND pt.user_id IS NOT DISTINCT FROM (select auth.uid())
      ));

    IF NOT FOUND THEN
        RETURN jsonb_build_object('eligible', false, 'reason', 'transaction_not_found');
    END IF;

    IF transaction_record.status = 'refunded' THEN
        RETURN jsonb_build_object('eligible', false, 'reason', 'already_refunded');
    END IF;

    IF NOT transaction_record.is_refundable THEN
        RETURN jsonb_build_object('eligible', false, 'reason', 'product_not_refundable');
    END IF;

    -- Check for existing pending request
    SELECT * INTO existing_request
    FROM public.refund_requests
    WHERE refund_requests.transaction_id = transaction_id_param
      AND status IN ('pending', 'approved');

    IF FOUND THEN
        RETURN jsonb_build_object(
            'eligible', false,
            'reason', 'request_already_exists',
            'existing_request_id', existing_request.id,
            'existing_request_status', existing_request.status
        );
    END IF;

    -- Calculate days since purchase
    days_since_purchase := EXTRACT(DAY FROM NOW() - transaction_record.created_at);

    -- Check refund period
    IF transaction_record.refund_period_days IS NOT NULL AND
       days_since_purchase > transaction_record.refund_period_days THEN
        RETURN jsonb_build_object(
            'eligible', false,
            'reason', 'refund_period_expired',
            'refund_period_days', transaction_record.refund_period_days,
            'days_since_purchase', days_since_purchase
        );
    END IF;

    -- Transaction is eligible
    RETURN jsonb_build_object(
        'eligible', true,
        'transaction_id', transaction_record.id,
        'product_name', transaction_record.product_name,
        'amount', transaction_record.amount,
        'currency', transaction_record.currency,
        'refund_period_days', transaction_record.refund_period_days,
        'days_since_purchase', days_since_purchase,
        'days_remaining', CASE
            WHEN transaction_record.refund_period_days IS NOT NULL
            THEN transaction_record.refund_period_days - days_since_purchase
            ELSE NULL
        END
    );
END;
$$;


ALTER FUNCTION public.check_refund_eligibility(transaction_id_param uuid) OWNER TO postgres;

--
-- Name: check_user_product_access(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_user_product_access(product_slug_param text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '2s'
    AS $$
DECLARE
    clean_slug TEXT;
BEGIN
    -- Rate limiting: 1000 calls per hour per user (increased for checkout)
    IF NOT public.check_rate_limit('check_user_product_access'::TEXT, 1000, 3600) THEN
        RAISE EXCEPTION 'Rate limit exceeded for check_user_product_access';
    END IF;

    -- Input validation and sanitization
    IF product_slug_param IS NULL THEN
        RETURN FALSE;
    END IF;
    
    -- Sanitize slug: only allow alphanumeric, hyphens, and underscores
    clean_slug := regexp_replace(product_slug_param, '[^a-zA-Z0-9_-]', '', 'g');
    
    -- Validate sanitized slug
    IF clean_slug IS NULL OR length(clean_slug) = 0 OR length(clean_slug) > 100 THEN
        RETURN FALSE;
    END IF;
    
    -- Get current authenticated user ID
    IF auth.uid() IS NULL THEN
        RETURN FALSE;
    END IF;
    
    -- NOTE: is_active controls product visibility for NEW purchases only
    -- Users who already have access keep it regardless of is_active status
    -- Access is revoked only when: product is deleted OR access_expires_at passes
    RETURN EXISTS (
        SELECT 1
        FROM public.user_product_access upa
        JOIN public.products p ON upa.product_id = p.id
        WHERE upa.user_id = auth.uid()  -- Use authenticated user ID
          AND p.slug = clean_slug       -- Use sanitized slug
          -- Check temporal access for user (only condition that revokes access)
          AND (upa.access_expires_at IS NULL OR upa.access_expires_at >= NOW())
    );
END;
$$;


ALTER FUNCTION public.check_user_product_access(product_slug_param text) OWNER TO postgres;

--
-- Name: FUNCTION check_user_product_access(product_slug_param text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.check_user_product_access(product_slug_param text) IS 'Check if authenticated user has access to a specific product by slug. Includes rate limiting and input sanitization.';


