-- Name: check_waitlist_config(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_waitlist_config() RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT (select public.is_admin()) THEN
    RAISE EXCEPTION 'Admin access required' USING ERRCODE = '42501';
  END IF;

  RETURN json_build_object(
    'has_webhook', EXISTS(
      SELECT 1 FROM public.webhook_endpoints
      WHERE 'waitlist.signup' = ANY(events)
        AND is_active = true
    ),
    'products_count', (
      SELECT COUNT(*)::integer
      FROM public.products
      WHERE enable_waitlist = true
    )
  );
END;
$$;


ALTER FUNCTION public.check_waitlist_config() OWNER TO postgres;

