-- Name: FUNCTION check_waitlist_config(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.check_waitlist_config() IS 'Check if waitlist.signup webhook exists and count products with waitlist enabled. Used for admin warnings.';


--
-- Name: check_webhook_delivery_date(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_webhook_delivery_date() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE changed timestamptz; source_created timestamptz;
BEGIN
  IF TG_OP = 'INSERT' AND NEW.delivery_key ~ ':business_[0-9a-f-]{36}$' THEN
    SELECT created_at INTO source_created FROM public.business_events
      WHERE id = substring(NEW.delivery_key from ':business_([0-9a-f-]{36})$')::uuid;
    NEW.created_at := least(NEW.created_at, source_created);
  ELSIF TG_OP = 'UPDATE' THEN
    NEW.created_at := OLD.created_at;
    NEW.endpoint_id := OLD.endpoint_id;
  END IF;
  SELECT url_changed_at INTO changed FROM public.webhook_endpoints WHERE id = NEW.endpoint_id;
  IF NEW.created_at < changed THEN
    IF TG_OP = 'UPDATE' AND NEW.status = 'pending_retry' AND OLD.status <> 'pending_retry' THEN
      RAISE EXCEPTION 'Endpoint URL changed' USING ERRCODE = 'PT409';
    END IF;
    IF NEW.status = 'pending_retry' THEN
      NEW.status := 'permanently_failed';
      NEW.next_retry_at := NULL;
      NEW.failed_permanently_at := clock_timestamp();
      NEW.error_message := 'Endpoint URL changed';
    END IF;
  END IF;
  RETURN NEW;
END $_$;


ALTER FUNCTION public.check_webhook_delivery_date() OWNER TO postgres;

--
-- Name: check_webhook_delivery_target(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_webhook_delivery_target(p_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.webhook_logs l JOIN public.webhook_endpoints e ON e.id=l.endpoint_id
    WHERE l.id=p_id AND l.created_at < e.url_changed_at) THEN
    RAISE EXCEPTION 'Endpoint URL changed' USING ERRCODE = 'PT409';
  END IF;
  RETURN true;
END $$;


ALTER FUNCTION public.check_webhook_delivery_target(p_id uuid) OWNER TO postgres;

--
-- Name: auth_mail_retries; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.auth_mail_retries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    email text NOT NULL,
    redirect_to text NOT NULL,
    data jsonb DEFAULT '{}'::jsonb NOT NULL,
    kind text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    next_attempt_at timestamp with time zone DEFAULT now() NOT NULL,
    last_error text,
    given_up_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    license_mail_key text,
    CONSTRAINT auth_mail_retries_attempts_check CHECK ((attempts >= 0)),
    CONSTRAINT auth_mail_retries_data_check CHECK (((jsonb_typeof(data) = 'object'::text) AND (octet_length((data)::text) <= 73728))),
    CONSTRAINT auth_mail_retries_email_check CHECK (((length(email) >= 3) AND (length(email) <= 320))),
    CONSTRAINT auth_mail_retries_kind_check CHECK ((kind = ANY (ARRAY['post_checkout'::text, 'license'::text]))),
    CONSTRAINT auth_mail_retries_last_error_check CHECK (((last_error IS NULL) OR (length(last_error) <= 40))),
    CONSTRAINT auth_mail_retries_redirect_to_check CHECK (((length(redirect_to) >= 1) AND (length(redirect_to) <= 2048)))
);


ALTER TABLE public.auth_mail_retries OWNER TO postgres;

--
-- Name: claim_auth_mail_retries(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_auth_mail_retries(p_limit integer DEFAULT 20) RETURNS SETOF public.auth_mail_retries
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  -- A purged license mail was never delivered: dropping its receipt lets a repeated grant send it again.
  WITH purged AS (
    DELETE FROM public.auth_mail_retries WHERE given_up_at < now() - interval '7 days' RETURNING license_mail_key
  )
  DELETE FROM public.license_mail_receipts r USING purged p WHERE r.mail_key = p.license_mail_key;
  RETURN QUERY
  UPDATE public.auth_mail_retries r SET attempts = r.attempts + 1, next_attempt_at = now() + interval '10 minutes'
  WHERE r.id IN (SELECT q.id FROM public.auth_mail_retries q WHERE q.given_up_at IS NULL AND q.next_attempt_at <= now()
    ORDER BY (q.kind = 'license') DESC, q.next_attempt_at LIMIT least(greatest(coalesce(p_limit, 20), 1), 100) FOR UPDATE SKIP LOCKED)
  RETURNING r.*;
END $$;


ALTER FUNCTION public.claim_auth_mail_retries(p_limit integer) OWNER TO postgres;

--
-- Name: business_events; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.business_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    event_type text NOT NULL,
    product_id uuid,
    payload jsonb NOT NULL,
    deduplication_key text,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    leased_until timestamp with time zone,
    dispatched_at timestamp with time zone,
    attempts integer DEFAULT 0 NOT NULL,
    next_attempt_at timestamp with time zone DEFAULT now() NOT NULL,
    last_error text,
    abandoned_at timestamp with time zone,
    CONSTRAINT business_events_attempts_check CHECK ((attempts >= 0)),
    CONSTRAINT business_events_event_type_check CHECK ((event_type = ANY (ARRAY['access.granted'::text, 'access.updated'::text, 'access.revoked'::text, 'access.expired'::text, 'order.abandoned'::text, 'seats.held'::text, 'seats.confirmed'::text, 'seats.released'::text, 'license.revoked'::text, 'license.restored'::text, 'invoicing.issued'::text, 'invoicing.failed'::text, 'invoicing.corrected'::text, 'commission.accrued'::text, 'commission.reversed'::text, 'payout.reserved'::text, 'payout.paid'::text, 'payout.cancelled'::text, 'refund.requested'::text, 'refund.request_approved'::text, 'refund.request_rejected'::text, 'refund.request_cancelled'::text, 'product.published'::text, 'product.unpublished'::text, 'product.price_changed'::text, 'product.sold_out'::text, 'license.issued'::text, 'license.expired'::text, 'order.participants_updated'::text, 'subscription.renewal_upcoming'::text, 'license.updated'::text, 'product.created'::text, 'product.updated'::text, 'product.deleted'::text]))),
    CONSTRAINT business_events_last_error_check CHECK (((last_error IS NULL) OR (length(last_error) <= 200)))
);


ALTER TABLE public.business_events OWNER TO postgres;

--
-- Name: claim_business_events(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_business_events(p_limit integer DEFAULT 100) RETURNS SETOF public.business_events
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  UPDATE public.business_events SET abandoned_at = now(), last_error = coalesce(last_error, 'lease_expired')
  WHERE dispatched_at IS NULL AND abandoned_at IS NULL AND attempts >= 8 AND (leased_until IS NULL OR leased_until < now());
  RETURN QUERY
  WITH picked AS (
    SELECT id FROM public.business_events
    WHERE dispatched_at IS NULL AND abandoned_at IS NULL AND next_attempt_at <= now()
      AND (leased_until IS NULL OR leased_until < now())
    ORDER BY next_attempt_at, created_at, id FOR UPDATE SKIP LOCKED LIMIT greatest(1, least(coalesce(p_limit, 100), 100))
  ),
  leased AS (
    UPDATE public.business_events b SET leased_until = now() + interval '1 minute', attempts = b.attempts + 1
    FROM picked WHERE b.id = picked.id RETURNING b.*
  )
  SELECT * FROM leased ORDER BY next_attempt_at, created_at, id;
END $$;


ALTER FUNCTION public.claim_business_events(p_limit integer) OWNER TO postgres;

--
-- Name: claim_guest_purchases_for_user(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_guest_purchases_for_user(p_user_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  buyer_email text; purchase public.guest_purchases; term record; terms jsonb := '{}';
  saved_context text := current_setting('sellf.event_context',true); result json;
BEGIN
  SELECT email INTO buyer_email FROM auth.users WHERE id=p_user_id AND email_confirmed_at IS NOT NULL;
  FOR purchase IN SELECT * FROM public.guest_purchases WHERE customer_email=buyer_email AND claimed_by_user_id IS NULL
    AND metadata ? '_dispute_access_terms' FOR UPDATE
  LOOP
    IF NOT EXISTS(SELECT 1 FROM jsonb_each(purchase.metadata->'_dispute_access_terms') saved
      WHERE saved.value->>'expiresAt' IS NULL OR (saved.value->>'expiresAt')::timestamptz>clock_timestamp()) THEN
      UPDATE public.guest_purchases SET claimed_by_user_id=p_user_id,claimed_at=now() WHERE id=purchase.id;
      CONTINUE;
    END IF;
    FOR term IN SELECT * FROM jsonb_each(purchase.metadata->'_dispute_access_terms') LOOP
      IF NOT terms ? term.key OR (terms->term.key->>'expiresAt' IS NOT NULL AND
        (term.value->>'expiresAt' IS NULL OR (term.value->>'expiresAt')::timestamptz>(terms->term.key->>'expiresAt')::timestamptz)) THEN
        terms:=terms||jsonb_build_object(term.key,term.value);
      END IF;
    END LOOP;
  END LOOP;
  -- A separate newly claimable order retains its own normal grant policy.
  FOR term IN SELECT DISTINCT p.id::text key FROM public.guest_purchases g JOIN public.products p ON
    p.id=g.product_id OR EXISTS(SELECT 1 FROM public.payment_transactions o WHERE (o.id=g.transaction_id OR (g.transaction_id IS NULL AND o.session_id=g.session_id))
      AND o.product_id=g.product_id AND p.id IN (SELECT public.order_granted_components(o.id)))
    OR (NOT EXISTS(SELECT 1 FROM public.payment_transactions o WHERE o.id=g.transaction_id OR (g.transaction_id IS NULL AND o.session_id=g.session_id))
      AND EXISTS(SELECT 1 FROM public.bundle_items b WHERE b.bundle_product_id=g.product_id AND b.component_product_id=p.id))
    OR EXISTS(SELECT 1 FROM public.payment_line_items l WHERE l.transaction_id=g.transaction_id AND l.product_id=p.id)
    WHERE g.customer_email=buyer_email AND g.claimed_by_user_id IS NULL AND NOT g.metadata ? '_dispute_access_terms'
      AND NOT EXISTS(SELECT 1 FROM public.payment_transactions t
        WHERE (t.id=g.transaction_id OR (g.transaction_id IS NULL AND t.session_id=g.session_id))
          AND (t.status IN ('refunded','disputed','cancelled') OR (t.amount>0 AND coalesce(t.refunded_amount,0)>=t.amount)))
  LOOP terms:=terms-term.key; END LOOP;
  PERFORM set_config('sellf.event_context',(coalesce(nullif(saved_context,'')::jsonb,'{}')||jsonb_build_object('guest_dispute_terms',terms))::text,true);
  result:=public._claim_guest_purchases_before_disputes(p_user_id);
  PERFORM set_config('sellf.event_context',coalesce(saved_context,''),true);
  PERFORM public.claim_paid_subscription_access(p_user_id);
  RETURN result;
END $$;


ALTER FUNCTION public.claim_guest_purchases_for_user(p_user_id uuid) OWNER TO postgres;

--
-- Name: claim_license_mail(text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_license_mail(p_key text, p_email text, p_redirect_to text, p_data jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE retry_id uuid;
BEGIN
  INSERT INTO public.license_mail_receipts(mail_key) VALUES(p_key) ON CONFLICT DO NOTHING;
  IF NOT FOUND THEN RETURN NULL; END IF;
  INSERT INTO public.auth_mail_retries(email,redirect_to,data,kind,next_attempt_at,last_error,license_mail_key)
    VALUES(lower(btrim(p_email)),p_redirect_to,p_data,'license',now()+interval '10 minutes','send_failed',p_key)
    RETURNING id INTO retry_id;
  RETURN retry_id;
END $$;


ALTER FUNCTION public.claim_license_mail(p_key text, p_email text, p_redirect_to text, p_data jsonb) OWNER TO postgres;

--
-- Name: claim_paid_subscription_access(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_paid_subscription_access(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  -- Serialize claims with changes to the payment ledger.
  PERFORM 1 FROM public.payment_transactions t
  JOIN public.subscriptions s ON s.id=t.subscription_id AND s.paid_access_invoice_id=t.stripe_invoice_id
  WHERE s.user_id=p_user_id AND s.status='canceled'
  ORDER BY t.id FOR UPDATE OF t;

  INSERT INTO public.user_product_access(user_id,product_id,subscription_id,access_granted_at,access_expires_at,grant_source)
  SELECT DISTINCT ON (s.product_id) s.user_id,s.product_id,s.id,now(),s.paid_access_expires_at,'subscription'
  FROM public.subscriptions s
  JOIN auth.users u ON u.id=s.user_id AND u.email_confirmed_at IS NOT NULL
  JOIN public.payment_transactions t ON t.subscription_id=s.id AND t.stripe_invoice_id=s.paid_access_invoice_id
    AND t.product_id=s.product_id AND t.status='completed' AND coalesce(t.refunded_amount,0)=0
  WHERE s.user_id=p_user_id AND s.status='canceled' AND s.paid_access_expires_at>now()
  ORDER BY s.product_id,s.paid_access_expires_at DESC,s.id
  ON CONFLICT (user_id,product_id) DO NOTHING;
END $$;


ALTER FUNCTION public.claim_paid_subscription_access(p_user_id uuid) OWNER TO postgres;

