--
-- Name: cleanup_expired_oto_coupons(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cleanup_expired_oto_coupons() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  deleted_count INTEGER;
BEGIN
  -- Delete OTO coupons that:
  -- 1. Are OTO coupons
  -- 2. Expired more than 1 hour ago (grace period)
  -- 3. Were never used
  DELETE FROM public.coupons
  WHERE is_oto_coupon = true
    AND expires_at < NOW() - INTERVAL '1 hour'
    AND current_usage_count = 0;

  GET DIAGNOSTICS deleted_count = ROW_COUNT;

  -- Optional: Log cleanup
  -- RAISE NOTICE 'Cleaned up % expired OTO coupons', deleted_count;

  RETURN deleted_count;
END;
$$;


