--
-- Name: clear_admin_cache(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.clear_admin_cache() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    current_user_id UUID;
    cache_key TEXT;
BEGIN
    -- Get current authenticated user
    current_user_id := (SELECT auth.uid());
    IF current_user_id IS NOT NULL THEN
        -- Clear the session-specific cache
        cache_key := 'app.user_is_admin_' || replace(current_user_id::TEXT, '-', '_');
        PERFORM set_config(cache_key, NULL, false);
    END IF;
END;
$$;


