--

CREATE FUNCTION public.clear_pending_free_grant_on_access() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  UPDATE auth.users u
  SET raw_app_meta_data = jsonb_set(
        u.raw_app_meta_data,
        '{pending_free_grants}',
        (u.raw_app_meta_data -> 'pending_free_grants') - NEW.product_id::TEXT
      )
  WHERE u.id = NEW.user_id
    AND COALESCE(u.raw_app_meta_data -> 'pending_free_grants', '[]'::jsonb) ? NEW.product_id::TEXT;
  RETURN NEW;
END;
$$;


