--
-- Name: get_abandoned_carts(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_abandoned_carts(days_ago integer DEFAULT 7, limit_count integer DEFAULT 100) RETURNS TABLE(id uuid, customer_email text, product_id uuid, product_name text, amount numeric, currency text, created_at timestamp with time zone, abandoned_at timestamp with time zone, expires_at timestamp with time zone, metadata jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  -- Check if user is admin or service_role
  IF (SELECT auth.role()) != 'service_role' AND
     NOT ( select public.is_admin() ) THEN
    RAISE EXCEPTION 'Access denied: Admin only';
  END IF;

  RETURN QUERY
  SELECT
    pt.id,
    pt.customer_email,
    pt.product_id,
    p.name AS product_name,
    pt.amount,
    pt.currency,
    pt.created_at,
    pt.abandoned_at,
    pt.expires_at,
    pt.metadata
  FROM public.payment_transactions pt
  LEFT JOIN public.products p ON pt.product_id = p.id
  WHERE pt.status IN ('pending', 'abandoned')
    AND pt.created_at > NOW() - (days_ago || ' days')::INTERVAL
  ORDER BY pt.created_at DESC
  LIMIT limit_count;
END;
$$;


