--
-- Name: get_admin_refund_requests(text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_admin_refund_requests(status_filter text DEFAULT NULL::text, limit_param integer DEFAULT 50, offset_param integer DEFAULT 0) RETURNS TABLE(request_id uuid, transaction_id uuid, user_id uuid, customer_email text, product_id uuid, product_name text, reason text, status text, requested_amount numeric, currency text, admin_id uuid, admin_response text, processed_at timestamp with time zone, created_at timestamp with time zone, purchase_date timestamp with time zone, stripe_payment_intent_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '10s'
    AS $$
BEGIN
    -- Check admin permission
    IF NOT ( select public.is_admin() ) THEN
        RETURN;
    END IF;

    RETURN QUERY
    SELECT
        rr.id as request_id,
        rr.transaction_id,
        rr.user_id,
        rr.customer_email,
        rr.product_id,
        p.name as product_name,
        rr.reason,
        rr.status,
        rr.requested_amount,
        rr.currency,
        rr.admin_id,
        rr.admin_response,
        rr.processed_at,
        rr.created_at,
        pt.created_at as purchase_date,
        pt.stripe_payment_intent_id
    FROM public.refund_requests rr
    JOIN public.products p ON rr.product_id = p.id
    JOIN public.payment_transactions pt ON rr.transaction_id = pt.id
    WHERE (status_filter IS NULL OR rr.status = status_filter)
    ORDER BY
        CASE WHEN rr.status = 'pending' THEN 0 ELSE 1 END,
        rr.created_at DESC
    LIMIT limit_param
    OFFSET offset_param;
END;
$$;


