--
-- Name: get_product_order_bumps(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_product_order_bumps(product_id_param uuid) RETURNS TABLE(bump_id uuid, bump_product_id uuid, bump_product_name text, bump_product_description text, bump_product_icon text, bump_price numeric, original_price numeric, bump_access_duration integer, bump_currency text, bump_title text, bump_description text, display_order integer, urgency_duration_minutes integer, vat_rate numeric, price_includes_vat boolean, vat_exempt boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    ob.id as bump_id,
    ob.bump_product_id,
    p.name as bump_product_name,
    p.description as bump_product_description,
    p.icon as bump_product_icon,
    COALESCE(ob.bump_price, p.price) as bump_price,
    p.price as original_price,
    COALESCE(ob.access_duration_days, p.auto_grant_duration_days) as bump_access_duration,
    p.currency as bump_currency,
    ob.bump_title,
    ob.bump_description,
    ob.display_order,
    ob.urgency_duration_minutes,
    p.vat_rate,
    p.price_includes_vat,
    p.vat_exempt
  FROM public.order_bumps ob
  INNER JOIN public.products p ON p.id = ob.bump_product_id
  WHERE ob.main_product_id = product_id_param
    AND ob.is_active = true
    AND p.is_active = true
  ORDER BY ob.display_order ASC, ob.created_at ASC;
END;
$$;


