--
-- Name: get_sales_chart_data(timestamp with time zone, timestamp with time zone, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_sales_chart_data(p_start_date timestamp with time zone, p_end_date timestamp with time zone, p_product_id uuid DEFAULT NULL::uuid, p_timezone text DEFAULT 'UTC'::text) RETURNS TABLE(date text, amount_by_currency jsonb, orders integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_timezone TEXT;
BEGIN
  IF NOT ( select public.is_admin() ) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  SELECT COALESCE(
    (SELECT tz.name FROM pg_catalog.pg_timezone_names tz WHERE tz.name = p_timezone),
    'UTC'
  ) INTO v_timezone;

  RETURN QUERY
  SELECT
    per_currency.day,
    COALESCE(jsonb_object_agg(per_currency.currency, per_currency.total), '{}'::jsonb),
    SUM(per_currency.orders)::INTEGER
  FROM (
    SELECT
      TO_CHAR(pt.created_at AT TIME ZONE v_timezone, 'YYYY-MM-DD') AS day,
      pt.currency,
      SUM(GREATEST(pt.amount - COALESCE(pt.refunded_amount, 0), 0)) AS total,
      COUNT(*) AS orders
    FROM public.payment_transactions pt
    WHERE pt.status IN ('completed', 'partially_refunded')
      AND pt.created_at >= p_start_date
      AND pt.created_at <= p_end_date
      AND (p_product_id IS NULL OR pt.product_id = p_product_id)
    GROUP BY 1, 2
  ) per_currency
  GROUP BY per_currency.day
  ORDER BY per_currency.day ASC;
END;
$$;


