-- Name: FUNCTION get_user_payment_history(user_id_param uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_user_payment_history(user_id_param uuid) IS '@graphql({"include": false})';


--
-- Name: get_user_profile(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_user_profile(user_id_param uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '5s'
    AS $$
DECLARE
    user_info JSONB;
    user_stats JSONB;
    user_access JSONB;
    current_user_id UUID;
BEGIN
    -- Input validation
    IF user_id_param IS NULL THEN
        RETURN NULL;
    END IF;
    
    -- Get current authenticated user
    current_user_id := auth.uid();
    IF current_user_id IS NULL THEN
        RAISE EXCEPTION 'Authentication required';
    END IF;
    
    -- Security check: only allow users to view their own profile, or admins to view any profile
    IF user_id_param != current_user_id THEN
        IF NOT EXISTS (SELECT 1 FROM public.admin_users WHERE user_id = current_user_id)
        THEN
            RAISE EXCEPTION 'Unauthorized: Can only view your own profile';
        END IF;
    END IF;
    
    -- Get user info from auth.users
    SELECT jsonb_build_object(
        'id', id,
        'email', email,
        'created_at', created_at,
        'email_confirmed_at', email_confirmed_at,
        'last_sign_in_at', last_sign_in_at,
        'user_metadata', raw_user_meta_data
    ) INTO user_info
    FROM auth.users
    WHERE id = user_id_param;
    
    -- Return null if user not found
    IF user_info IS NULL THEN
        RETURN NULL;
    END IF;
    
    -- Get user statistics
    SELECT jsonb_build_object(
        'total_products', total_products,
        'total_value', total_value,
        'last_access_granted_at', last_access_granted_at,
        'first_access_granted_at', first_access_granted_at
    ) INTO user_stats
    FROM public.user_access_stats
    WHERE user_id = user_id_param;
    
    -- Get user access details
    SELECT jsonb_agg(
        jsonb_build_object(
            'id', id,
            'product_id', product_id,
            'product_name', product_name,
            'product_slug', product_slug,
            'product_price', product_price,
            'product_currency', product_currency,
            'product_icon', product_icon,
            'product_is_active', product_is_active,
            'granted_at', access_created_at
        )
    ) INTO user_access
    FROM public.user_product_access_detailed
    WHERE user_id = user_id_param;
    
    -- Return the combined user profile
    RETURN jsonb_build_object(
        'user', user_info,
        'stats', user_stats,
        'access', COALESCE(user_access, '[]'::jsonb)
    );
END;
$$;


ALTER FUNCTION public.get_user_profile(user_id_param uuid) OWNER TO postgres;

--
-- Name: FUNCTION get_user_profile(user_id_param uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_user_profile(user_id_param uuid) IS 'Get complete user profile with access statistics. Users can only view their own profile, admins can view any profile.';


--
-- Name: get_user_purchases_with_refund_status(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_user_purchases_with_refund_status(user_id_param uuid DEFAULT NULL::uuid) RETURNS TABLE(transaction_id uuid, product_id uuid, product_name text, product_slug text, product_icon text, amount numeric, currency text, purchase_date timestamp with time zone, status text, refunded_amount numeric, is_refundable boolean, refund_period_days integer, days_since_purchase integer, refund_eligible boolean, refund_request_status text, refund_request_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '10s'
    AS $$
DECLARE
    target_user_id UUID;
BEGIN
    target_user_id := COALESCE(user_id_param, auth.uid());

    IF target_user_id IS NULL THEN
        RETURN;
    END IF;

    -- Only allow users to view their own purchases (or admins to view any)
    IF target_user_id != auth.uid() THEN
        IF NOT ( select public.is_admin() ) THEN
            RETURN;
        END IF;
    END IF;

    RETURN QUERY
    SELECT
        pt.id as transaction_id,
        p.id as product_id,
        p.name as product_name,
        p.slug as product_slug,
        p.icon as product_icon,
        pt.amount,
        pt.currency,
        pt.created_at as purchase_date,
        pt.status,
        pt.refunded_amount,
        p.is_refundable,
        p.refund_period_days,
        EXTRACT(DAY FROM NOW() - pt.created_at)::INTEGER as days_since_purchase,
        CASE
            WHEN pt.status = 'refunded' THEN false
            WHEN NOT p.is_refundable THEN false
            WHEN p.refund_period_days IS NOT NULL AND
                 EXTRACT(DAY FROM NOW() - pt.created_at) > p.refund_period_days THEN false
            ELSE true
        END as refund_eligible,
        rr.status as refund_request_status,
        rr.id as refund_request_id
    FROM public.payment_transactions pt
    JOIN public.products p ON pt.product_id = p.id
    LEFT JOIN public.refund_requests rr ON pt.id = rr.transaction_id AND rr.status IN ('pending', 'approved', 'rejected')
    WHERE pt.user_id = target_user_id
    ORDER BY pt.created_at DESC;
END;
$$;


