--
-- Name: grant_bundle_component_access(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.grant_bundle_component_access(user_id_param uuid, product_id_param uuid, max_retries integer DEFAULT 3) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE previous text := current_setting('sellf.grant_source', true); result jsonb;
BEGIN
  PERFORM set_config('sellf.grant_source', 'bundle', true);
  result := public.grant_bundle_component_access_impl(user_id_param, product_id_param, max_retries);
  PERFORM set_config('sellf.grant_source', coalesce(previous, ''), true);
  IF (result->>'success')::boolean THEN PERFORM public.record_order_access_term(user_id_param, product_id_param, (SELECT auto_grant_duration_days FROM public.products WHERE id = product_id_param)); END IF; RETURN result;
END;
$$;


ALTER FUNCTION public.grant_bundle_component_access(user_id_param uuid, product_id_param uuid, max_retries integer) OWNER TO postgres;

--
-- Name: grant_bundle_component_access_impl(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.grant_bundle_component_access_impl(user_id_param uuid, product_id_param uuid, max_retries integer DEFAULT 3) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '10s'
    AS $$
DECLARE
  effective_duration INTEGER;
  existing_record RECORD;
  new_expires_at TIMESTAMPTZ := NULL;
  final_duration INTEGER := NULL;
  retry_count INTEGER := 0;
  rows_affected INTEGER;
BEGIN
  IF user_id_param IS NULL OR product_id_param IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'User ID and Product ID are required');
  END IF;

  -- Resolve the component's auto-grant duration WITHOUT requiring is_active (unlike
  -- grant_product_access_service_role). A missing component product is a real failure.
  SELECT auto_grant_duration_days INTO effective_duration
  FROM public.products WHERE id = product_id_param;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Component product not found');
  END IF;

  -- Optimistic-locking upsert (mirrors grant_product_access_service_role; never downgrades a
  -- permanent grant, extends active limited grants, re-grants from now on expired ones).
  WHILE retry_count < max_retries LOOP
    SELECT
      access_expires_at,
      version,
      (access_expires_at IS NULL) AS has_permanent_access,
      (access_expires_at IS NOT NULL AND access_expires_at > NOW()) AS has_active_access
    INTO existing_record
    FROM public.user_product_access
    WHERE user_id = user_id_param AND product_id = product_id_param;

    IF FOUND THEN
      IF existing_record.has_permanent_access THEN
        new_expires_at := NULL;
        final_duration := NULL;
      ELSIF existing_record.has_active_access THEN
        IF effective_duration IS NOT NULL THEN
          new_expires_at := existing_record.access_expires_at + (effective_duration || ' days')::INTERVAL;
          final_duration := effective_duration;
        ELSE
          new_expires_at := NULL;
          final_duration := NULL;
        END IF;
      ELSE
        IF effective_duration IS NOT NULL THEN
          new_expires_at := NOW() + (effective_duration || ' days')::INTERVAL;
          final_duration := effective_duration;
        ELSE
          new_expires_at := NULL;
          final_duration := NULL;
        END IF;
      END IF;

      UPDATE public.user_product_access
      SET
        access_granted_at = NOW(),
        access_duration_days = final_duration,
        access_expires_at = CASE WHEN access_expires_at IS NULL THEN NULL ELSE new_expires_at END,
        version = version + 1
      WHERE user_id = user_id_param AND product_id = product_id_param
        AND version = existing_record.version;

      GET DIAGNOSTICS rows_affected = ROW_COUNT;
      IF rows_affected = 1 THEN
        RETURN jsonb_build_object('success', true, 'operation', 'updated_existing');
      END IF;
      retry_count := retry_count + 1;
      IF retry_count < max_retries THEN PERFORM pg_sleep(0.01 * (2 ^ retry_count)); END IF;
      CONTINUE;
    ELSE
      IF effective_duration IS NOT NULL THEN
        new_expires_at := NOW() + (effective_duration || ' days')::INTERVAL;
        final_duration := effective_duration;
      ELSE
        new_expires_at := NULL;
        final_duration := NULL;
      END IF;

      BEGIN
        INSERT INTO public.user_product_access (
          user_id, product_id, access_duration_days, access_expires_at, access_granted_at, version
        ) VALUES (
          user_id_param, product_id_param, final_duration, new_expires_at, NOW(), 1
        );
        RETURN jsonb_build_object('success', true, 'operation', 'created_new');
      EXCEPTION WHEN unique_violation THEN
        retry_count := retry_count + 1;
        IF retry_count < max_retries THEN PERFORM pg_sleep(0.01 * (2 ^ retry_count)); END IF;
        CONTINUE;
      END;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('success', false, 'error', 'Concurrency conflict after retries');
END;
$$;


ALTER FUNCTION public.grant_bundle_component_access_impl(user_id_param uuid, product_id_param uuid, max_retries integer) OWNER TO postgres;

--
-- Name: grant_free_product_access(text, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.grant_free_product_access(product_slug_param text, access_duration_days_param integer DEFAULT NULL::integer, coupon_code_param text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  previous text := current_setting('sellf.grant_source', true);
  saved_request uuid := nullif(current_setting('sellf.free_grant_context', true), '')::uuid;
  result boolean;
BEGIN
  IF (select auth.role()) IS DISTINCT FROM 'service_role'
     AND EXISTS (SELECT 1 FROM public.maintenance_mode m WHERE m.id AND m.enabled)
     AND NOT EXISTS (
       SELECT 1 FROM public.free_grant_contexts c
       JOIN public.products p ON p.id = c.product_id
       JOIN auth.users u ON lower(u.email) = c.email
       WHERE c.id = saved_request AND p.slug = product_slug_param AND u.id = (select auth.uid())
         AND c.claimed_at IS NULL AND c.expires_at > now()) THEN
    RAISE EXCEPTION 'Down for maintenance' USING ERRCODE = '55000';
  END IF;
  PERFORM set_config('sellf.grant_source', 'free', true);
  result := public.grant_free_product_access_impl(product_slug_param, access_duration_days_param, coupon_code_param);
  PERFORM set_config('sellf.grant_source', coalesce(previous, ''), true);
  RETURN result;
END;
$$;


ALTER FUNCTION public.grant_free_product_access(product_slug_param text, access_duration_days_param integer, coupon_code_param text) OWNER TO postgres;

--
-- Name: grant_free_product_access_impl(text, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.grant_free_product_access_impl(product_slug_param text, access_duration_days_param integer DEFAULT NULL::integer, coupon_code_param text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '2s'
    AS $$
DECLARE
    product_record RECORD;
    current_user_id UUID;
    v_access_expires_at TIMESTAMPTZ;
    v_capped_duration INTEGER;
    clean_slug TEXT; clean_coupon TEXT;
    coupon_result JSONB; v_coupon_id UUID;
    v_discount_type TEXT; v_discount_value NUMERIC; v_user_email TEXT;
    eligible BOOLEAN := FALSE;
    v_component_id UUID;
BEGIN
    IF product_slug_param IS NULL OR length(product_slug_param) = 0 OR length(product_slug_param) > 100 THEN
        RETURN FALSE;
    END IF;
    IF access_duration_days_param IS NOT NULL AND (access_duration_days_param < 0 OR access_duration_days_param > 3650) THEN
        RETURN FALSE;
    END IF;
    clean_slug := regexp_replace(product_slug_param, '[^a-zA-Z0-9_-]', '', 'g');
    IF clean_slug IS NULL OR length(clean_slug) = 0 THEN
        RETURN FALSE;
    END IF;
    current_user_id := auth.uid();
    IF current_user_id IS NULL THEN
        RETURN FALSE;
    END IF;
    SELECT email INTO v_user_email FROM auth.users WHERE id = current_user_id;
    SELECT id, price, currency, allow_custom_price, custom_price_min, auto_grant_duration_days, is_active,
           product_type, available_from, available_until, is_bundle
      INTO product_record
      FROM public.products
      WHERE slug = clean_slug;
    IF NOT FOUND OR NOT product_record.is_active THEN
        RETURN FALSE;
    END IF;
    IF NOT public.is_free_grantable_now(product_record.product_type, product_record.available_from, product_record.available_until)
       AND NOT EXISTS (
         SELECT 1 FROM public.user_product_access upa
         WHERE upa.user_id = current_user_id
           AND upa.product_id = product_record.id
           AND (upa.access_expires_at IS NULL OR upa.access_expires_at > NOW())
       ) THEN
        RETURN FALSE;
    END IF;
    IF coupon_code_param IS NOT NULL THEN
        clean_coupon := regexp_replace(upper(coupon_code_param), '[^A-Z0-9_-]', '', 'g');
        IF length(clean_coupon) = 0 THEN
            RETURN FALSE;
        END IF;
        coupon_result := public.verify_coupon(
            code_param := clean_coupon,
            product_id_param := product_record.id,
            customer_email_param := v_user_email,
            currency_param := product_record.currency
        );
        IF (coupon_result ->> 'valid')::BOOLEAN IS DISTINCT FROM TRUE THEN
            RETURN FALSE;
        END IF;
        v_coupon_id := (coupon_result ->> 'id')::UUID;
        v_discount_type := coupon_result ->> 'discount_type';
        v_discount_value := (coupon_result ->> 'discount_value')::NUMERIC;
        IF v_discount_type = 'set_price' AND v_discount_value = 0 THEN
            eligible := TRUE;
        ELSIF v_discount_type = 'percentage' AND v_discount_value >= 100 THEN
            eligible := TRUE;
        ELSIF v_discount_type = 'fixed' AND v_discount_value >= product_record.price THEN
            eligible := TRUE;
        ELSE
            RETURN FALSE;
        END IF;
    ELSIF product_record.price = 0 THEN
        eligible := TRUE;
    ELSIF product_record.allow_custom_price AND product_record.custom_price_min = 0 THEN
        eligible := TRUE;
    END IF;
    IF NOT eligible THEN
        RETURN FALSE;
    END IF;
    PERFORM 1 FROM public.user_product_access upa
    WHERE upa.user_id = current_user_id
      AND upa.product_id = product_record.id
      AND (upa.access_expires_at IS NULL OR upa.access_expires_at > NOW());
    IF FOUND THEN
        RETURN TRUE;
    END IF;
    IF NOT public.check_rate_limit('grant_free_product_access'::TEXT, 20, 3600) THEN
        RETURN FALSE;
    END IF;
    v_capped_duration := access_duration_days_param;
    IF v_capped_duration IS NOT NULL AND product_record.auto_grant_duration_days IS NOT NULL THEN
        v_capped_duration := LEAST(v_capped_duration, product_record.auto_grant_duration_days);
    END IF;
    IF v_capped_duration IS NOT NULL THEN
        v_access_expires_at := NOW() + INTERVAL '1 day' * v_capped_duration;
    ELSIF product_record.auto_grant_duration_days IS NOT NULL THEN
        v_access_expires_at := NOW() + INTERVAL '1 day' * product_record.auto_grant_duration_days;
    ELSE
        v_access_expires_at := NULL;
    END IF;
    INSERT INTO public.user_product_access (user_id, product_id, access_expires_at, access_duration_days)
    VALUES (
        current_user_id,
        product_record.id,
        v_access_expires_at,
        COALESCE(v_capped_duration, product_record.auto_grant_duration_days)
    )
    ON CONFLICT (user_id, product_id)
    DO UPDATE SET
        access_expires_at = EXCLUDED.access_expires_at,
        access_duration_days = EXCLUDED.access_duration_days,
        access_granted_at = NOW();
    IF product_record.is_bundle THEN
        FOR v_component_id IN
            SELECT bi.component_product_id FROM public.bundle_items bi
            WHERE bi.bundle_product_id = product_record.id
            ORDER BY bi.display_order
        LOOP
            PERFORM public.grant_bundle_component_access(current_user_id, v_component_id);
        END LOOP;
    END IF;
    IF coupon_code_param IS NOT NULL AND v_coupon_id IS NOT NULL THEN
        INSERT INTO public.coupon_redemptions (
            coupon_id, customer_email, user_id, discount_amount, transaction_id
        )
        VALUES (
            v_coupon_id,
            v_user_email,
            current_user_id,
            product_record.price,  -- full-discount path: discount equals list price
            NULL
        );
        UPDATE public.coupons
           SET current_usage_count = current_usage_count + 1
         WHERE id = v_coupon_id;
        DELETE FROM public.coupon_reservations
         WHERE coupon_id = v_coupon_id
           AND customer_email = v_user_email;
    END IF;
    RETURN TRUE;
END;
$$;


