--
-- Name: grant_free_with_context(text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.grant_free_with_context(product_slug_param text, coupon_code_param text DEFAULT NULL::text, p_request_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE pid uuid; context_id uuid; result boolean;
BEGIN
 SELECT id INTO pid FROM public.products WHERE slug=product_slug_param;
 SELECT c.request_id INTO context_id FROM public.free_grant_context(pid,p_request_id)c;
 IF p_request_id IS NOT NULL AND context_id IS NULL THEN RETURN false; END IF;
 PERFORM set_config('sellf.free_grant_context',coalesce(context_id::text,''),true);
 SELECT public.grant_free_product_access(product_slug_param,NULL,coupon_code_param) INTO result;
 IF result AND context_id IS NOT NULL THEN
  UPDATE public.free_grant_contexts SET claimed_at=now() WHERE email=(SELECT lower(email) FROM auth.users WHERE id=(select auth.uid())) AND product_id=pid AND claimed_at IS NULL;
 END IF;
 RETURN result;
END $$;


ALTER FUNCTION public.grant_free_with_context(product_slug_param text, coupon_code_param text, p_request_id uuid) OWNER TO postgres;

--
-- Name: grant_product_access_service_role(uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.grant_product_access_service_role(user_id_param uuid, product_id_param uuid, max_retries integer DEFAULT 3, override_duration_days_param integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE previous text := current_setting('sellf.grant_source', true); result jsonb;
BEGIN
  PERFORM set_config('sellf.grant_source', 'purchase', true);
  result := public.grant_product_access_service_role_impl(user_id_param, product_id_param, max_retries, override_duration_days_param);
  PERFORM set_config('sellf.grant_source', coalesce(previous, ''), true);
  IF (result->>'success')::boolean THEN PERFORM public.record_order_access_term(user_id_param, product_id_param, (SELECT CASE WHEN override_duration_days_param IS NULL THEN auto_grant_duration_days ELSE nullif(override_duration_days_param, 0) END FROM public.products WHERE id = product_id_param)); END IF; RETURN result;
END;
$$;


ALTER FUNCTION public.grant_product_access_service_role(user_id_param uuid, product_id_param uuid, max_retries integer, override_duration_days_param integer) OWNER TO postgres;

--
-- Name: grant_product_access_service_role_impl(uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.grant_product_access_service_role_impl(user_id_param uuid, product_id_param uuid, max_retries integer DEFAULT 3, override_duration_days_param integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '10s'
    AS $$
DECLARE
    product_auto_duration INTEGER;
    effective_duration INTEGER;
    existing_record RECORD;
    new_expires_at TIMESTAMPTZ := NULL;
    final_duration INTEGER := NULL;
    retry_count INTEGER := 0;
    rows_affected INTEGER;
BEGIN
    -- Input validation
    IF user_id_param IS NULL OR product_id_param IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'User ID and Product ID are required'
        );
    END IF;

    -- override_duration_days_param encoding (matches order_bumps.access_duration_days):
    --   NULL → fall back to the product's auto_grant_duration_days
    --      0 → force unlimited (NULL effective duration)
    --    N>0 → use N as the duration, ignoring the product's default
    IF override_duration_days_param IS NOT NULL
       AND (override_duration_days_param < 0 OR override_duration_days_param > 3650) THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Invalid override duration'
        );
    END IF;

    -- Get product configuration
    SELECT auto_grant_duration_days
    INTO product_auto_duration
    FROM public.products
    
    WHERE id = product_id_param AND (is_active = true OR EXISTS (
      SELECT 1 FROM public.payment_transactions t JOIN auth.users u ON u.id = user_id_param
      WHERE t.id::text IN (current_setting('sellf.paid_order', true), current_setting('sellf.transfer_order', true))
        AND (t.product_id = product_id_param OR EXISTS (SELECT 1 FROM public.payment_line_items l
          WHERE l.transaction_id = t.id AND l.product_id = product_id_param))
        AND t.status IN ('completed', 'partially_refunded')
        AND (t.amount = 0 OR coalesce(t.refunded_amount, 0) < t.amount)
        AND (t.user_id = user_id_param OR (t.user_id IS NULL AND lower(t.customer_email) = lower(u.email)))
    ));

    -- If product doesn't exist, return error
    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Product not found or inactive'
        );
    END IF;

    -- Resolve the effective duration once; downstream branches use this value.
    IF override_duration_days_param IS NULL THEN
        effective_duration := product_auto_duration;
    ELSIF override_duration_days_param = 0 THEN
        effective_duration := NULL;
    ELSE
        effective_duration := override_duration_days_param;
    END IF;

    -- Retry loop for optimistic locking
    WHILE retry_count < max_retries LOOP
        -- Get current state (including version for optimistic locking)
        SELECT 
            access_expires_at,
            version,
            (access_expires_at IS NULL) as has_permanent_access,
            (access_expires_at IS NOT NULL AND access_expires_at > NOW()) as has_active_access
        INTO existing_record
        FROM public.user_product_access
        WHERE user_id = user_id_param AND product_id = product_id_param;

        -- Calculate new expiration based on business logic
        IF FOUND THEN
            -- User has existing access record
            IF existing_record.has_permanent_access THEN
                -- User has PERMANENT access - NEVER downgrade
                new_expires_at := NULL;
                final_duration := NULL;
            ELSIF existing_record.has_active_access THEN
                -- User has active LIMITED access
                IF effective_duration IS NOT NULL THEN
                    -- Extend existing access
                    new_expires_at := existing_record.access_expires_at + (effective_duration || ' days')::INTERVAL;
                    final_duration := effective_duration;
                ELSE
                    -- Upgrade to permanent
                    new_expires_at := NULL;
                    final_duration := NULL;
                END IF;
            ELSE
                -- User's access expired - standard logic
                IF effective_duration IS NOT NULL THEN
                    new_expires_at := NOW() + (effective_duration || ' days')::INTERVAL;
                    final_duration := effective_duration;
                ELSE
                    new_expires_at := NULL;
                    final_duration := NULL;
                END IF;
            END IF;

            -- Optimistic update with version check
            UPDATE public.user_product_access 
            SET 
                access_granted_at = NOW(),
                access_duration_days = final_duration,
                access_expires_at = CASE
                    -- Never downgrade from permanent to limited
                    WHEN access_expires_at IS NULL THEN NULL
                    -- Otherwise use calculated value
                    ELSE new_expires_at
                END,
                version = version + 1
            WHERE 
                user_id = user_id_param 
                AND product_id = product_id_param 
                AND version = existing_record.version; -- Optimistic locking condition
            
            GET DIAGNOSTICS rows_affected = ROW_COUNT;
            
            IF rows_affected = 1 THEN
                -- Success! Update succeeded
                RETURN jsonb_build_object(
                    'success', true,
                    'operation', 'updated_existing',
                    'had_permanent_access', existing_record.has_permanent_access,
                    'had_active_access', existing_record.has_active_access,
                    'new_expires_at', new_expires_at,
                    'retry_count', retry_count
                );
            ELSE
                -- Optimistic lock failure - someone else modified the record
                retry_count := retry_count + 1;
                
                -- Small delay before retry (exponential backoff)
                IF retry_count < max_retries THEN
                    PERFORM pg_sleep(0.01 * (2 ^ retry_count)); -- 10ms, 20ms, 40ms
                END IF;
                
                CONTINUE; -- Retry the loop
            END IF;
        ELSE
            -- No existing record - create new with version = 1
            IF effective_duration IS NOT NULL THEN
                new_expires_at := NOW() + (effective_duration || ' days')::INTERVAL;
                final_duration := effective_duration;
            ELSE
                new_expires_at := NULL;
                final_duration := NULL;
            END IF;

            -- Insert new record with optimistic locking protection
            BEGIN
                INSERT INTO public.user_product_access (
                    user_id, 
                    product_id, 
                    access_duration_days, 
                    access_expires_at,
                    access_granted_at,
                    version
                )
                VALUES (
                    user_id_param, 
                    product_id_param, 
                    final_duration, 
                    new_expires_at,
                    NOW(),
                    1
                );
                
                -- Success! Insert succeeded
                RETURN jsonb_build_object(
                    'success', true,
                    'operation', 'created_new',
                    'new_expires_at', new_expires_at,
                    'retry_count', retry_count
                );
                
            EXCEPTION 
                WHEN unique_violation THEN
                    -- Someone else created the record concurrently
                    retry_count := retry_count + 1;
                    
                    -- Small delay before retry
                    IF retry_count < max_retries THEN
                        PERFORM pg_sleep(0.01 * (2 ^ retry_count));
                    END IF;
                    
                    CONTINUE; -- Retry the loop
            END;
        END IF;
    END LOOP;
    
    -- All retries exhausted - CRITICAL: Log this business failure
    BEGIN
        PERFORM public.log_admin_action(
            'critical_optimistic_lock_exhausted',
            'user_product_access',
            user_id_param::TEXT || '_' || product_id_param::TEXT,
            jsonb_build_object(
                'severity', 'CRITICAL',
                'error_type', 'optimistic_lock_retry_exhausted',
                'user_id', user_id_param,
                'product_id', product_id_param,
                'retry_count', retry_count,
                'max_retries', max_retries,
                'function_name', 'grant_product_access_service_role',
                'timestamp', extract(epoch from NOW()),
                'business_impact', 'Payment processed but product access not granted due to high concurrency',
                'context', 'optimistic_locking'
            )
        );
    EXCEPTION 
        WHEN OTHERS THEN
            -- If logging fails, continue anyway
            NULL;
    END;
    
    -- All retries exhausted
    RETURN jsonb_build_object(
        'success', false,
        'error', 'Concurrency conflict: Could not complete operation after retries',
        'retry_count', retry_count,
        'max_retries', max_retries,
        'retry_exceeded', true
    );
    
EXCEPTION
    WHEN OTHERS THEN
        -- Log the error for debugging
        BEGIN
            PERFORM public.log_admin_action(
                'grant_access_error',
                'user_product_access',
                user_id_param::TEXT || '_' || product_id_param::TEXT,
                jsonb_build_object(
                    'severity', 'ERROR',
                    'error_type', 'database_exception',
                    'error_code', SQLSTATE,
                    'error_message', SQLERRM,
                    'user_id', user_id_param,
                    'product_id', product_id_param,
                    'retry_count', retry_count,
                    'function_name', 'grant_product_access_service_role',
                    'timestamp', extract(epoch from NOW()),
                    'context', 'optimistic_locking'
                )
            );
        EXCEPTION 
            WHEN OTHERS THEN
                -- If logging fails, continue
                NULL;
        END;
        
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Database error occurred',
            'error_code', SQLSTATE,
            'retry_count', retry_count
        );
END;
$$;


ALTER FUNCTION public.grant_product_access_service_role_impl(user_id_param uuid, product_id_param uuid, max_retries integer, override_duration_days_param integer) OWNER TO postgres;

