--
-- Name: grant_product_and_bundle_components(uuid, uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.grant_product_and_bundle_components(user_id_param uuid, product_id_param uuid, override_duration_days_param integer DEFAULT NULL::integer, transaction_id_param uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  previous_paid_order text := current_setting('sellf.paid_order', true);
  is_bundle_var boolean;
  order_scoped boolean;
  comp_rec record;
  comp_result jsonb;
  granted integer := 0;
BEGIN
  PERFORM set_config('sellf.paid_order', coalesce(transaction_id_param::text, ''), true);
  PERFORM public.grant_product_access_service_role(
    user_id_param, product_id_param, override_duration_days_param => override_duration_days_param
  );
  granted := granted + 1;

  SELECT is_bundle INTO is_bundle_var FROM public.products WHERE id = product_id_param;
  IF is_bundle_var IS TRUE THEN
    order_scoped := transaction_id_param IS NOT NULL AND EXISTS (
      SELECT 1 FROM public.payment_transactions WHERE id = transaction_id_param AND product_id = product_id_param);
    IF order_scoped THEN PERFORM public.snapshot_order_bundle_components(transaction_id_param); END IF;
    FOR comp_rec IN
      SELECT c.component_product_id FROM (
        SELECT g AS component_product_id FROM public.order_granted_components(transaction_id_param) g WHERE order_scoped
        UNION ALL
        SELECT b.component_product_id FROM public.bundle_items b WHERE NOT order_scoped AND b.bundle_product_id = product_id_param
      ) c
      LEFT JOIN public.bundle_items d ON d.bundle_product_id = product_id_param AND d.component_product_id = c.component_product_id
      ORDER BY d.display_order NULLS LAST
    LOOP
      BEGIN
        -- Grants the component regardless of is_active (an inactive component is a SUCCESS).
        comp_result := public.grant_bundle_component_access(user_id_param, comp_rec.component_product_id);
        IF COALESCE((comp_result->>'success')::boolean, false) THEN
          granted := granted + 1;
        ELSE
          BEGIN
            PERFORM public.log_admin_action(
              'bundle_component_grant_failure', 'bundle_items', product_id_param::text,
              jsonb_build_object('severity', 'ERROR', 'user_id', user_id_param,
                'component_product_id', comp_rec.component_product_id,
                'error', comp_result->>'error',
                'function_name', 'grant_product_and_bundle_components')
            );
          EXCEPTION WHEN OTHERS THEN NULL;
          END;
        END IF;
      EXCEPTION WHEN OTHERS THEN
        -- One bad component must not block the rest of the bundle; logging can never escape this loop.
        BEGIN
          PERFORM public.log_admin_action(
            'bundle_component_grant_failure', 'bundle_items', product_id_param::text,
            jsonb_build_object('severity', 'ERROR', 'user_id', user_id_param,
              'component_product_id', comp_rec.component_product_id,
              'error_code', SQLSTATE, 'error_message', SQLERRM,
              'function_name', 'grant_product_and_bundle_components')
          );
        EXCEPTION WHEN OTHERS THEN NULL;
        END;
      END;
    END LOOP;
  END IF;

  PERFORM set_config('sellf.paid_order', coalesce(previous_paid_order, ''), true);
  RETURN jsonb_build_object('success', true, 'granted', granted);
END $$;


ALTER FUNCTION public.grant_product_and_bundle_components(user_id_param uuid, product_id_param uuid, override_duration_days_param integer, transaction_id_param uuid) OWNER TO postgres;

--
-- Name: handle_new_user_registration(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handle_new_user_registration() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('handle_new_user_registration'));

  INSERT INTO public.profiles (id, full_name, avatar_url)
  VALUES (NEW.id, NEW.raw_user_meta_data->>'full_name', NEW.raw_user_meta_data->>'avatar_url')
  ON CONFLICT (id) DO NOTHING;

  INSERT INTO public.admin_users (user_id)
  SELECT NEW.id WHERE NOT EXISTS (SELECT 1 FROM auth.users WHERE id <> NEW.id)
  ON CONFLICT (user_id) DO NOTHING;

  IF NEW.email_confirmed_at IS NOT NULL THEN
    PERFORM public.migrate_guest_payment_data_to_profile(NEW.id);
    PERFORM public.claim_guest_purchases_for_user(NEW.id);
  END IF;

  PERFORM public.log_audit_entry('auth.users', 'INSERT', NULL, jsonb_build_object('email', NEW.email), NEW.id);
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.handle_new_user_registration() OWNER TO postgres;

--
-- Name: handle_user_email_confirmation(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handle_user_email_confirmation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('handle_new_user_registration'));
  PERFORM public.migrate_guest_payment_data_to_profile(NEW.id);
  PERFORM public.claim_guest_purchases_for_user(NEW.id);
  INSERT INTO public.user_product_access(user_id, product_id, subscription_id, access_granted_at)
  SELECT DISTINCT ON (s.product_id) NEW.id, s.product_id, s.id, now()
  FROM public.subscriptions s
  WHERE s.user_id = NEW.id AND s.status IN ('active', 'trialing')
  ORDER BY s.product_id, s.created_at DESC, s.id DESC
  ON CONFLICT (user_id, product_id) DO UPDATE
    SET subscription_id = EXCLUDED.subscription_id,
        access_granted_at = EXCLUDED.access_granted_at;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.handle_user_email_confirmation() OWNER TO postgres;

--
-- Name: hold_transfer_for_invoice(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.hold_transfer_for_invoice(p_id uuid, p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE changed integer;
BEGIN
  IF p_now IS NULL THEN RAISE EXCEPTION 'Time required' USING ERRCODE='22023'; END IF;
  UPDATE public.payment_transactions SET invoice_hold_at=p_now,release_at=NULL,reminder_at=NULL,updated_at=now()
    WHERE id=p_id AND payment_provider='bank_transfer' AND status='awaiting_payment' AND invoice_hold_at IS NULL;
  GET DIAGNOSTICS changed=ROW_COUNT;
  RETURN jsonb_build_object('success',EXISTS(SELECT 1 FROM public.payment_transactions WHERE id=p_id AND payment_provider='bank_transfer'
    AND status='awaiting_payment'),'held',changed=1);
END $$;


ALTER FUNCTION public.hold_transfer_for_invoice(p_id uuid, p_now timestamp with time zone) OWNER TO postgres;

