--
-- Name: increment_sale_quantity_sold(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.increment_sale_quantity_sold(p_product_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_rows_updated INTEGER;
BEGIN
  -- SECURITY: Atomic check-and-update in single statement to prevent race conditions
  -- This ensures sale validity is checked at the exact moment of update, not before
  UPDATE public.products
  SET sale_quantity_sold = COALESCE(sale_quantity_sold, 0) + 1
  WHERE id = p_product_id
    AND sale_price IS NOT NULL
    AND sale_price > 0
    AND (sale_price_until IS NULL OR sale_price_until > NOW())
    AND (sale_quantity_limit IS NULL OR COALESCE(sale_quantity_sold, 0) < sale_quantity_limit);

  GET DIAGNOSTICS v_rows_updated = ROW_COUNT;
  RETURN v_rows_updated > 0;
END;
$$;


ALTER FUNCTION public.increment_sale_quantity_sold(p_product_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION increment_sale_quantity_sold(p_product_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.increment_sale_quantity_sold(p_product_id uuid) IS '@graphql({"include": false})';


--
-- Name: increment_sale_quantity_sold(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.increment_sale_quantity_sold(p_product_id uuid, p_quantity integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF p_quantity IS NULL OR p_quantity NOT BETWEEN 1 AND 100 THEN
    RAISE EXCEPTION 'Invalid sale quantity';
  END IF;
  UPDATE public.products SET sale_quantity_sold = coalesce(sale_quantity_sold, 0) + p_quantity
  WHERE id = p_product_id AND sale_price > 0;
  RETURN FOUND;
END;
$$;


ALTER FUNCTION public.increment_sale_quantity_sold(p_product_id uuid, p_quantity integer) OWNER TO postgres;

