-- Name: increment_webhook_attempt(uuid, text, integer, text, text, integer, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.increment_webhook_attempt(p_log_id uuid, p_status text, p_http_status integer, p_response_body text, p_error_message text, p_duration_ms integer, p_next_retry_at timestamp with time zone, p_failed_permanently_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  UPDATE public.webhook_logs
  SET
    status = p_status,
    http_status = p_http_status,
    response_body = p_response_body,
    error_message = p_error_message,
    duration_ms = p_duration_ms,
    attempt_count = attempt_count + 1,
    next_retry_at = p_next_retry_at,
    failed_permanently_at = p_failed_permanently_at
  WHERE id = p_log_id;
END;
$$;


