--
-- Name: is_admin(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.is_admin(user_id_param uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    current_user_id UUID;
    target_user_id UUID;
BEGIN
    -- Service role is always trusted (used by admin clients after TS auth checks)
    IF (SELECT auth.role()) = 'service_role' THEN
        RETURN TRUE;
    END IF;

    current_user_id := (SELECT auth.uid());

    IF current_user_id IS NULL THEN
        RETURN FALSE;
    END IF;

    target_user_id := COALESCE(user_id_param, current_user_id);

    -- Security: Only allow users to check their own admin status
    IF user_id_param IS NOT NULL AND user_id_param != current_user_id THEN
        RETURN FALSE;
    END IF;

    RETURN EXISTS (
        SELECT 1 FROM public.admin_users
        WHERE user_id = target_user_id
    );
END;
$$;


ALTER FUNCTION public.is_admin(user_id_param uuid) OWNER TO postgres;

--
-- Name: is_admin_cached(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.is_admin_cached() RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    current_user_id UUID;
    user_is_admin BOOLEAN;
    cache_key TEXT;
BEGIN
    -- Get current authenticated user
    current_user_id := (SELECT auth.uid());
    IF current_user_id IS NULL THEN
        RETURN FALSE;
    END IF;
    
    -- Create session-specific cache key
    cache_key := 'app.user_is_admin_' || replace(current_user_id::TEXT, '-', '_');
    
    -- Try to get from session cache first
    BEGIN
        user_is_admin := current_setting(cache_key, true)::boolean;
        IF user_is_admin IS NOT NULL THEN
            RETURN user_is_admin;
        END IF;
    EXCEPTION 
        WHEN OTHERS THEN
            -- Cache miss, continue to DB lookup
            NULL;
    END;
    
    -- Check admin status from database
    SELECT EXISTS(
        SELECT 1 FROM public.admin_users 
        WHERE user_id = current_user_id
    ) INTO user_is_admin;
    
    -- Set session cache (expires with session)
    PERFORM set_config(cache_key, user_is_admin::TEXT, false);
    
    RETURN user_is_admin;
END;
$$;


ALTER FUNCTION public.is_admin_cached() OWNER TO postgres;

--
-- Name: is_free_claimable_product(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.is_free_claimable_product(p_product_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.products p
    WHERE p.id = p_product_id
      AND p.is_active
      AND (p.price = 0 OR (p.allow_custom_price AND p.custom_price_min = 0))
      AND public.is_free_grantable_now(p.product_type, p.available_from, p.available_until)
  );
$$;


ALTER FUNCTION public.is_free_claimable_product(p_product_id uuid) OWNER TO postgres;

--
-- Name: is_free_grantable_now(text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.is_free_grantable_now(p_product_type text, p_available_from timestamp with time zone, p_available_until timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT p_product_type = 'one_time'
     AND (p_available_from IS NULL OR p_available_from <= NOW())
     AND (p_available_until IS NULL OR p_available_until >= NOW());
$$;


ALTER FUNCTION public.is_free_grantable_now(p_product_type text, p_available_from timestamp with time zone, p_available_until timestamp with time zone) OWNER TO postgres;

--
-- Name: is_sale_price_active(numeric, timestamp with time zone, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.is_sale_price_active(p_sale_price numeric, p_sale_price_until timestamp with time zone, p_sale_quantity_limit integer, p_sale_quantity_sold integer) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
BEGIN
  -- No sale price set
  IF p_sale_price IS NULL OR p_sale_price <= 0 THEN
    RETURN FALSE;
  END IF;

  -- Check time limit (if set)
  IF p_sale_price_until IS NOT NULL AND p_sale_price_until <= NOW() THEN
    RETURN FALSE;
  END IF;

  -- Check quantity limit (if set)
  IF p_sale_quantity_limit IS NOT NULL AND COALESCE(p_sale_quantity_sold, 0) >= p_sale_quantity_limit THEN
    RETURN FALSE;
  END IF;

  RETURN TRUE;
END;
$$;


ALTER FUNCTION public.is_sale_price_active(p_sale_price numeric, p_sale_price_until timestamp with time zone, p_sale_quantity_limit integer, p_sale_quantity_sold integer) OWNER TO postgres;

--
-- Name: FUNCTION is_sale_price_active(p_sale_price numeric, p_sale_price_until timestamp with time zone, p_sale_quantity_limit integer, p_sale_quantity_sold integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.is_sale_price_active(p_sale_price numeric, p_sale_price_until timestamp with time zone, p_sale_quantity_limit integer, p_sale_quantity_sold integer) IS '@graphql({"include": false})';


--
-- Name: issue_license_with_audit(jsonb, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.issue_license_with_audit(p_license jsonb, p_performed_by uuid, p_audit_values jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE r public.issued_licenses; v public.issued_licenses;
BEGIN
  IF (SELECT auth.role()) IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Service role required' USING ERRCODE='42501'; END IF;
  IF p_performed_by IS NULL OR jsonb_typeof(p_license) IS DISTINCT FROM 'object'
     OR (p_audit_values IS NOT NULL AND jsonb_typeof(p_audit_values) <> 'object') THEN
    RAISE EXCEPTION 'Invalid license issuance' USING ERRCODE='22023';
  END IF;
  r := jsonb_populate_record(NULL::public.issued_licenses, p_license);
  INSERT INTO public.issued_licenses(id, seller_id, original_seller_id, product_id, email, user_id, order_id, access_grant_id,
      customer_locale, kid, license_key, expires_at, issuance_source, license_domain)
    VALUES(coalesce(r.id, gen_random_uuid()), r.seller_id, r.original_seller_id, r.product_id, r.email, r.user_id, r.order_id,
      r.access_grant_id, r.customer_locale, r.kid, r.license_key, r.expires_at, coalesce(r.issuance_source, 'purchase'), r.license_domain)
    RETURNING * INTO v;
  INSERT INTO public.audit_log(table_name, operation, performed_by, new_values)
    VALUES('issued_licenses', 'INSERT', p_performed_by, coalesce(p_audit_values, '{}'::jsonb)
      || CASE WHEN v.access_grant_id IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('access_grant_id', v.access_grant_id) END
      || jsonb_build_object('license_id', v.id, 'product_id', v.product_id, 'email', v.email, 'domain', v.license_domain, 'kid', v.kid));
  RETURN v.id;
END $$;


ALTER FUNCTION public.issue_license_with_audit(p_license jsonb, p_performed_by uuid, p_audit_values jsonb) OWNER TO postgres;

--
-- Name: jsonschema_subset_matches(json, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.jsonschema_subset_matches(schema json, instance jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
BEGIN
  -- Bound serialized input before walking; shared node budget includes failed
  -- anyOf branches, preventing exponential branch amplification.
  IF pg_catalog.octet_length(schema::text) > 131072 OR pg_catalog.octet_length(instance::text) > 102400 THEN RETURN false; END IF;
  RETURN (SELECT valid FROM public.jsonschema_subset_walk(schema::jsonb,instance,0,16384));
END;
$$;


ALTER FUNCTION public.jsonschema_subset_matches(schema json, instance jsonb) OWNER TO postgres;

--
-- Name: jsonschema_subset_pattern(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.jsonschema_subset_pattern(pattern text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $_$
  SELECT CASE pattern
    WHEN '^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$' THEN '^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$'
    WHEN '^[^<>]*$' THEN '^[^<>]*$'
    WHEN '^https:\/\/(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}(?::443)?(?:\/[a-zA-Z0-9/_-]*)?$' THEN '^https://(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}(?::443)?(?:/[a-zA-Z0-9/_-]*)?$'
    WHEN '^[a-z][a-z0-9-]{0,63}$' THEN '^[a-z][a-z0-9-]{0,63}$'
    WHEN '^#[0-9A-Fa-f]{6}$' THEN '^#[0-9A-Fa-f]{6}$'
    WHEN '^(?![\s\S]*<[^>]*>)[\s\S]*$' THEN '^(?!.*<[^>]*>).*$'
    WHEN '^(?![\s\S]*(?:[<>]|(?:https?|ftp|javascript|data|mailto):|:\/\/|[wW][wW][wW]\.|[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}|[$\u20AC\u00A3]\s*\d|\d\s*(?:USD|EUR|PLN|GBP|z\u0142)|[\u0000\uFEFF\uFFFD]))[\s\S]*$' THEN '^(?!.*(?:[<>]|(?:https?|ftp|javascript|data|mailto):|://|[wW][wW][wW]\.|[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}|[$€£][\u0009-\u000d\u0020\u00a0\u2003\u2029\ufeff]*[0-9]|[0-9][\u0009-\u000d\u0020\u00a0\u2003\u2029\ufeff]*(?:USD|EUR|PLN|GBP|zł)|[﻿�])).*$'
    ELSE NULL END;
$_$;


ALTER FUNCTION public.jsonschema_subset_pattern(pattern text) OWNER TO postgres;

--
-- Name: jsonschema_subset_walk(jsonb, jsonb, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.jsonschema_subset_walk(schema jsonb, instance jsonb, depth integer, budget integer) RETURNS TABLE(valid boolean, remaining integer)
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
DECLARE
  keyword text; child jsonb; property record; result record;
  kind text := pg_catalog.jsonb_typeof(instance); matched boolean; expression text;
BEGIN
  valid := false; remaining := budget - 1;
  <<validate>> BEGIN
    IF depth > 32 OR remaining < 0 OR pg_catalog.jsonb_typeof(schema) <> 'object' THEN EXIT validate; END IF;
    FOR keyword IN SELECT pg_catalog.jsonb_object_keys(schema) LOOP
      IF keyword NOT IN ('type','properties','required','additionalProperties','items','anyOf','enum','const',
        'maxLength','minItems','maxItems','uniqueItems','pattern','format','default') THEN EXIT validate; END IF;
    END LOOP;
    IF schema ? 'type' THEN
      IF schema->>'type' = 'integer' THEN
        IF kind <> 'number' OR (instance::text)::numeric <> pg_catalog.trunc((instance::text)::numeric) THEN EXIT validate; END IF;
      ELSIF schema->>'type' NOT IN ('object','array','string','number','boolean','null') OR kind <> schema->>'type' THEN EXIT validate;
      END IF;
    END IF;
    IF schema ? 'const' AND instance <> schema->'const' THEN EXIT validate; END IF;
    IF schema ? 'enum' AND NOT EXISTS (SELECT 1 FROM pg_catalog.jsonb_array_elements(schema->'enum') item WHERE item=instance) THEN EXIT validate; END IF;
    IF schema ? 'anyOf' THEN
      matched := false;
      FOR child IN SELECT value FROM pg_catalog.jsonb_array_elements(schema->'anyOf') LOOP
        SELECT * INTO result FROM public.jsonschema_subset_walk(child,instance,depth+1,remaining);
        remaining := result.remaining;
        IF remaining < 0 THEN EXIT validate; END IF;
        IF result.valid THEN matched := true; EXIT; END IF;
      END LOOP;
      IF NOT matched THEN EXIT validate; END IF;
    END IF;
    IF kind = 'object' THEN
      IF schema ? 'required' AND EXISTS (SELECT 1 FROM pg_catalog.jsonb_array_elements_text(schema->'required') required WHERE NOT instance ? required) THEN EXIT validate; END IF;
      FOR property IN SELECT * FROM pg_catalog.jsonb_each(instance) LOOP
        child := schema->'properties'->property.key;
        IF child IS NULL THEN
          IF schema->'additionalProperties' = 'false'::jsonb THEN EXIT validate; END IF;
          IF pg_catalog.jsonb_typeof(schema->'additionalProperties') = 'object' THEN child := schema->'additionalProperties'; END IF;
        END IF;
        IF child IS NOT NULL THEN
          SELECT * INTO result FROM public.jsonschema_subset_walk(child,property.value,depth+1,remaining);
          remaining := result.remaining;
          IF NOT result.valid THEN EXIT validate; END IF;
        END IF;
      END LOOP;
    ELSIF kind = 'array' THEN
      IF schema ? 'minItems' AND pg_catalog.jsonb_array_length(instance) < (schema->>'minItems')::numeric THEN EXIT validate; END IF;
      IF schema ? 'maxItems' AND pg_catalog.jsonb_array_length(instance) > (schema->>'maxItems')::numeric THEN EXIT validate; END IF;
      IF schema->'uniqueItems' = 'true'::jsonb AND
        (SELECT count(*) <> count(DISTINCT value) FROM pg_catalog.jsonb_array_elements(instance)) THEN EXIT validate; END IF;
      IF schema ? 'items' THEN
        FOR child IN SELECT value FROM pg_catalog.jsonb_array_elements(instance) LOOP
          SELECT * INTO result FROM public.jsonschema_subset_walk(schema->'items',child,depth+1,remaining);
          remaining := result.remaining;
          IF NOT result.valid THEN EXIT validate; END IF;
        END LOOP;
      END IF;
    ELSIF kind = 'string' THEN
      IF schema ? 'maxLength' AND pg_catalog.char_length(instance #>> '{}') > (schema->>'maxLength')::numeric THEN EXIT validate; END IF;
      IF schema ? 'pattern' THEN
        expression := public.jsonschema_subset_pattern(schema->>'pattern');
        -- C collation avoids locale expansion of ASCII ranges. Default PG regex
        -- mode is newline-insensitive: '.' also matches line terminators.
        IF expression IS NULL OR NOT ((instance #>> '{}') COLLATE pg_catalog."C" ~ expression) THEN EXIT validate; END IF;
      END IF;
      -- pg_jsonschema 0.3.3 treats format as annotation (including uuid).
      -- Only this emitted format is admitted by the generator.
      IF schema ? 'format' AND schema->>'format' <> 'uuid' THEN EXIT validate; END IF;
    END IF;
    -- 'default' is an annotation; missing properties are never filled in.
    valid := true;
  END validate;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION public.jsonschema_subset_walk(schema jsonb, instance jsonb, depth integer, budget integer) OWNER TO postgres;

--
-- Name: keep_bundle_component_available(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.keep_bundle_component_available() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF OLD.archived_at IS NULL AND NEW.archived_at IS NOT NULL
    AND EXISTS (SELECT 1 FROM public.bundle_items WHERE component_product_id = NEW.id) THEN
    RAISE EXCEPTION 'Product belongs to bundles' USING ERRCODE = '2BP01';
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.keep_bundle_component_available() OWNER TO postgres;

--
-- Name: keep_ended_subscription_ended(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.keep_ended_subscription_ended() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF OLD.status IN ('canceled', 'incomplete_expired') AND NEW.status IS DISTINCT FROM OLD.status THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.keep_ended_subscription_ended() OWNER TO postgres;

--
-- Name: keep_refunded_subscription_access_ended(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.keep_refunded_subscription_access_ended() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.subscription_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.payment_transactions t
    WHERE t.subscription_id=NEW.subscription_id AND t.status='refunded') THEN
    RETURN NULL;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.keep_refunded_subscription_access_ended() OWNER TO postgres;

--
-- Name: keep_refunded_subscription_ended(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.keep_refunded_subscription_ended() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF EXISTS(SELECT 1 FROM public.payment_transactions t WHERE t.subscription_id=NEW.id AND t.status='refunded') THEN
    NEW.status:='canceled'; NEW.cancel_at_period_end:=false;
    NEW.canceled_at:=coalesce(NEW.canceled_at,now()); NEW.current_period_end:=NULL;
    NEW.paid_access_expires_at:=NULL; NEW.paid_access_invoice_id:=NULL;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.keep_refunded_subscription_ended() OWNER TO postgres;

--
-- Name: legacy_pending_free_grant_products(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.legacy_pending_free_grant_products() RETURNS TABLE(product_id uuid, slug text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
#variable_conflict use_column
DECLARE
  v_user_id UUID := auth.uid();
  v_keep JSONB;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN;
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(p.id::TEXT)), '[]'::jsonb)
  INTO v_keep
  FROM auth.users u
  CROSS JOIN LATERAL jsonb_array_elements_text(
    COALESCE(u.raw_app_meta_data -> 'pending_free_grants', '[]'::jsonb)
  ) AS pending(id)
  JOIN public.products p ON p.id::TEXT = pending.id
  WHERE u.id = v_user_id
    AND public.is_free_claimable_product(p.id)
    AND NOT EXISTS (
      SELECT 1 FROM public.user_product_access upa
      WHERE upa.user_id = v_user_id
        AND upa.product_id = p.id
        AND (upa.access_expires_at IS NULL OR upa.access_expires_at > now())
    );

  UPDATE auth.users u
  SET raw_app_meta_data = jsonb_set(u.raw_app_meta_data, '{pending_free_grants}', v_keep)
  WHERE u.id = v_user_id
    AND u.raw_app_meta_data ? 'pending_free_grants'
    AND u.raw_app_meta_data -> 'pending_free_grants' IS DISTINCT FROM v_keep;

  RETURN QUERY
  SELECT p.id, p.slug
  FROM public.products p
  WHERE p.id::TEXT IN (SELECT jsonb_array_elements_text(v_keep));
END;
$$;


ALTER FUNCTION public.legacy_pending_free_grant_products() OWNER TO postgres;

--
-- Name: issued_licenses; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.issued_licenses (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    seller_id uuid,
    product_id uuid,
    email text,
    user_id uuid,
    order_id text NOT NULL,
    kid text NOT NULL,
    license_key text NOT NULL,
    issued_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone,
    revoked_at timestamp with time zone,
    issuance_source text DEFAULT 'purchase'::text NOT NULL,
    license_domain text,
    original_seller_id uuid NOT NULL,
    revoked_by_dispute_id text,
    expiry_notified_at timestamp with time zone,
    revocation_reason text,
    customer_locale text,
    access_grant_id uuid,
    product_name text,
    CONSTRAINT issued_license_dispute_requires_revocation CHECK (((revoked_by_dispute_id IS NULL) OR (revoked_at IS NOT NULL))),
    CONSTRAINT issued_licenses_customer_locale_check CHECK ((customer_locale = ANY (ARRAY['pl'::text, 'en'::text]))),
    CONSTRAINT issued_licenses_issuance_source_check CHECK ((issuance_source = ANY (ARRAY['purchase'::text, 'manual'::text, 'api'::text]))),
    CONSTRAINT issued_licenses_revocation_reason_check CHECK ((revocation_reason = ANY (ARRAY['refund'::text, 'dispute'::text, 'manual'::text, 'subscription_cancelled'::text, 'expired'::text])))
);


ALTER TABLE public.issued_licenses OWNER TO postgres;

--
-- Name: license_event_snapshot(public.issued_licenses); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.license_event_snapshot(p_license public.issued_licenses) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE claims jsonb; encoded text; tier text; product jsonb; tx record;
BEGIN
  BEGIN
    encoded:=translate(split_part(p_license.license_key,'.',1),'-_','+/');
    encoded:=encoded||repeat('=',(4-length(encoded)%4)%4);
    claims:=convert_from(decode(encoded,'base64'),'UTF8')::jsonb;
    tier:=CASE WHEN jsonb_typeof(claims->'tier')='string' THEN claims->>'tier' ELSE NULL END;
  EXCEPTION WHEN OTHERS THEN tier:=NULL;
  END;
  SELECT jsonb_build_object('name',p.name,'slug',p.slug,'license_tier',tier) INTO product
    FROM public.products p WHERE p.id=p_license.product_id;
  -- order_id is the payment intent, checkout session, renewal invoice or offline order id.
  SELECT t.id,t.order_number INTO tx FROM public.payment_transactions t
    WHERE t.stripe_payment_intent_id=p_license.order_id OR t.session_id=p_license.order_id
      OR t.stripe_invoice_id=p_license.order_id OR t.id::text=p_license.order_id
    ORDER BY (t.product_id=p_license.product_id) DESC,t.created_at LIMIT 1;
  RETURN jsonb_build_object('id',p_license.id,'product_id',p_license.product_id,'email',p_license.email,'user_id',p_license.user_id,
    'order_id',p_license.order_id,'seller_id',p_license.seller_id,'original_seller_id',p_license.original_seller_id,
    'tier',tier,'license_domain',p_license.license_domain,'issuance_source',p_license.issuance_source,
    'issued_at',p_license.issued_at,'expires_at',p_license.expires_at,'revoked_at',p_license.revoked_at,'products',product,
    'customer_locale',p_license.customer_locale,'sellf_order_id',tx.id,'order_number',tx.order_number,
    'revocation_reason',CASE WHEN p_license.revoked_at IS NULL THEN NULL
      WHEN p_license.revoked_by_dispute_id IS NOT NULL THEN 'dispute'
      ELSE p_license.revocation_reason END);
END $$;


ALTER FUNCTION public.license_event_snapshot(p_license public.issued_licenses) OWNER TO postgres;

--
-- Name: license_mail_is_current(text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.license_mail_is_current(p_email text, p_keys jsonb) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
SELECT jsonb_typeof(p_keys)='array' AND jsonb_array_length(p_keys)>0
AND NOT EXISTS (
  SELECT 1 FROM jsonb_array_elements_text(p_keys) k(token)
  WHERE NOT EXISTS (
    SELECT 1 FROM public.issued_licenses l
    WHERE l.license_key=k.token AND lower(l.email)=lower(p_email)
      AND l.revoked_at IS NULL AND (l.expires_at IS NULL OR l.expires_at>now())
      AND (l.issuance_source IN ('manual','api') OR
        EXISTS (SELECT 1 FROM public.payment_transactions t
          JOIN public.subscriptions s ON s.id=t.subscription_id
          JOIN auth.users u ON u.id=s.user_id AND u.email_confirmed_at IS NULL
          WHERE lower(u.email)=lower(p_email) AND s.product_id=l.product_id
            AND t.status IN ('completed','partially_refunded') AND l.order_id=t.stripe_invoice_id
            AND ((s.status IN ('active','trialing','past_due') AND s.current_period_end>now())
              OR (s.status='canceled' AND s.paid_access_invoice_id=t.stripe_invoice_id
                AND s.paid_access_expires_at>now() AND coalesce(t.refunded_amount,0)=0))) OR
        EXISTS (SELECT 1 FROM public.user_product_access a JOIN auth.users u ON u.id=a.user_id
          WHERE lower(u.email)=lower(p_email) AND a.product_id=l.product_id
            AND (a.access_expires_at IS NULL OR a.access_expires_at>now())) OR
        EXISTS (SELECT 1 FROM public.guest_purchases g
          JOIN public.payment_transactions t ON t.id=g.transaction_id OR (g.transaction_id IS NULL AND t.session_id=g.session_id)
          WHERE lower(g.customer_email)=lower(p_email) AND g.product_id=l.product_id
            AND g.claimed_by_user_id IS NULL AND t.status IN ('completed','partially_refunded')
            AND l.order_id IN (t.id::text,t.session_id,t.stripe_payment_intent_id,t.stripe_invoice_id)))
  )
);
$$;


ALTER FUNCTION public.license_mail_is_current(p_email text, p_keys jsonb) OWNER TO postgres;

--
-- Name: payment_transactions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.payment_transactions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    session_id text,
    user_id uuid,
    product_id uuid,
    customer_email text NOT NULL,
    amount numeric NOT NULL,
    currency text NOT NULL,
    stripe_payment_intent_id text,
    status text DEFAULT 'completed'::text NOT NULL,
    refunded_amount numeric DEFAULT 0,
    refunded_at timestamp with time zone,
    refunded_by uuid,
    refund_id text,
    refund_reason text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    abandoned_at timestamp with time zone,
    expires_at timestamp with time zone,
    subscription_id uuid,
    stripe_invoice_id text,
    custom_field_values jsonb DEFAULT '{}'::jsonb NOT NULL,
    net_total integer,
    tax_total integer,
    tax_snapshot_status text DEFAULT 'none'::text NOT NULL,
    fulfillment_pending boolean DEFAULT false NOT NULL,
    order_details jsonb,
    payment_provider text DEFAULT 'stripe'::text NOT NULL,
    order_number bigint NOT NULL,
    pricing_snapshot_version integer,
    coupon_id uuid,
    livemode boolean DEFAULT false NOT NULL,
    payment_due_at timestamp with time zone,
    paid_at timestamp with time zone,
    transfer_details jsonb,
    order_placed_notified_at timestamp with time zone,
    order_cancelled_notified_at timestamp with time zone,
    order_overdue_notified_at timestamp with time zone,
    transfer_mail_sent_at timestamp with time zone,
    refund_status text,
    reminder_at timestamp with time zone,
    release_at timestamp with time zone,
    cancel_reason text,
    transfer_declared_at timestamp with time zone,
    transfer_declared_note text,
    invoice_hold_at timestamp with time zone,
    reopened_at timestamp with time zone,
    order_reminder_notified_at timestamp with time zone,
    order_transfer_declared_notified_at timestamp with time zone,
    order_invoice_issued_notified_at timestamp with time zone,
    order_reopened_notified_at timestamp with time zone,
    reminder_mail_sent_at timestamp with time zone,
    cancelled_mail_sent_at timestamp with time zone,
    settled_via text,
    participants_mail_sent_at timestamp with time zone,
    participants_completed_at timestamp with time zone,
    participants_reminder2_sent_at timestamp with time zone,
    transfer_paid_mail_sent_at timestamp with time zone,
    cancel_note text,
    product_name text,
    bundle_components_recorded_at timestamp with time zone,
    access_terms jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT payment_transactions_access_terms_check CHECK ((jsonb_typeof(access_terms) = 'object'::text)),
    CONSTRAINT payment_transactions_amount_check CHECK (((amount <= (99999999)::numeric) AND ((amount > (0)::numeric) OR ((amount = (0)::numeric) AND (subscription_id IS NOT NULL) AND (stripe_invoice_id IS NOT NULL))))),
    CONSTRAINT payment_transactions_cancel_note_check CHECK (((cancel_note IS NULL) OR (length(cancel_note) <= 1000))),
    CONSTRAINT payment_transactions_cancel_reason_check CHECK ((cancel_reason = ANY (ARRAY['admin'::text, 'payment_window_expired'::text]))),
    CONSTRAINT payment_transactions_currency_check CHECK (((length(currency) = 3) AND (upper(currency) ~ '^[A-Z]{3}$'::text) AND (upper(currency) = ANY (ARRAY['USD'::text, 'EUR'::text, 'GBP'::text, 'CAD'::text, 'AUD'::text, 'JPY'::text, 'CHF'::text, 'CNY'::text, 'SEK'::text, 'NOK'::text, 'DKK'::text, 'PLN'::text, 'CZK'::text, 'HUF'::text, 'RON'::text, 'BGN'::text, 'HRK'::text, 'RUB'::text, 'TRY'::text, 'BRL'::text, 'MXN'::text, 'INR'::text, 'KRW'::text, 'SGD'::text, 'HKD'::text, 'NZD'::text, 'ZAR'::text, 'ILS'::text, 'THB'::text, 'MYR'::text, 'PHP'::text, 'IDR'::text, 'VND'::text])))),
    CONSTRAINT payment_transactions_customer_email_check CHECK (public.validate_email_format(customer_email)),
    CONSTRAINT payment_transactions_order_details_check CHECK (((order_details IS NULL) OR ((jsonb_typeof(order_details) = 'object'::text) AND (octet_length((order_details)::text) <= 65536)))),
    CONSTRAINT payment_transactions_payment_provider_check CHECK ((payment_provider = ANY (ARRAY['stripe'::text, 'bank_transfer'::text]))),
    CONSTRAINT payment_transactions_pricing_snapshot_version_check CHECK ((pricing_snapshot_version = 1)),
    CONSTRAINT payment_transactions_provider_ref_chk CHECK ((((payment_provider = 'stripe'::text) AND (session_id IS NOT NULL) AND ((length(session_id) >= 1) AND (length(session_id) <= 255)) AND (session_id ~* '^(cs_|pi_|in_)[a-zA-Z0-9_]+$'::text)) OR ((payment_provider = 'bank_transfer'::text) AND (session_id IS NULL) AND (pricing_snapshot_version IS NOT NULL) AND ((stripe_payment_intent_id IS NULL) OR ((NOT (settled_via IS DISTINCT FROM 'stripe'::text)) AND (stripe_payment_intent_id ~ '^pi_[A-Za-z0-9_]+$'::text)))))),
    CONSTRAINT payment_transactions_refund_id_check CHECK (((refund_id IS NULL) OR (((length(refund_id) >= 1) AND (length(refund_id) <= 255)) AND (refund_id ~* '^re_[a-zA-Z0-9_]+$'::text)))),
    CONSTRAINT payment_transactions_refund_reason_check CHECK (((refund_reason IS NULL) OR ((length(refund_reason) >= 1) AND (length(refund_reason) <= 1000)))),
    CONSTRAINT payment_transactions_refund_status_check CHECK ((refund_status = ANY (ARRAY['pending'::text, 'requires_action'::text, 'succeeded'::text, 'failed'::text, 'canceled'::text]))),
    CONSTRAINT payment_transactions_refunded_amount_check CHECK (((refunded_amount >= (0)::numeric) AND (refunded_amount IS NOT NULL))),
    CONSTRAINT payment_transactions_settled_via_check CHECK ((settled_via = ANY (ARRAY['bank_transfer'::text, 'stripe'::text]))),
    CONSTRAINT payment_transactions_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'completed'::text, 'refunded'::text, 'partially_refunded'::text, 'disputed'::text, 'abandoned'::text, 'awaiting_payment'::text, 'cancelled'::text]))),
    CONSTRAINT payment_transactions_stripe_payment_intent_id_check CHECK (((stripe_payment_intent_id IS NULL) OR (((length(stripe_payment_intent_id) >= 1) AND (length(stripe_payment_intent_id) <= 255)) AND (stripe_payment_intent_id ~* '^pi_[a-zA-Z0-9_]+$'::text)))),
    CONSTRAINT payment_transactions_tax_snapshot_status_chk CHECK ((tax_snapshot_status = ANY (ARRAY['none'::text, 'captured'::text, 'partial'::text, 'unavailable'::text, 'local'::text]))),
    CONSTRAINT payment_transactions_transfer_declared_note_check CHECK ((length(transfer_declared_note) <= 200)),
    CONSTRAINT valid_refund_amount CHECK ((refunded_amount <= amount))
);

ALTER TABLE ONLY public.payment_transactions REPLICA IDENTITY FULL;


ALTER TABLE public.payment_transactions OWNER TO postgres;

--
-- Name: COLUMN payment_transactions.status; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.payment_transactions.status IS 'Payment status flow:
- pending: Payment Intent created, awaiting payment
- completed: Payment successful
- abandoned: Payment expired or user left without paying
- refunded: Payment was refunded
- disputed: Payment disputed (chargeback)';


--
-- Name: COLUMN payment_transactions.abandoned_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.payment_transactions.abandoned_at IS 'Timestamp when payment was marked as abandoned (either manually or automatically after expiration)';


--
-- Name: COLUMN payment_transactions.expires_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.payment_transactions.expires_at IS 'When this pending payment expires (typically 24 hours after creation). NULL for non-pending statuses.';


--
-- Name: COLUMN payment_transactions.custom_field_values; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.payment_transactions.custom_field_values IS 'Map of field_id → buyer-typed string. Validated against the buying product''s custom_checkout_fields before insert.';


--
-- Name: COLUMN payment_transactions.net_total; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.payment_transactions.net_total IS 'MINOR units (cents); Stripe amount_subtotal.';


--
-- Name: COLUMN payment_transactions.tax_total; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.payment_transactions.tax_total IS 'MINOR units (cents); matches Stripe total_details.amount_tax verbatim.';


--
-- Name: COLUMN payment_transactions.tax_snapshot_status; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.payment_transactions.tax_snapshot_status IS 'none = no tax line; captured = full per-line snapshot; partial = totals only (line match failed); unavailable = tax not computable.';


--
-- Name: COLUMN payment_transactions.fulfillment_pending; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.payment_transactions.fulfillment_pending IS 'Explicitly unfinished fulfillment; existing and directly inserted completed orders default to fulfilled.';


--
-- Name: COLUMN payment_transactions.order_details; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.payment_transactions.order_details IS 'Versioned order module details (max 65536 bytes).';


--
-- Name: COLUMN payment_transactions.refund_status; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.payment_transactions.refund_status IS 'Status returned by Stripe for refund_id; NULL when not observed. Never inferred from payment status.';


