--
-- Name: list_orders_missing_participants(boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.list_orders_missing_participants(p_unsent_only boolean DEFAULT false, p_limit integer DEFAULT 100) RETURNS TABLE(id uuid, order_number bigint, customer_email text, product_id uuid, product_name text, quantity integer, created_at timestamp with time zone, mail_sent_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF (select auth.role()) IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Service role required' USING ERRCODE = '42501'; END IF;
  RETURN QUERY
  SELECT t.id, t.order_number, t.customer_email, t.product_id, p.name,
    coalesce((t.order_details->'quantity'->>'value')::integer, 1), t.created_at,
    coalesce(t.participants_reminder2_sent_at, t.participants_mail_sent_at)
  FROM public.payment_transactions t JOIN public.products p ON p.id = t.product_id
  WHERE public.order_awaits_participants(t.order_details, p.checkout_profile, t.status)
    AND (NOT p_unsent_only OR t.participants_mail_sent_at IS NULL)
  ORDER BY t.created_at, t.id LIMIT greatest(1, least(p_limit, 500));
END $$;


ALTER FUNCTION public.list_orders_missing_participants(p_unsent_only boolean, p_limit integer) OWNER TO postgres;

--
-- Name: list_participants_reminders_due(timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.list_participants_reminders_due(p_now timestamp with time zone DEFAULT now(), p_limit integer DEFAULT 50) RETURNS TABLE(id uuid, stage integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF (select auth.role()) IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Service role required' USING ERRCODE = '42501'; END IF;
  RETURN QUERY
  WITH waiting AS (
    SELECT t.id, t.participants_mail_sent_at AS first_sent, t.participants_reminder2_sent_at AS second_sent,
      coalesce(t.paid_at, t.created_at) AS bought_at,
      (SELECT min(s.starts_at) FROM public.payment_line_items l JOIN public.product_sessions s ON s.id = l.session_id
        WHERE l.transaction_id = t.id) AS event_at
    FROM public.payment_transactions t JOIN public.products p ON p.id = t.product_id
    WHERE public.order_awaits_participants(t.order_details, p.checkout_profile, t.status)
  )
  SELECT w.id, CASE
      WHEN w.event_at IS NOT NULL AND w.second_sent IS NULL AND p_now >= w.event_at - interval '2 days' AND p_now < w.event_at THEN 2
      WHEN w.first_sent IS NULL AND p_now >= w.bought_at + interval '24 hours' AND (w.event_at IS NULL OR p_now < w.event_at) THEN 1
    END
  FROM waiting w
  WHERE (w.event_at IS NOT NULL AND w.second_sent IS NULL AND p_now >= w.event_at - interval '2 days' AND p_now < w.event_at)
     OR (w.first_sent IS NULL AND p_now >= w.bought_at + interval '24 hours' AND (w.event_at IS NULL OR p_now < w.event_at))
  ORDER BY w.bought_at, w.id LIMIT greatest(1, least(p_limit, 500));
END $$;


ALTER FUNCTION public.list_participants_reminders_due(p_now timestamp with time zone, p_limit integer) OWNER TO postgres;

--
-- Name: log_admin_action(text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_admin_action(action_name text, target_type text, target_id text, action_details jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '2s'
    AS $$
BEGIN
    -- Service role: scoped rate limit per action+target_type
    IF (select auth.role()) = 'service_role' THEN
        IF NOT public.check_rate_limit(
            'log_admin_action_svc_' || left(action_name, 30) || '_' || left(target_type, 20),
            500, 3600
        ) THEN
            RAISE EXCEPTION 'Rate limit exceeded for action %/%. Please wait.', action_name, target_type;
        END IF;
    ELSIF ( select public.is_admin() ) THEN
        -- Admin users (direct DB access): 200 log entries per hour
        IF NOT public.check_rate_limit('log_admin_action_admin', 200, 3600) THEN
            RAISE EXCEPTION 'Rate limit exceeded: Too many admin actions logged. Please wait before performing more actions.';
        END IF;
    ELSE
        -- Non-admin authenticated users: 20 log entries per hour (much stricter)
        IF NOT public.check_rate_limit('log_admin_action_user', 20, 3600) THEN
            RAISE EXCEPTION 'Rate limit exceeded: Too many log entries. Please wait before performing more actions.';
        END IF;
    END IF;

    -- Input validation
    IF action_name IS NULL OR length(action_name) = 0 OR length(action_name) > 100 THEN
        RAISE EXCEPTION 'Invalid action name: must be 1-100 characters';
    END IF;
    
    IF target_type IS NULL OR length(target_type) = 0 OR length(target_type) > 50 THEN
        RAISE EXCEPTION 'Invalid target type: must be 1-50 characters';
    END IF;
    
    IF target_id IS NULL OR length(target_id) = 0 OR length(target_id) > 255 THEN
        RAISE EXCEPTION 'Invalid target ID: must be 1-255 characters';
    END IF;
    
    -- Validate JSONB is not too large (prevent DoS) - reduced limit for non-admins
    IF ( select public.is_admin() ) THEN
        -- Admins can log larger details (64KB) for legitimate debugging
        IF pg_column_size(action_details) > 65536 THEN -- 64KB limit
            RAISE EXCEPTION 'Action details too large (max 64KB for admins)';
        END IF;
    ELSE
        -- Non-admin users get much smaller limit (8KB) to prevent abuse
        IF pg_column_size(action_details) > 8192 THEN -- 8KB limit
            RAISE EXCEPTION 'Action details too large (max 8KB for non-admin users)';
        END IF;
    END IF;
    
    -- Insert admin action with proper user identification
    INSERT INTO public.admin_actions (admin_id, action, target_type, target_id, details)
    VALUES (
        auth.uid(), -- NULL for system operations when no user is logged in
        action_name,
        target_type,
        target_id,
        action_details
    );
END;
$$;


ALTER FUNCTION public.log_admin_action(action_name text, target_type text, target_id text, action_details jsonb) OWNER TO postgres;

--
-- Name: log_admin_action_trigger(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_admin_action_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    action_name TEXT;
    action_details JSONB;
BEGIN
    -- Only log if the user is an admin
    IF ( select public.is_admin() ) THEN
        -- Determine specific action name based on operation and changes
        IF TG_OP = 'UPDATE' AND TG_TABLE_NAME = 'payment_transactions' THEN
            IF OLD.status != NEW.status AND NEW.status = 'refunded' THEN
                action_name := 'payment_refunded';
                -- Standardized logging format
                action_details := jsonb_build_object(
                    'severity', 'INFO',
                    'action_type', 'payment_status_change',
                    'transaction_id', NEW.id,
                    'old_status', OLD.status,
                    'new_status', NEW.status,
                    'refunded_amount', NEW.refunded_amount,
                    'refund_reason', NEW.refund_reason,
                    'refunded_at', NEW.refunded_at,
                    'refunded_by', auth.uid(),
                    'customer_email_hash', encode(extensions.digest(NEW.customer_email, 'sha256'), 'hex'),
                    'function_name', 'log_admin_action_trigger',
                    'timestamp', extract(epoch from NOW()),
                    'context', 'payment_refund_processing'
                );
            ELSE
                action_name := 'payment_updated';
                -- Standardized logging format
                action_details := jsonb_build_object(
                    'severity', 'INFO',
                    'action_type', 'payment_modification',
                    'transaction_id', NEW.id,
                    'changed_fields', jsonb_build_object(
                        'status', CASE WHEN OLD.status != NEW.status THEN jsonb_build_object('old', OLD.status, 'new', NEW.status) END,
                        'refunded_amount', CASE WHEN OLD.refunded_amount != NEW.refunded_amount THEN jsonb_build_object('old', OLD.refunded_amount, 'new', NEW.refunded_amount) END,
                        'updated_at', NEW.updated_at
                    ),
                    'function_name', 'log_admin_action_trigger',
                    'timestamp', extract(epoch from NOW()),
                    'context', 'payment_update_processing'
                );
            END IF;
        ELSIF TG_OP = 'UPDATE' AND TG_TABLE_NAME = 'guest_purchases' THEN
            action_name := 'guest_purchase_claimed';
            -- Standardized logging format
            action_details := jsonb_build_object(
                'severity', 'INFO',
                'action_type', 'guest_purchase_claim',
                'purchase_id', NEW.id,
                'claimed_by', NEW.claimed_by_user_id,
                'claimed_at', NEW.claimed_at,
                'customer_email_hash', encode(extensions.digest(NEW.customer_email, 'sha256'), 'hex'),
                'product_id', NEW.product_id,
                'function_name', 'log_admin_action_trigger',
                'timestamp', extract(epoch from NOW()),
                'context', 'guest_claim_processing'
            );
        ELSE
            action_name := TG_OP::TEXT;
            -- Standardized logging format for generic operations
            action_details := CASE
                WHEN TG_OP = 'INSERT' THEN jsonb_build_object(
                    'severity', 'INFO',
                    'action_type', 'record_creation',
                    'record_id', NEW.id,
                    'table', TG_TABLE_NAME,
                    'operation', 'INSERT',
                    'function_name', 'log_admin_action_trigger',
                    'timestamp', extract(epoch from NOW()),
                    'context', 'database_operation'
                )
                WHEN TG_OP = 'DELETE' THEN jsonb_build_object(
                    'severity', 'INFO',
                    'action_type', 'record_deletion',
                    'record_id', OLD.id,
                    'table', TG_TABLE_NAME,
                    'operation', 'DELETE',
                    'function_name', 'log_admin_action_trigger',
                    'timestamp', extract(epoch from NOW()),
                    'context', 'database_operation'
                )
                ELSE jsonb_build_object(
                    'severity', 'WARNING',
                    'action_type', 'unknown_operation',
                    'operation', 'UNKNOWN',
                    'function_name', 'log_admin_action_trigger',
                    'timestamp', extract(epoch from NOW()),
                    'context', 'database_operation'
                )
            END;
        END IF;

        -- Use the main log_admin_action function
        PERFORM public.log_admin_action(
            action_name,
            TG_TABLE_NAME::TEXT,
            COALESCE(NEW.id::TEXT, OLD.id::TEXT),
            action_details
        );
    END IF;

    RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION public.log_admin_action_trigger() OWNER TO postgres;

--
-- Name: log_audit_entry(text, text, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_audit_entry(table_name_param text, operation_param text, old_values_param jsonb DEFAULT NULL::jsonb, new_values_param jsonb DEFAULT NULL::jsonb, user_id_param uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '2s'
    AS $$
BEGIN
    -- Input validation
    IF table_name_param IS NULL OR length(table_name_param) = 0 OR length(table_name_param) > 100 THEN
        RAISE EXCEPTION 'Invalid table name: must be 1-100 characters';
    END IF;
    
    IF operation_param IS NULL OR operation_param NOT IN ('INSERT', 'UPDATE', 'DELETE') THEN
        RAISE EXCEPTION 'Invalid operation: must be INSERT, UPDATE, or DELETE';
    END IF;
    
    -- Validate JSONB size (prevent DoS)
    IF pg_column_size(old_values_param) > 65536 THEN -- 64KB limit
        RAISE EXCEPTION 'Old values too large (max 64KB)';
    END IF;
    
    IF pg_column_size(new_values_param) > 65536 THEN -- 64KB limit
        RAISE EXCEPTION 'New values too large (max 64KB)';
    END IF;
    
    -- Insert audit entry
    INSERT INTO public.audit_log (
        table_name, 
        operation, 
        old_values, 
        new_values, 
        user_id,
        performed_at
    ) VALUES (
        table_name_param,
        operation_param,
        old_values_param,
        new_values_param,
        COALESCE(user_id_param, auth.uid()),
        NOW()
    );
END;
$$;


ALTER FUNCTION public.log_audit_entry(table_name_param text, operation_param text, old_values_param jsonb, new_values_param jsonb, user_id_param uuid) OWNER TO postgres;

--
-- Name: log_product_price_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_product_price_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  -- Only log if price or sale_price actually changed
  IF (TG_OP = 'UPDATE' AND
      (OLD.price != NEW.price OR
       OLD.sale_price IS DISTINCT FROM NEW.sale_price OR
       OLD.currency != NEW.currency OR
       OLD.vat_rate != NEW.vat_rate)) OR
     TG_OP = 'INSERT' THEN

    -- Close previous price period
    IF TG_OP = 'UPDATE' THEN
      UPDATE public.product_price_history
      SET effective_until = NOW()
      WHERE product_id = OLD.id
        AND effective_until IS NULL;
    END IF;

    -- Insert new price record
    INSERT INTO public.product_price_history (
      product_id, price, sale_price, currency, vat_rate,
      price_includes_vat, effective_from
    ) VALUES (
      NEW.id, NEW.price, NEW.sale_price, NEW.currency, NEW.vat_rate,
      NEW.price_includes_vat, NOW()
    );
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.log_product_price_change() OWNER TO postgres;

--
-- Name: FUNCTION log_product_price_change(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.log_product_price_change() IS 'Automatically logs price changes to product_price_history for Omnibus compliance';


--
-- Name: logs_monitoring_check(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.logs_monitoring_check(new_action_details jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '2s'
    AS $$
DECLARE
    warning_count INTEGER;
    last_email_sent TIMESTAMPTZ;
BEGIN
    -- If this is a CRITICAL event passed from trigger - send immediate email!
    IF new_action_details IS NOT NULL AND (new_action_details->>'severity') = 'CRITICAL' THEN
        -- Send immediate email for every critical event
        BEGIN
            PERFORM public.send_monitoring_email(
                'critical_event_immediate',
                jsonb_build_object(
                    'severity', 'CRITICAL',
                    'event_type', 'immediate_critical_alert',
                    'action_details', new_action_details,
                    'timestamp', extract(epoch from NOW()),
                    'message', 'CRITICAL: Immediate attention required',
                    'action_required', 'Please investigate immediately',
                    'dashboard_link', '/admin/monitoring',
                    'urgent', true
                )
            );
        EXCEPTION 
            WHEN OTHERS THEN
                NULL; -- Never break the main operation
        END;
    END IF;
    
    -- For WARNING events OR regular monitoring check - handle batch warnings
    IF new_action_details IS NULL OR (new_action_details->>'severity') = 'WARNING' THEN
        -- Count warnings in last 5 minutes (for batch alerts)
        SELECT COUNT(*) INTO warning_count
        FROM public.admin_actions
        WHERE (details->>'severity') = 'WARNING'
          AND (details->>'context') LIKE '%payment%'
          AND created_at > NOW() - INTERVAL '5 minutes';
        
        -- Check when we last sent payment alert email
        SELECT MAX(created_at) INTO last_email_sent
        FROM public.admin_actions
        WHERE action = 'monitoring_email_sent'
          AND (details->>'alert_type') = 'payment_issues';
        
        -- If too many payment warnings AND we haven't sent email recently
        IF warning_count >= 5 AND 
           (last_email_sent IS NULL OR last_email_sent < NOW() - INTERVAL '15 minutes') THEN
            
            -- Send email about payment issues
            PERFORM public.send_monitoring_email(
                'payment_issues',
                jsonb_build_object(
                    'warning_count', warning_count,
                    'time_window', '5 minutes',
                    'severity', 'MEDIUM',
                    'message', 'Payment system has ' || warning_count || ' warnings in last 5 minutes',
                    'action_required', 'Please review payment processing',
                    'dashboard_link', '/admin/payments'
                )
            );
            
            -- Log that we sent email (just once)
            PERFORM public.log_admin_action(
                'monitoring_email_sent',
                'admin_actions',
                'email_notification', 
                jsonb_build_object(
                    'severity', 'INFO',
                    'alert_type', 'payment_issues',
                    'warning_count', warning_count,
                    'email_sent_at', extract(epoch from NOW()),
                    'function_name', 'logs_monitoring_check',
                    'context', 'email_notification'
                )
            );
        END IF;
    END IF;
    
EXCEPTION 
    WHEN OTHERS THEN
        -- Don't break anything if monitoring fails
        NULL;
END;
$$;


ALTER FUNCTION public.logs_monitoring_check(new_action_details jsonb) OWNER TO postgres;

--
-- Name: logs_monitoring_trigger(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.logs_monitoring_trigger() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
    -- Call unified monitoring function for any CRITICAL or WARNING event
    IF TG_TABLE_NAME = 'admin_actions' AND 
       (NEW.details->>'severity') IN ('CRITICAL', 'WARNING') THEN
        
        -- Pass the event details to the monitoring function
        BEGIN
            PERFORM public.logs_monitoring_check(NEW.details);
        EXCEPTION 
            WHEN OTHERS THEN
                NULL; -- Never break the main operation
        END;
    END IF;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.logs_monitoring_trigger() OWNER TO postgres;

--
-- Name: mark_checkout_details_missing(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_checkout_details_missing() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  profile jsonb;
  module jsonb;
  details jsonb := coalesce(NEW.order_details, '{}'::jsonb);
  missing boolean := false;
  missing_modules jsonb := '[]'::jsonb;
BEGIN
  SELECT checkout_profile INTO profile FROM public.products WHERE id = NEW.product_id;
  IF profile IS NULL THEN
    IF NEW.order_details ? 'details_missing' OR NEW.order_details ? 'missing_modules' THEN
      NEW.order_details := NEW.order_details - 'details_missing' - 'missing_modules';
    END IF;
    RETURN NEW;
  END IF;
  FOR module IN SELECT value FROM jsonb_array_elements(profile->'modules') LOOP
    missing := false;
    CASE module->>'id'
      WHEN 'buyer' THEN
        missing := missing OR coalesce(jsonb_typeof(details->'buyer') <> 'object'
          OR details->'buyer'->>'type' NOT IN ('person', 'organization'), true);
      WHEN 'recipient' THEN
        IF details->'buyer'->>'type' = 'organization' THEN
          missing := missing OR coalesce(jsonb_typeof(details->'recipient'->'differs') <> 'boolean', true);
        END IF;
      WHEN 'quantity' THEN
        missing := missing OR coalesce(jsonb_typeof(details->'quantity'->'value') <> 'number', true);
      WHEN 'phone' THEN
        IF (module->>'required')::boolean THEN
          missing := missing OR coalesce(length(details->'phone'->>'value'), 0) = 0;
        END IF;
      WHEN 'participants' THEN
        IF (module->>'required')::boolean THEN
          missing := missing OR coalesce(jsonb_typeof(details->'participants'->'people') <> 'array', true);
          IF jsonb_typeof(details->'participants'->'people') = 'array' THEN
            missing := missing OR jsonb_array_length(details->'participants'->'people') = 0;
          END IF;
        END IF;
      ELSE NULL;
    END CASE;
    IF missing THEN missing_modules := missing_modules || jsonb_build_array(module->>'id'); END IF;
  END LOOP;
  NEW.order_details := details - 'details_missing' - 'missing_modules';
  IF jsonb_array_length(missing_modules) > 0 THEN
    NEW.order_details := NEW.order_details || jsonb_build_object('details_missing', true, 'missing_modules', missing_modules);
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.mark_checkout_details_missing() OWNER TO postgres;

--
-- Name: mark_expired_pending_payments(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_expired_pending_payments() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  updated_count INTEGER := 0;
BEGIN
  UPDATE public.payment_transactions
  SET
    status = 'abandoned',
    abandoned_at = NOW(),
    updated_at = NOW()
  WHERE status = 'pending'
    AND expires_at IS NOT NULL
    AND expires_at < NOW();

  GET DIAGNOSTICS updated_count = ROW_COUNT;
  RETURN updated_count;
END;
$$;


ALTER FUNCTION public.mark_expired_pending_payments() OWNER TO postgres;

