--
-- Name: user_product_access; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.user_product_access (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    product_id uuid NOT NULL,
    access_granted_at timestamp with time zone DEFAULT now() NOT NULL,
    access_expires_at timestamp with time zone,
    access_duration_days integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    expiry_notified_at timestamp with time zone,
    subscription_id uuid,
    transfer_transaction_id uuid,
    custom_field_values jsonb DEFAULT '{}'::jsonb NOT NULL,
    grant_source text NOT NULL,
    license_requested boolean DEFAULT false NOT NULL,
    independent_access jsonb,
    CONSTRAINT check_access_expiration CHECK (((access_expires_at IS NULL) OR (access_expires_at >= access_granted_at))),
    CONSTRAINT user_product_access_access_duration_days_check CHECK (((access_duration_days IS NULL) OR ((access_duration_days > 0) AND (access_duration_days <= 3650)))),
    CONSTRAINT user_product_access_custom_field_values_check CHECK ((jsonb_typeof(custom_field_values) = 'object'::text)),
    CONSTRAINT user_product_access_grant_source_chk CHECK ((grant_source = ANY (ARRAY['purchase'::text, 'bundle'::text, 'bank_transfer'::text, 'subscription'::text, 'free'::text, 'manual'::text, 'unknown'::text])))
);


ALTER TABLE public.user_product_access OWNER TO postgres;

--
-- Name: mutate_access(text, uuid, uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mutate_access(p_action text, p_user_id uuid, p_product_id uuid DEFAULT NULL::uuid, p_access_id uuid DEFAULT NULL::uuid, p_values jsonb DEFAULT '{}'::jsonb, p_actor jsonb DEFAULT '{}'::jsonb) RETURNS SETOF public.user_product_access
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE previous text := current_setting('sellf.grant_source', true); a public.user_product_access;
BEGIN
  IF (SELECT auth.role()) IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Service role required' USING ERRCODE='42501'; END IF;
  PERFORM set_config('sellf.grant_source', 'manual', true);
  IF p_action = 'revoke' THEN
    FOR a IN SELECT * FROM public.user_product_access WHERE user_id = p_user_id
      AND (id = p_access_id OR (p_access_id IS NULL AND product_id = p_product_id)) FOR UPDATE LOOP
      IF coalesce((p_values->>'revoke_license')::boolean, false) THEN
        PERFORM public.revoke_order_licenses(a.product_id, ARRAY['access_' || a.id::text], 'manual');
      END IF;
    END LOOP;
  END IF;
  FOR a IN SELECT * FROM public.mutate_access_impl(p_action, p_user_id, p_product_id, p_access_id, p_values, p_actor) LOOP
    IF p_action = 'grant' AND coalesce((p_values->>'issue_license')::boolean, false) THEN
      UPDATE public.user_product_access SET license_requested = true WHERE id = a.id RETURNING * INTO a;
    END IF;
    RETURN NEXT a;
  END LOOP;
  PERFORM set_config('sellf.grant_source', coalesce(previous, ''), true);
END $$;


ALTER FUNCTION public.mutate_access(p_action text, p_user_id uuid, p_product_id uuid, p_access_id uuid, p_values jsonb, p_actor jsonb) OWNER TO postgres;

--
-- Name: mutate_access_audited(text, uuid, uuid, uuid, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mutate_access_audited(p_action text, p_user_id uuid, p_product_id uuid DEFAULT NULL::uuid, p_access_id uuid DEFAULT NULL::uuid, p_values jsonb DEFAULT '{}'::jsonb, p_actor jsonb DEFAULT '{}'::jsonb, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS SETOF public.user_product_access
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE a public.user_product_access; changed integer := 0;
BEGIN
  IF (SELECT auth.role()) IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Service role required' USING ERRCODE='42501'; END IF;
  IF p_actor->>'type' IS DISTINCT FROM 'user' OR p_actor->>'id' IS NULL
     OR (p_audit IS NOT NULL AND jsonb_typeof(p_audit) <> 'object') THEN
    RAISE EXCEPTION 'Audited access change needs a user actor' USING ERRCODE='22023';
  END IF;
  FOR a IN SELECT * FROM public.mutate_access(p_action, p_user_id, p_product_id, p_access_id, p_values, p_actor) LOOP
    changed := changed + 1;
    RETURN NEXT a;
  END LOOP;
  IF changed > 0 THEN
    INSERT INTO public.audit_log(table_name, operation, user_id, performed_by, old_values, new_values)
      VALUES('user_product_access',
        CASE p_action WHEN 'grant' THEN 'INSERT' WHEN 'revoke' THEN 'DELETE' ELSE 'UPDATE' END,
        p_user_id, (p_actor->>'id')::uuid,
        CASE WHEN p_action = 'revoke' THEN coalesce(p_audit, '{}'::jsonb) END,
        CASE WHEN p_action <> 'revoke' THEN coalesce(p_audit, '{}'::jsonb) END);
  END IF;
END $$;


ALTER FUNCTION public.mutate_access_audited(p_action text, p_user_id uuid, p_product_id uuid, p_access_id uuid, p_values jsonb, p_actor jsonb, p_audit jsonb) OWNER TO postgres;

--
-- Name: mutate_access_impl(text, uuid, uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mutate_access_impl(p_action text, p_user_id uuid, p_product_id uuid DEFAULT NULL::uuid, p_access_id uuid DEFAULT NULL::uuid, p_values jsonb DEFAULT '{}'::jsonb, p_actor jsonb DEFAULT '{}'::jsonb) RETURNS SETOF public.user_product_access
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF (select auth.role()) IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Service role required' USING ERRCODE='42501'; END IF;
  IF coalesce(p_actor->>'type','') NOT IN ('user','api_key') OR p_actor->>'id' IS NULL THEN RAISE EXCEPTION 'Actor required'; END IF;
  PERFORM (p_actor->>'id')::uuid;
  IF (p_values->>'access_duration_days')::integer NOT BETWEEN 1 AND 3650 THEN RAISE EXCEPTION 'Invalid access duration'; END IF;
  PERFORM set_config('sellf.event_context',jsonb_build_object('actor',p_actor,'reason','admin_'||p_action)::text,true);
  IF p_action='grant' THEN
    RETURN QUERY INSERT INTO public.user_product_access(user_id,product_id,access_duration_days,access_expires_at)
      VALUES(p_user_id,p_product_id,(p_values->>'access_duration_days')::integer,(p_values->>'access_expires_at')::timestamptz) RETURNING *;
  ELSIF p_action='update' THEN
    RETURN QUERY UPDATE public.user_product_access a SET
      access_expires_at=CASE WHEN p_values ? 'access_expires_at' THEN (p_values->>'access_expires_at')::timestamptz ELSE a.access_expires_at END,
      access_duration_days=CASE WHEN p_values ? 'access_duration_days' THEN (p_values->>'access_duration_days')::integer ELSE a.access_duration_days END
      WHERE a.user_id=p_user_id AND a.id=p_access_id RETURNING *;
  ELSIF p_action='revoke' THEN
    RETURN QUERY DELETE FROM public.user_product_access a WHERE a.user_id=p_user_id AND (a.id=p_access_id OR (p_access_id IS NULL AND a.product_id=p_product_id)) RETURNING *;
  ELSE RAISE EXCEPTION 'Invalid access action'; END IF;
END $$;


ALTER FUNCTION public.mutate_access_impl(p_action text, p_user_id uuid, p_product_id uuid, p_access_id uuid, p_values jsonb, p_actor jsonb) OWNER TO postgres;

