ALTER FUNCTION public.product_marketing_valid(instance jsonb) OWNER TO postgres;

--
-- Name: products; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.products (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    slug text NOT NULL,
    description text,
    long_description text,
    icon text,
    image_url text,
    thumbnail_url text,
    price numeric DEFAULT 0 NOT NULL,
    currency text DEFAULT 'USD'::text NOT NULL,
    vat_rate numeric(5,2) DEFAULT NULL::numeric,
    price_includes_vat boolean DEFAULT true NOT NULL,
    features jsonb DEFAULT '[]'::jsonb,
    layout_template text DEFAULT 'default'::text NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    is_featured boolean DEFAULT false NOT NULL,
    is_listed boolean DEFAULT true NOT NULL,
    available_from timestamp with time zone,
    available_until timestamp with time zone,
    auto_grant_duration_days integer,
    content_delivery_type text DEFAULT 'content'::text NOT NULL,
    content_config jsonb DEFAULT '{}'::jsonb NOT NULL,
    success_redirect_url text,
    pass_params_to_redirect boolean DEFAULT false NOT NULL,
    is_refundable boolean DEFAULT false NOT NULL,
    refund_period_days integer,
    enable_waitlist boolean DEFAULT false NOT NULL,
    allow_custom_price boolean DEFAULT false NOT NULL,
    custom_price_min numeric(10,2) DEFAULT 5.00,
    show_price_presets boolean DEFAULT true NOT NULL,
    custom_price_presets jsonb DEFAULT '[5, 10, 25]'::jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    omnibus_exempt boolean DEFAULT false NOT NULL,
    sale_price numeric,
    sale_price_until timestamp with time zone,
    sale_quantity_limit integer,
    sale_quantity_sold integer DEFAULT 0 NOT NULL,
    preview_video_url text,
    product_type text DEFAULT 'one_time'::text NOT NULL,
    billing_interval text,
    billing_interval_count integer,
    recurring_price numeric(10,2),
    trial_days integer,
    stripe_price_id text,
    embed_enabled boolean DEFAULT false NOT NULL,
    seller_id uuid,
    checkout_template text DEFAULT 'default'::text NOT NULL,
    custom_checkout_fields jsonb DEFAULT '[]'::jsonb NOT NULL,
    preview_video_config jsonb DEFAULT '{}'::jsonb NOT NULL,
    stripe_product_id text,
    issue_license_on_purchase boolean DEFAULT false NOT NULL,
    license_tier text,
    license_duration_days integer,
    vat_exempt boolean DEFAULT false NOT NULL,
    vat_exempt_note text,
    is_bundle boolean DEFAULT false NOT NULL,
    marketing_fields jsonb DEFAULT '{"en": {"tools": [], "result": null, "requirements": []}, "format": null, "sourceLocale": "en"}'::jsonb NOT NULL,
    allow_repeat_purchase boolean DEFAULT false NOT NULL,
    checkout_profile jsonb,
    event_mode boolean DEFAULT false NOT NULL,
    lead_consent_required boolean DEFAULT false NOT NULL,
    lead_consent_version text DEFAULT '1'::text NOT NULL,
    lead_consent_text_pl text DEFAULT 'Chcę otrzymywać wiadomości o nowych materiałach i produktach. Mogę wypisać się w każdej chwili.'::text NOT NULL,
    lead_consent_text_en text DEFAULT 'I want to receive news about new materials and products. I can unsubscribe at any time.'::text NOT NULL,
    webhook_revision bigint DEFAULT 0 NOT NULL,
    archived_at timestamp with time zone,
    CONSTRAINT check_availability_dates CHECK (((available_from IS NULL) OR (available_until IS NULL) OR (available_from < available_until))),
    CONSTRAINT preview_video_config_is_object CHECK ((jsonb_typeof(preview_video_config) = 'object'::text)),
    CONSTRAINT products_archived_not_active CHECK (((archived_at IS NULL) OR (NOT is_active))),
    CONSTRAINT products_auto_grant_duration_days_check CHECK (((auto_grant_duration_days > 0) AND (auto_grant_duration_days <= 3650))),
    CONSTRAINT products_billing_interval_check CHECK (((billing_interval IS NULL) OR (billing_interval = ANY (ARRAY['day'::text, 'week'::text, 'month'::text, 'year'::text])))),
    CONSTRAINT products_billing_interval_count_check CHECK (((billing_interval_count IS NULL) OR (billing_interval_count > 0))),
    CONSTRAINT products_checkout_profile_check CHECK (((checkout_profile IS NULL) OR ((jsonb_typeof(checkout_profile) = 'object'::text) AND (octet_length((checkout_profile)::text) <= 8192)))),
    CONSTRAINT products_checkout_template_check CHECK ((checkout_template = ANY (ARRAY['default'::text, 'tip-jar'::text, 'oto'::text]))),
    CONSTRAINT products_content_delivery_type_check CHECK ((content_delivery_type = ANY (ARRAY['redirect'::text, 'content'::text]))),
    CONSTRAINT products_currency_check CHECK (((length(currency) = 3) AND (upper(currency) ~ '^[A-Z]{3}$'::text) AND (upper(currency) = ANY (ARRAY['USD'::text, 'EUR'::text, 'GBP'::text, 'CAD'::text, 'AUD'::text, 'JPY'::text, 'CHF'::text, 'CNY'::text, 'SEK'::text, 'NOK'::text, 'DKK'::text, 'PLN'::text, 'CZK'::text, 'HUF'::text, 'RON'::text, 'BGN'::text, 'HRK'::text, 'RUB'::text, 'TRY'::text, 'BRL'::text, 'MXN'::text, 'INR'::text, 'KRW'::text, 'SGD'::text, 'HKD'::text, 'NZD'::text, 'ZAR'::text, 'ILS'::text, 'THB'::text, 'MYR'::text, 'PHP'::text, 'IDR'::text, 'VND'::text])))),
    CONSTRAINT products_custom_price_min_check CHECK ((custom_price_min >= (0)::numeric)),
    CONSTRAINT products_description_check CHECK ((length(description) <= 2000)),
    CONSTRAINT products_event_mode_check CHECK (((NOT event_mode) OR ((product_type = 'one_time'::text) AND (NOT is_bundle) AND (NOT allow_custom_price)))),
    CONSTRAINT products_icon_check CHECK ((length(icon) <= 500)),
    CONSTRAINT products_layout_template_check CHECK ((length(layout_template) <= 100)),
    CONSTRAINT products_lead_consent_text_en_check CHECK (((length(btrim(lead_consent_text_en)) >= 1) AND (length(btrim(lead_consent_text_en)) <= 500))),
    CONSTRAINT products_lead_consent_text_pl_check CHECK (((length(btrim(lead_consent_text_pl)) >= 1) AND (length(btrim(lead_consent_text_pl)) <= 500))),
    CONSTRAINT products_lead_consent_version_check CHECK ((lead_consent_version ~ '^[a-zA-Z0-9._-]{1,60}$'::text)),
    CONSTRAINT products_license_duration_days_check CHECK (((license_duration_days IS NULL) OR (license_duration_days > 0))),
    CONSTRAINT products_marketing_shape CHECK (public.product_marketing_valid(marketing_fields)),
    CONSTRAINT products_marketing_size CHECK ((octet_length((marketing_fields)::text) <= 8192)),
    CONSTRAINT products_name_check CHECK ((length(name) <= 255)),
    CONSTRAINT products_price_check CHECK ((price >= (0)::numeric)),
    CONSTRAINT products_product_type_check CHECK ((product_type = ANY (ARRAY['one_time'::text, 'subscription'::text]))),
    CONSTRAINT products_recurring_price_check CHECK (((recurring_price IS NULL) OR (recurring_price >= (0)::numeric))),
    CONSTRAINT products_refund_period_days_check CHECK (((refund_period_days IS NULL) OR ((refund_period_days > 0) AND (refund_period_days <= 365)))),
    CONSTRAINT products_sale_price_check CHECK ((sale_price >= (0)::numeric)),
    CONSTRAINT products_sale_quantity_limit_check CHECK (((sale_quantity_limit IS NULL) OR (sale_quantity_limit > 0))),
    CONSTRAINT products_sale_quantity_sold_check CHECK ((sale_quantity_sold >= 0)),
    CONSTRAINT products_slug_check CHECK (((slug ~ '^[a-zA-Z0-9_-]+$'::text) AND ((length(slug) >= 1) AND (length(slug) <= 100)))),
    CONSTRAINT products_subscription_complete CHECK (((product_type = 'one_time'::text) OR ((product_type = 'subscription'::text) AND (billing_interval IS NOT NULL) AND (billing_interval_count IS NOT NULL) AND (recurring_price IS NOT NULL)))),
    CONSTRAINT products_tipjar_requires_pwyw CHECK (((checkout_template <> 'tip-jar'::text) OR (allow_custom_price = true))),
    CONSTRAINT products_trial_days_check CHECK (((trial_days IS NULL) OR ((trial_days >= 0) AND (trial_days <= 730)))),
    CONSTRAINT products_webhook_revision_check CHECK ((webhook_revision >= 0))
);


ALTER TABLE public.products OWNER TO postgres;

--
-- Name: TABLE products; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.products IS 'Products catalog with sellf integration support';


--
-- Name: COLUMN products.slug; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.products.slug IS 'URL-safe unique identifier for sellf system';


--
-- Name: COLUMN products.content_config; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.products.content_config IS 'JSON configuration for content delivery and sellf integration';


--
-- Name: COLUMN products.omnibus_exempt; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.products.omnibus_exempt IS 'Exempt this product from Omnibus price history display (e.g., perishable goods, new arrivals <30 days)';


--
-- Name: COLUMN products.sale_price; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.products.sale_price IS 'Promotional price for the product. When set and active (not expired), this is the public discounted price that triggers Omnibus display.';


--
-- Name: COLUMN products.sale_price_until; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.products.sale_price_until IS 'Optional expiration date for sale_price. NULL means sale price is active indefinitely. When date passes, sale_price is no longer used.';


--
-- Name: COLUMN products.sale_quantity_limit; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.products.sale_quantity_limit IS 'Maximum number of units that can be sold at sale price (NULL = unlimited). When limit is reached, sale_price is no longer used.';


--
-- Name: COLUMN products.sale_quantity_sold; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.products.sale_quantity_sold IS 'Number of units already sold at sale price. Automatically incremented on successful payment when sale is active.';


--
-- Name: COLUMN products.checkout_template; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.products.checkout_template IS 'Slug of the React template that renders /checkout/<slug>. Allowed values mirrored in admin-panel/src/lib/checkout-templates/types.ts.';


--
-- Name: COLUMN products.custom_checkout_fields; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.products.custom_checkout_fields IS 'Array of {id,type,label,required,max_length,placeholder?} definitions. Shape validated at API layer (lib/validations/custom-checkout-fields.ts).';


--
-- Name: COLUMN products.stripe_product_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.products.stripe_product_id IS 'Stripe Product ID lazily created the first time a buyer initiates a PWYW subscription for this product. Reused for subsequent dynamic-price subscriptions so we never accumulate one Stripe Product per donation amount.';


--
-- Name: COLUMN products.vat_exempt; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.products.vat_exempt IS 'Product sold VAT-exempt ("zwolniony / zw."), distinct from a 0% rate. Carried into the order tax snapshot. Default for new products inherits shop_config.is_vat_exempt.';


--
-- Name: mutate_product_as(jsonb, text, jsonb, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mutate_product_as(event_actor jsonb, operation_param text, product_data jsonb, product_id uuid, actor_id uuid) RETURNS SETOF public.products
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM public.set_business_event_actor(event_actor);
  RETURN QUERY SELECT * FROM public.mutate_product_with_audit(operation_param,product_data,product_id,actor_id);
END $$;


ALTER FUNCTION public.mutate_product_as(event_actor jsonb, operation_param text, product_data jsonb, product_id uuid, actor_id uuid) OWNER TO postgres;

--
-- Name: mutate_product_offer(uuid, bigint, text, jsonb, bigint, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mutate_product_offer(offer_product_id uuid, expected_revision bigint, operation text, validated_config jsonb, restored_from bigint DEFAULT NULL::bigint, actor_user_id uuid DEFAULT NULL::uuid, actor_method text DEFAULT NULL::text, actor_api_key_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
 current_config public.product_offer_config%ROWTYPE;
 owner_id uuid; key_record public.api_keys%ROWTYPE; required_scope text;
 next_draft jsonb; next_published jsonb; candidate jsonb; product_public boolean;
BEGIN
 IF (SELECT auth.role()) IS DISTINCT FROM 'service_role' THEN RETURN jsonb_build_object('success',false,'code','FORBIDDEN'); END IF;
 SELECT id INTO owner_id FROM public.admin_users WHERE user_id=actor_user_id FOR SHARE;
 IF owner_id IS NULL OR actor_method IS NULL OR actor_method NOT IN ('session','api_key') OR
   (actor_method='session' AND actor_api_key_id IS NOT NULL) THEN RETURN jsonb_build_object('success',false,'code','FORBIDDEN'); END IF;
 required_scope := CASE WHEN operation IN ('publish','rollback') THEN 'templates:activate' ELSE 'templates:write' END;
 IF actor_method='api_key' THEN
   SELECT * INTO key_record FROM public.api_keys WHERE id=actor_api_key_id FOR SHARE;
   IF NOT FOUND OR key_record.admin_user_id IS DISTINCT FROM owner_id OR key_record.revoked_at IS NOT NULL OR
     (NOT key_record.is_active AND (key_record.rotation_grace_until IS NULL OR key_record.rotation_grace_until <= clock_timestamp())) OR
     (key_record.expires_at IS NOT NULL AND key_record.expires_at <= clock_timestamp()) OR
     NOT (key_record.scopes @> jsonb_build_array(required_scope)) THEN RETURN jsonb_build_object('success',false,'code','FORBIDDEN'); END IF;
 END IF;
 IF expected_revision IS NULL OR expected_revision NOT BETWEEN 0 AND 9007199254740991 OR
   (restored_from IS NOT NULL AND restored_from NOT BETWEEN 0 AND 9007199254740991) THEN RETURN jsonb_build_object('success',false,'code','LIMIT'); END IF;
 IF operation IS NULL OR operation NOT IN ('draft','reset','publish','rollback') OR (operation<>'rollback' AND restored_from IS NOT NULL) THEN RETURN jsonb_build_object('success',false,'code','INVALID'); END IF;
 -- The canonical product also serializes concurrent first edits and deletion.
 SELECT is_active AND is_listed INTO product_public FROM public.products WHERE id=offer_product_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'code','NOT_FOUND'); END IF;
 SELECT * INTO current_config FROM public.product_offer_config WHERE product_id=offer_product_id FOR UPDATE;
 IF NOT FOUND THEN current_config.revision := 0; END IF;
 IF expected_revision <> current_config.revision THEN RETURN jsonb_build_object('success',false,'code','CONFLICT','currentRevision',current_config.revision); END IF;
 IF current_config.revision=9007199254740991 THEN RETURN jsonb_build_object('success',false,'code','LIMIT'); END IF;
 next_draft := current_config.draft; next_published := current_config.published;
 IF operation IN ('draft','reset') THEN
   IF validated_config IS NULL THEN RETURN jsonb_build_object('success',false,'code','INVALID'); END IF;
   next_draft := validated_config; candidate := validated_config;
 ELSIF operation='publish' THEN
   IF validated_config IS NOT NULL OR current_config.draft IS NULL THEN RETURN jsonb_build_object('success',false,'code','INVALID'); END IF;
   next_published := current_config.draft; next_draft := NULL; candidate := next_published;
 ELSE
   IF validated_config IS NOT NULL OR restored_from IS NULL THEN RETURN jsonb_build_object('success',false,'code','INVALID'); END IF;
   SELECT h.published INTO next_published FROM public.product_offer_history h WHERE h.product_id=offer_product_id AND h.revision=mutate_product_offer.restored_from;
   IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'code','NOT_FOUND'); END IF;
   next_draft := NULL; candidate := next_published;
 END IF;
 IF public.storefront_config_stored_bytes(candidate)>102400 OR public.storefront_config_stored_bytes(next_published)>102400 THEN RETURN jsonb_build_object('success',false,'code','LIMIT'); END IF;
 IF (candidate IS NOT NULL AND public.product_offer_config_valid(candidate) IS DISTINCT FROM true) OR
    (next_published IS NOT NULL AND public.product_offer_config_valid(next_published) IS DISTINCT FROM true) THEN RETURN jsonb_build_object('success',false,'code','INVALID'); END IF;
 IF operation IN ('publish','rollback') AND candidate->>'enabled'='true' AND product_public IS DISTINCT FROM true THEN RETURN jsonb_build_object('success',false,'code','INVALID'); END IF;
 IF current_config.product_id IS NULL THEN
   INSERT INTO public.product_offer_config(product_id) VALUES(offer_product_id);
   INSERT INTO public.product_offer_history(product_id,revision,operation,actor_id) VALUES(offer_product_id,0,'draft',actor_user_id);
 END IF;
 UPDATE public.product_offer_config SET revision=current_config.revision+1,draft=next_draft,published=next_published,updated_at=clock_timestamp(),updated_by=actor_user_id WHERE product_id=offer_product_id;
 INSERT INTO public.product_offer_history(product_id,revision,operation,draft,published,actor_id,restored_from)
 VALUES(offer_product_id,current_config.revision+1,operation,next_draft,next_published,actor_user_id,restored_from);
 INSERT INTO public.audit_log(table_name,operation,user_id,performed_by,new_values)
 VALUES('product_offer_config','UPDATE',actor_user_id,actor_user_id,jsonb_build_object('productId',offer_product_id,'revision',current_config.revision+1,'action',operation,'scope',required_scope,'actor_method',actor_method,'actor_api_key_id',actor_api_key_id));
 RETURN jsonb_build_object('success',true,'revision',current_config.revision+1);
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('success',false,'code','UNAVAILABLE');
END; $$;


ALTER FUNCTION public.mutate_product_offer(offer_product_id uuid, expected_revision bigint, operation text, validated_config jsonb, restored_from bigint, actor_user_id uuid, actor_method text, actor_api_key_id uuid) OWNER TO postgres;

--
-- Name: mutate_product_with_audit(text, jsonb, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mutate_product_with_audit(operation_param text, product_data jsonb, product_id uuid, actor_id uuid) RETURNS SETOF public.products
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
DECLARE
  before_row public.products;
  after_row public.products;
  columns_sql text;
  sessions jsonb := product_data->'sessions';
  session_json jsonb; tier_json jsonb; sid uuid; tid uuid;
  kept_sessions uuid[] := '{}'; kept_tiers uuid[]; before_sessions jsonb;

BEGIN
  -- Only the server supplies the actor, after session or API-key authentication.
  IF (SELECT auth.role()) IS DISTINCT FROM 'service_role'
     OR NOT EXISTS (SELECT 1 FROM public.admin_users WHERE user_id = actor_id) THEN
    RAISE EXCEPTION 'Administrator required' USING ERRCODE = '42501';
  END IF;
  IF operation_param NOT IN ('INSERT', 'UPDATE', 'DELETE') OR operation_param IS NULL
     OR product_data IS NULL OR jsonb_typeof(product_data) <> 'object' THEN
    RAISE EXCEPTION 'Invalid product mutation' USING ERRCODE = '22023';
  END IF;
  product_data := product_data - 'sessions';
  IF EXISTS (
    SELECT 1 FROM jsonb_object_keys(product_data) AS k(name)
    WHERE name IN ('id', 'created_at', 'updated_at') OR NOT EXISTS (
      SELECT 1 FROM pg_catalog.pg_attribute
      WHERE attrelid = 'public.products'::regclass AND attname = k.name
        AND attnum > 0 AND NOT attisdropped
    )
  ) THEN
    RAISE EXCEPTION 'Invalid product fields' USING ERRCODE = '22023';
  END IF;

  IF operation_param IN ('UPDATE', 'DELETE') THEN
    SELECT * INTO before_row FROM public.products WHERE id = product_id FOR NO KEY UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Product not found' USING ERRCODE = 'P0002';
    END IF;
  END IF;

  IF sessions IS NOT NULL THEN
    IF jsonb_typeof(sessions) <> 'array' OR jsonb_array_length(sessions) > 50 THEN
      RAISE EXCEPTION 'Invalid sessions' USING ERRCODE = '23514';
    END IF;
    SELECT coalesce(jsonb_agg(to_jsonb(s)), '[]') INTO before_sessions FROM public.product_sessions s WHERE s.product_id = mutate_product_with_audit.product_id;
    FOR sid IN SELECT id FROM public.product_sessions WHERE product_sessions.product_id = mutate_product_with_audit.product_id ORDER BY id LOOP
      PERFORM pg_advisory_xact_lock(hashtextextended(sid::text, 0));
    END LOOP;
  END IF;

  SELECT string_agg(format('%I', name), ', ' ORDER BY name)
    INTO columns_sql FROM jsonb_object_keys(product_data) AS k(name);
  IF operation_param = 'INSERT' THEN
    IF columns_sql IS NULL THEN
      RAISE EXCEPTION 'Product fields required' USING ERRCODE = '22023';
    END IF;
    EXECUTE format(
      'INSERT INTO public.products (%s) SELECT %s FROM jsonb_populate_record(NULL::public.products, $1) RETURNING *',
      columns_sql, columns_sql
    ) INTO after_row USING product_data;
  ELSIF operation_param = 'UPDATE' THEN
    IF columns_sql IS NULL THEN
      UPDATE public.products SET updated_at = now() WHERE id = product_id RETURNING * INTO after_row;
    ELSE
      EXECUTE format(
        'UPDATE public.products SET (%s) = (SELECT %s FROM jsonb_populate_record(NULL::public.products, $1)) WHERE id = $2 RETURNING *',
        columns_sql, columns_sql
      ) INTO after_row USING product_data, product_id;
    END IF;
  ELSE
    DELETE FROM public.products WHERE id = product_id;
  END IF;

  IF sessions IS NOT NULL AND operation_param <> 'DELETE' THEN
    FOR session_json IN SELECT value FROM jsonb_array_elements(sessions) LOOP
      sid := coalesce((session_json->>'id')::uuid, gen_random_uuid());
      IF sid = ANY(kept_sessions) THEN RAISE EXCEPTION 'Duplicate session' USING ERRCODE = '23514'; END IF;
      kept_sessions := array_append(kept_sessions, sid);
      IF jsonb_typeof(session_json->'tiers') IS DISTINCT FROM 'array'
        OR jsonb_array_length(session_json->'tiers') NOT BETWEEN 1 AND 50
        OR NOT EXISTS (SELECT 1 FROM pg_catalog.pg_timezone_names WHERE name=coalesce(session_json->>'timezone','Europe/Warsaw')) THEN
        RAISE EXCEPTION 'Invalid session or tiers' USING ERRCODE = '23514';
      END IF;
      INSERT INTO public.product_sessions(id, product_id, starts_at, ends_at, timezone, title, venue, online_url, extra_days, capacity, sales_open, sort)
      VALUES(sid, after_row.id, (session_json->>'starts_at')::timestamptz, (session_json->>'ends_at')::timestamptz,
        coalesce(session_json->>'timezone','Europe/Warsaw'), session_json->>'title', session_json->>'venue', session_json->>'online_url',
        session_json->>'extra_days', (session_json->>'capacity')::integer, coalesce((session_json->>'sales_open')::boolean,true), coalesce((session_json->>'sort')::integer,0))
      ON CONFLICT(id) DO UPDATE SET starts_at=EXCLUDED.starts_at, ends_at=EXCLUDED.ends_at, timezone=EXCLUDED.timezone,
        title=EXCLUDED.title, venue=EXCLUDED.venue, online_url=EXCLUDED.online_url, extra_days=EXCLUDED.extra_days,
        capacity=EXCLUDED.capacity, sales_open=EXCLUDED.sales_open, sort=EXCLUDED.sort
      WHERE product_sessions.product_id=after_row.id;
      IF NOT FOUND THEN RAISE EXCEPTION 'Invalid session ID' USING ERRCODE='23514'; END IF;
      UPDATE public.product_price_tiers SET sort=-sort-1 WHERE session_id=sid;
      kept_tiers := '{}';
      FOR tier_json IN SELECT value FROM jsonb_array_elements(session_json->'tiers') LOOP
        tid := coalesce((tier_json->>'id')::uuid,gen_random_uuid());
        IF tid = ANY(kept_tiers) OR (tier_json->>'sort')::integer < 0 THEN RAISE EXCEPTION 'Invalid tier' USING ERRCODE='23514'; END IF;
        kept_tiers := array_append(kept_tiers,tid);
        INSERT INTO public.product_price_tiers(id,session_id,label,price,seats,sale_ends_at,sort)
        VALUES(tid,sid,tier_json->>'label',(tier_json->>'price')::numeric,(tier_json->>'seats')::integer,
          (tier_json->>'sale_ends_at')::timestamptz,(tier_json->>'sort')::integer)
        ON CONFLICT(id) DO UPDATE SET label=EXCLUDED.label,price=EXCLUDED.price,seats=EXCLUDED.seats,sale_ends_at=EXCLUDED.sale_ends_at,sort=EXCLUDED.sort
        WHERE product_price_tiers.session_id=sid;
        IF NOT FOUND THEN RAISE EXCEPTION 'Invalid tier ID' USING ERRCODE='23514'; END IF;
      END LOOP;
      DELETE FROM public.product_price_tiers WHERE session_id=sid AND NOT(id=ANY(kept_tiers));
    END LOOP;
    DELETE FROM public.product_sessions WHERE product_sessions.product_id=after_row.id AND NOT(id=ANY(kept_sessions));
  END IF;

  INSERT INTO public.audit_log (table_name, operation, old_values, new_values, user_id, performed_by)
  VALUES (
    'products', operation_param,
    CASE WHEN operation_param <> 'INSERT' THEN to_jsonb(before_row) || CASE WHEN sessions IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('sessions',before_sessions) END END,
    CASE WHEN operation_param <> 'DELETE' THEN to_jsonb(after_row) || CASE WHEN sessions IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('sessions',sessions) END END,
    actor_id, actor_id
  );
  RETURN NEXT CASE WHEN operation_param = 'DELETE' THEN before_row ELSE after_row END;
END;
$_$;


ALTER FUNCTION public.mutate_product_with_audit(operation_param text, product_data jsonb, product_id uuid, actor_id uuid) OWNER TO postgres;

--
-- Name: mutate_storefront_config(bigint, text, jsonb, bigint, uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mutate_storefront_config(expected_revision bigint, operation text, validated_config jsonb, restored_from bigint DEFAULT NULL::bigint, actor_user_id uuid DEFAULT NULL::uuid, actor_method text DEFAULT NULL::text, actor_api_key_id uuid DEFAULT NULL::uuid, legacy_source jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  current_config public.storefront_config%ROWTYPE;
  next_draft jsonb; next_published jsonb; owner_id uuid; key_record public.api_keys%ROWTYPE;
  required_scope text; candidate jsonb;
BEGIN
  IF (SELECT auth.role()) IS DISTINCT FROM 'service_role' THEN RETURN jsonb_build_object('success',false,'code','FORBIDDEN'); END IF;
  SELECT * INTO current_config FROM public.storefront_config WHERE id=true FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'code','UNAVAILABLE'); END IF;
  SELECT id INTO owner_id FROM public.admin_users WHERE user_id=actor_user_id FOR SHARE;
  IF actor_user_id IS NULL OR owner_id IS NULL OR actor_method IS NULL OR actor_method NOT IN ('session','api_key') OR
    (actor_method='session' AND actor_api_key_id IS NOT NULL) THEN
    RETURN jsonb_build_object('success',false,'code','FORBIDDEN');
  END IF;
  required_scope := CASE WHEN operation IN ('publish','rollback') THEN 'templates:activate' ELSE 'templates:write' END;
  IF actor_method='api_key' THEN
    SELECT * INTO key_record FROM public.api_keys WHERE id=actor_api_key_id FOR SHARE;
    IF NOT FOUND OR key_record.admin_user_id IS DISTINCT FROM owner_id OR key_record.revoked_at IS NOT NULL OR
      (NOT key_record.is_active AND (key_record.rotation_grace_until IS NULL OR key_record.rotation_grace_until <= clock_timestamp())) OR
      (key_record.expires_at IS NOT NULL AND key_record.expires_at <= clock_timestamp()) OR
      NOT (key_record.scopes @> jsonb_build_array(required_scope)) THEN
      RETURN jsonb_build_object('success',false,'code','FORBIDDEN');
    END IF;
  END IF;
  IF expected_revision IS NULL OR expected_revision NOT BETWEEN 0 AND 9007199254740991 OR
    (restored_from IS NOT NULL AND restored_from NOT BETWEEN 0 AND 9007199254740991) THEN
    RETURN jsonb_build_object('success',false,'code','LIMIT','path','/expectedRevision','limit',9007199254740991);
  END IF;
  IF expected_revision <> current_config.revision THEN
    RETURN jsonb_build_object('success',false,'code','CONFLICT','currentRevision',current_config.revision);
  END IF;
  IF current_config.revision=9007199254740991 THEN RETURN jsonb_build_object('success',false,'code','LIMIT','path','/expectedRevision','limit',9007199254740991); END IF;
  IF operation IS NULL OR operation NOT IN ('draft','reset','legacy-import','publish','rollback') OR
    (operation <> 'rollback' AND restored_from IS NOT NULL) THEN
    RETURN jsonb_build_object('success',false,'code','INVALID');
  END IF;
  IF operation='legacy-import' THEN
    IF legacy_source IS NULL OR jsonb_typeof(legacy_source) IS DISTINCT FROM 'object' OR
      NOT (legacy_source ?& ARRAY['sha256','byteLength']) OR
      (legacy_source - 'sha256' - 'byteLength') <> '{}'::jsonb OR
      jsonb_typeof(legacy_source->'sha256') IS DISTINCT FROM 'string' OR
      (legacy_source->>'sha256') !~ '^[a-f0-9]{64}$' OR
      jsonb_typeof(legacy_source->'byteLength') IS DISTINCT FROM 'number' THEN
      RETURN jsonb_build_object('success',false,'code','INVALID');
    END IF;
    IF (legacy_source->>'byteLength')::numeric NOT BETWEEN 0 AND 102400 OR
      trunc((legacy_source->>'byteLength')::numeric) <> (legacy_source->>'byteLength')::numeric THEN
      RETURN jsonb_build_object('success',false,'code','INVALID');
    END IF;
  ELSIF legacy_source IS NOT NULL THEN
    RETURN jsonb_build_object('success',false,'code','INVALID');
  END IF;
  next_draft := current_config.draft; next_published := current_config.published;
  IF operation IN ('draft','reset','legacy-import') THEN
    next_draft := validated_config; candidate := validated_config;
  ELSIF operation='publish' THEN
    IF validated_config IS NOT NULL OR current_config.draft IS NULL THEN RETURN jsonb_build_object('success',false,'code','INVALID'); END IF;
    next_published := current_config.draft; next_draft := NULL; candidate := next_published;
  ELSE
    IF validated_config IS NOT NULL OR restored_from IS NULL THEN RETURN jsonb_build_object('success',false,'code','INVALID'); END IF;
    SELECT h.published INTO next_published FROM public.storefront_config_history h WHERE h.revision=mutate_storefront_config.restored_from;
    IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'code','NOT_FOUND'); END IF;
    next_draft := NULL; candidate := next_published;
  END IF;
  IF public.storefront_config_stored_bytes(candidate) > 102400 OR public.storefront_config_stored_bytes(next_published) > 102400 THEN
    RETURN jsonb_build_object('success',false,'code','LIMIT','path','/config','limit',102400);
  END IF;
  IF candidate IS NULL OR public.storefront_config_valid(candidate) IS DISTINCT FROM true OR
    (operation IN ('publish','rollback') AND public.storefront_config_valid(next_published) IS DISTINCT FROM true) THEN
    RETURN jsonb_build_object('success',false,'code','INVALID');
  END IF;
  UPDATE public.storefront_config SET revision=current_config.revision+1, draft=next_draft, published=next_published,
    updated_at=clock_timestamp(), updated_by=actor_user_id WHERE id=true;
  INSERT INTO public.storefront_config_history(revision,operation,draft,published,actor_id,restored_from)
  VALUES(current_config.revision+1,operation,next_draft,next_published,actor_user_id,restored_from);
  INSERT INTO public.audit_log(table_name,operation,user_id,performed_by,new_values)
  VALUES('storefront_config','UPDATE',actor_user_id,actor_user_id,jsonb_build_object(
    'revision',current_config.revision+1,'templateId',candidate->>'templateId','action',operation,
    'scope',required_scope,'actor_method',actor_method,'actor_api_key_id',actor_api_key_id) ||
    CASE WHEN operation='legacy-import' THEN jsonb_build_object('legacySource',legacy_source) ELSE '{}'::jsonb END);
  RETURN jsonb_build_object('success',true,'revision',current_config.revision+1);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success',false,'code','UNAVAILABLE');
END;
$_$;


ALTER FUNCTION public.mutate_storefront_config(expected_revision bigint, operation text, validated_config jsonb, restored_from bigint, actor_user_id uuid, actor_method text, actor_api_key_id uuid, legacy_source jsonb) OWNER TO postgres;

--
-- Name: my_event_sessions(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.my_event_sessions(p_product_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT public.check_rate_limit('my_event_sessions',1000,3600) THEN RETURN '[]'::jsonb; END IF;
  RETURN (SELECT coalesce(jsonb_agg(DISTINCT jsonb_build_object('id',s.id,'starts_at',s.starts_at,'timezone',s.timezone,'title',s.title,'online_url',s.online_url)), '[]')
    FROM public.product_sessions s JOIN public.seat_reservations r ON r.session_id=s.id
    JOIN public.payment_transactions t ON t.id=r.transaction_id
    WHERE (r.status='confirmed' OR (r.status='held' AND r.expires_at IS NULL AND t.status='awaiting_payment' AND t.metadata->>'access_on_placement'='true'))
    AND s.product_id=p_product_id AND EXISTS (SELECT 1 FROM public.user_product_access a WHERE a.product_id=p_product_id AND a.user_id=auth.uid() AND (a.access_expires_at IS NULL OR a.access_expires_at>now()))
    AND (t.user_id=auth.uid() OR lower(t.customer_email)=(SELECT lower(email) FROM auth.users WHERE id=auth.uid())
      OR EXISTS (SELECT 1 FROM jsonb_array_elements(coalesce(t.order_details->'participants'->'people','[]')) p WHERE lower(p->>'email')=(SELECT lower(email) FROM auth.users WHERE id=auth.uid()))));
END $$;


ALTER FUNCTION public.my_event_sessions(p_product_id uuid) OWNER TO postgres;

--
-- Name: normalize_purchase_contact(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.normalize_purchase_contact() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_TABLE_NAME='issued_licenses' THEN NEW.email:=lower(btrim(NEW.email));
  ELSE NEW.customer_email:=lower(btrim(NEW.customer_email)); END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.normalize_purchase_contact() OWNER TO postgres;

--
-- Name: observe_payment_refund(uuid, text, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.observe_payment_refund(p_transaction_id uuid, p_refund_id text, p_amount integer, p_currency text, p_status text, p_initial_status text DEFAULT NULL::text) RETURNS TABLE(refund_version integer, previous_status text, notified_version integer, refund_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_refund public.payment_refunds%ROWTYPE;
BEGIN
  INSERT INTO public.payment_refunds(stripe_refund_id,transaction_id,amount,currency,status)
  VALUES(p_refund_id,p_transaction_id,p_amount,upper(p_currency),coalesce(p_initial_status,p_status))
  ON CONFLICT (stripe_refund_id) DO NOTHING;
  SELECT * INTO STRICT v_refund FROM public.payment_refunds WHERE stripe_refund_id=p_refund_id FOR UPDATE;
  IF v_refund.transaction_id<>p_transaction_id OR v_refund.amount<>p_amount OR v_refund.currency<>upper(p_currency) THEN
    RAISE EXCEPTION 'Refund binding does not match';
  END IF;
  INSERT INTO public.payment_refund_events(stripe_refund_id,version,status,previous_status)
  VALUES(p_refund_id,v_refund.version,v_refund.status,v_refund.previous_status) ON CONFLICT DO NOTHING;
  IF v_refund.status IS DISTINCT FROM p_status THEN
    UPDATE public.payment_refunds SET previous_status=v_refund.status,status=p_status,
      version=version+1,updated_at=now() WHERE stripe_refund_id=p_refund_id RETURNING * INTO v_refund;
    INSERT INTO public.payment_refund_events(stripe_refund_id,version,status,previous_status)
    VALUES(p_refund_id,v_refund.version,v_refund.status,v_refund.previous_status);
  END IF;
  RETURN QUERY SELECT e.version,e.previous_status,0,e.status FROM public.payment_refund_events e
    WHERE e.stripe_refund_id=p_refund_id AND NOT e.notified ORDER BY e.version;
  IF NOT FOUND THEN
    RETURN QUERY SELECT v_refund.version,v_refund.previous_status,v_refund.notified_version,v_refund.status;
  END IF;
END;
$$;


ALTER FUNCTION public.observe_payment_refund(p_transaction_id uuid, p_refund_id text, p_amount integer, p_currency text, p_status text, p_initial_status text) OWNER TO postgres;

--
-- Name: open_order_payment_attempt(uuid, text, numeric, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.open_order_payment_attempt(p_id uuid, p_kind text, p_amount numeric, p_currency text, p_expires_at timestamp with time zone, p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE tx public.payment_transactions%ROWTYPE; a public.order_payment_attempts%ROWTYPE;
BEGIN
  IF p_now IS NULL OR p_expires_at IS NULL OR p_expires_at<=p_now OR p_kind IS DISTINCT FROM 'settle' THEN
    RAISE EXCEPTION 'Invalid attempt' USING ERRCODE='22023'; END IF;
  SELECT * INTO tx FROM public.payment_transactions WHERE id=p_id FOR UPDATE;
  IF NOT FOUND OR tx.payment_provider<>'bank_transfer' OR tx.status<>'awaiting_payment'
    OR p_amount IS DISTINCT FROM tx.amount OR upper(p_currency)<>upper(tx.currency) THEN
    RAISE EXCEPTION 'Order not payable' USING ERRCODE='22023'; END IF;
  UPDATE public.order_payment_attempts SET status='expired' WHERE transaction_id=p_id AND status IN ('opening','open') AND expires_at<=p_now;
  SELECT * INTO a FROM public.order_payment_attempts WHERE transaction_id=p_id AND status IN ('opening','open');
  IF FOUND THEN RETURN to_jsonb(a)||'{"reused":true}'; END IF;
  -- Past the reservation deadline the order waits for the release job; no new attempt may extend it.
  IF tx.release_at IS NOT NULL AND p_now>=tx.release_at THEN RAISE EXCEPTION 'Payment window closed' USING ERRCODE='22023'; END IF;
  INSERT INTO public.order_payment_attempts(transaction_id,kind,amount,currency,expires_at) VALUES(p_id,p_kind,p_amount,upper(p_currency),p_expires_at) RETURNING * INTO a;
  RETURN to_jsonb(a)||'{"reused":false}';
END $$;


ALTER FUNCTION public.open_order_payment_attempt(p_id uuid, p_kind text, p_amount numeric, p_currency text, p_expires_at timestamp with time zone, p_now timestamp with time zone) OWNER TO postgres;

--
-- Name: order_access_expiry(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.order_access_expiry(p_transaction_id uuid, p_user_id uuid, p_product_id uuid) RETURNS timestamp with time zone
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT CASE WHEN t.access_terms ? (p_user_id::text || ':' || p_product_id::text)
    THEN (t.access_terms->(p_user_id::text || ':' || p_product_id::text)->>'expiresAt')::timestamptz
    ELSE CASE WHEN nullif(coalesce(l.access_duration_override, p.auto_grant_duration_days), 0) IS NULL THEN NULL
      ELSE coalesce(g.claimed_at, CASE WHEN coalesce((t.metadata->>'access_on_placement')::boolean, false) THEN t.created_at ELSE t.paid_at END, t.created_at)
        + make_interval(days => coalesce(l.access_duration_override, p.auto_grant_duration_days)) END END
  FROM public.payment_transactions t JOIN public.products p ON p.id = p_product_id
  LEFT JOIN LATERAL (SELECT li.access_duration_override FROM public.payment_line_items li
    WHERE li.transaction_id = t.id AND li.product_id = p_product_id AND li.item_type = 'order_bump' LIMIT 1) l ON true
  LEFT JOIN LATERAL (SELECT gp.claimed_at FROM public.guest_purchases gp
    WHERE gp.claimed_by_user_id = p_user_id AND (gp.transaction_id = t.id OR (gp.transaction_id IS NULL AND gp.session_id = t.session_id))
    ORDER BY gp.claimed_at LIMIT 1) g ON true
  WHERE t.id = p_transaction_id;
$$;


ALTER FUNCTION public.order_access_expiry(p_transaction_id uuid, p_user_id uuid, p_product_id uuid) OWNER TO postgres;

--
-- Name: order_awaits_participants(jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.order_awaits_participants(p_order_details jsonb, p_profile jsonb, p_status text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT p_status = 'completed'
    AND jsonb_typeof(p_profile->'modules') = 'array'
    AND EXISTS (SELECT 1 FROM jsonb_array_elements(p_profile->'modules') m
      WHERE m->>'id' = 'participants' AND m->'required' = 'true'::jsonb AND m->'allow_later' = 'true'::jsonb)
    AND coalesce(jsonb_array_length(p_order_details->'participants'->'people'), 0) = 0
    AND coalesce((p_order_details->'quantity'->>'value')::integer, 1) >= 1;
$$;


ALTER FUNCTION public.order_awaits_participants(p_order_details jsonb, p_profile jsonb, p_status text) OWNER TO postgres;

--
-- Name: order_granted_components(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.order_granted_components(p_transaction_id uuid) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT component_product_id FROM public.order_bundle_components WHERE transaction_id = p_transaction_id
  UNION
  SELECT b.component_product_id FROM public.payment_transactions t
  JOIN public.bundle_items b ON b.bundle_product_id = t.product_id
  WHERE t.id = p_transaction_id
    AND t.bundle_components_recorded_at IS NULL;
$$;


