--
-- Name: pending_free_grant_products(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pending_free_grant_products() RETURNS TABLE(product_id uuid, slug text, request_id uuid, custom_field_values jsonb)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
 WITH owner AS (SELECT lower(email) AS email FROM auth.users WHERE id=(select auth.uid()) AND email_confirmed_at IS NOT NULL),
 intents AS (SELECT l.product_id FROM public.legacy_pending_free_grant_products() l
  UNION SELECT c.product_id FROM public.free_grant_contexts c,owner u WHERE c.email=u.email AND c.claimed_at IS NULL AND c.expires_at>now())
 SELECT p.id,p.slug,c.id,c.custom_field_values FROM intents i JOIN public.products p ON p.id=i.product_id CROSS JOIN owner u
 LEFT JOIN LATERAL(SELECT * FROM public.free_grant_contexts c WHERE c.email=u.email AND c.product_id=p.id AND c.claimed_at IS NULL AND c.expires_at>now() ORDER BY created_at DESC LIMIT 1)c ON true
 WHERE public.is_free_claimable_product(p.id) AND NOT EXISTS(SELECT 1 FROM public.user_product_access a WHERE a.user_id=(select auth.uid()) AND a.product_id=p.id AND (a.access_expires_at IS NULL OR a.access_expires_at>now()));
$$;


ALTER FUNCTION public.pending_free_grant_products() OWNER TO postgres;

--
-- Name: pick_due_webhook_deliveries(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pick_due_webhook_deliveries(p_limit integer) RETURNS TABLE(id uuid, endpoint_id uuid, event_type text, payload jsonb, attempt_count integer, max_attempts integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  lease_until timestamptz := NOW() + interval '60 seconds';
BEGIN
  RETURN QUERY
  WITH due AS (
    SELECT wl.id
    FROM public.webhook_logs wl
    WHERE wl.status = 'pending_retry'
      AND wl.next_retry_at IS NOT NULL
      AND wl.next_retry_at <= NOW()
    ORDER BY wl.next_retry_at ASC
    LIMIT p_limit
    FOR UPDATE SKIP LOCKED
  ),
  leased AS (
    UPDATE public.webhook_logs wl
    SET next_retry_at = lease_until
    FROM due
    WHERE wl.id = due.id
    RETURNING wl.id, wl.endpoint_id, wl.event_type, wl.payload, wl.attempt_count, wl.max_attempts
  )
  SELECT leased.id, leased.endpoint_id, leased.event_type, leased.payload, leased.attempt_count, leased.max_attempts
  FROM leased;
END;
$$;


ALTER FUNCTION public.pick_due_webhook_deliveries(p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION pick_due_webhook_deliveries(p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.pick_due_webhook_deliveries(p_limit integer) IS 'Atomically claims due retries with FOR UPDATE SKIP LOCKED + 60s lease';


--
-- Name: place_order(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.place_order(p_order jsonb, p_lines jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  event boolean; sid uuid; selected jsonb; tier jsonb; main jsonb; result jsonb;
  deadline timestamptz; q integer; txid uuid;
BEGIN
  SELECT event_mode INTO event FROM public.products WHERE id=(p_order->>'product_id')::uuid FOR SHARE;
  IF NOT coalesce(event,false) THEN RETURN public._place_order_without_event(p_order,p_lines); END IF;
  SELECT value INTO main FROM jsonb_array_elements(p_lines) WHERE value->>'item_type'='main_product';
  sid := (main->>'session_id')::uuid; q := (main->>'quantity')::integer;
  IF sid IS NULL OR q IS NULL OR q NOT BETWEEN 1 AND 100 OR coalesce(p_order->>'customer_email','')='' THEN
    RAISE EXCEPTION 'Invalid event order' USING ERRCODE='22023';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(sid::text, 0));
  IF NOT public.event_hold_limits(sid,p_order->>'customer_email',p_order->'metadata'->>'event_ip') THEN
    RAISE EXCEPTION 'event_hold_limit' USING ERRCODE='P0429';
  END IF;
  SELECT value INTO selected FROM jsonb_array_elements(public.event_availability((p_order->>'product_id')::uuid))
    WHERE value->>'id'=sid::text;
  tier := selected->'current_tier';
  IF tier IS NULL OR tier='null'::jsonb OR (selected->>'remaining')::integer < q
    OR (tier->>'seats_left')::integer < q THEN RAISE EXCEPTION 'sold_out' USING ERRCODE='P0409'; END IF;
  IF (main->>'unit_price')::numeric IS DISTINCT FROM (tier->>'price')::numeric THEN
    RAISE EXCEPTION 'event_price_changed' USING ERRCODE='P0409';
  END IF;
  deadline := coalesce((p_order->>'expires_at')::timestamptz, now()+interval '30 minutes');
  IF deadline <= now() OR deadline > now()+interval '31 minutes' THEN RAISE EXCEPTION 'Invalid event expiry'; END IF;
  IF p_order->>'payment_provider'='bank_transfer' THEN deadline:=NULL; END IF;
  p_order := jsonb_set(p_order,'{expires_at}',coalesce(to_jsonb(deadline),'null'::jsonb));
  result := public._place_order_without_event(p_order,p_lines); txid := (result->>'transaction_id')::uuid;
  UPDATE public.payment_line_items SET session_id=sid, tier_id=(tier->>'id')::uuid,
    session_label=selected->>'title', session_starts_at=(selected->>'starts_at')::timestamptz
    WHERE transaction_id=txid AND item_type='main_product';
  INSERT INTO public.seat_reservations(session_id,tier_id,transaction_id,quantity,status,expires_at)
    VALUES (sid,(tier->>'id')::uuid,txid,q,'held',deadline);
  RETURN result;
END $$;


ALTER FUNCTION public.place_order(p_order jsonb, p_lines jsonb) OWNER TO postgres;

--
-- Name: prepare_event_mail(text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prepare_event_mail(p_email text, p_data jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
BEGIN
  IF length(p_data->>'event_date')>500 OR length(p_data->>'event_online_url')>2048
    OR (p_data->>'event_online_url') !~ '^https://[^[:space:]]+$'
    OR length(p_data->>'transfer_text')>2000 OR length(p_data->>'purchase_product')>500
    OR length(p_data->>'purchase_amount')>100 OR (p_data->>'locale') NOT IN ('pl','en')
    OR (p_data->>'mail_kind') NOT IN ('transfer_placed','payment_reminder','order_cancelled','participants_needed')
    OR length(p_data->>'pay_url')>2048
    OR (p_data->>'pay_url') !~ '^https?://[^/[:space:]]+/(pl|en)/order/[0-9a-f-]{36}/transfer\?token=[0-9]{1,12}\.[A-Za-z0-9_-]{43}$'
    OR length(p_data->>'participants_url')>2048
    OR (p_data->>'participants_url') !~ '^https?://[^/[:space:]]+/(pl|en)/order/[0-9a-f-]{36}/participants\?token=[0-9]{1,12}\.[A-Za-z0-9_-]{43}$'
    OR (p_data ? 'access_on_placement' AND p_data->>'access_on_placement' NOT IN ('true','false'))
    OR length(p_data->>'release_text')>500
    OR length(p_data->>'cancel_reason_text')>2000 OR length(p_data->>'license_expires_text')>100
    OR length(p_data->>'license_expires_at')>50
    OR (p_data ? 'license_keys' AND (jsonb_typeof(p_data->'license_keys') <> 'object'
      OR octet_length((p_data->'license_keys')::text)>65536
      OR EXISTS (SELECT 1 FROM jsonb_each_text(p_data->'license_keys') e
        WHERE length(e.key)>500 OR length(e.value)>4096 OR e.value !~ '^[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$')))
    OR length(p_data->>'license_key')>4096 OR (p_data->>'license_key') !~ '^[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$'
    OR (p_data ? 'payment_received' AND (p_data->>'payment_received') <> 'true')
    OR (p_data ? 'transfer' AND (jsonb_typeof(p_data->'transfer') <> 'object'
      OR octet_length((p_data->'transfer')::text)>2000
      OR EXISTS (SELECT 1 FROM jsonb_each(p_data->'transfer') e
        WHERE jsonb_typeof(e.value) <> 'string' OR e.key NOT IN ('holder','account','bank','title','amount','due'))))
    THEN RAISE EXCEPTION 'Invalid mail data' USING ERRCODE='22023'; END IF;
  UPDATE auth.users SET raw_user_meta_data=(coalesce(raw_user_meta_data,'{}')
    -'event_date'-'event_online_url'-'transfer_text'-'transfer'-'purchase_product'-'purchase_amount'-'locale'
    -'cancel_reason_text'-'license_expires_at'-'license_expires_text'
    -'access_on_placement'-'mail_kind'-'pay_url'-'release_text'-'participants_url'-'license_keys'-'license_key'-'payment_received')
    ||jsonb_strip_nulls(jsonb_build_object('event_date',p_data->>'event_date',
      'event_online_url',p_data->>'event_online_url','transfer_text',p_data->>'transfer_text','transfer',p_data->'transfer',
      'purchase_product',p_data->>'purchase_product','purchase_amount',p_data->>'purchase_amount',
      'access_on_placement',p_data->>'access_on_placement',
      'mail_kind',p_data->>'mail_kind','pay_url',p_data->>'pay_url','release_text',p_data->>'release_text',
      'license_keys',p_data->'license_keys','participants_url',p_data->>'participants_url','license_key',p_data->>'license_key',
      'payment_received',p_data->>'payment_received',
      'cancel_reason_text',p_data->>'cancel_reason_text','license_expires_at',p_data->>'license_expires_at',
      'license_expires_text',p_data->>'license_expires_text',
      'locale',coalesce(p_data->>'locale','en')))
    WHERE lower(email)=lower(p_email);
END $_$;


ALTER FUNCTION public.prepare_event_mail(p_email text, p_data jsonb) OWNER TO postgres;

--
-- Name: prepare_free_grant(text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prepare_free_grant(p_email text, p_product_id uuid, p_values jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE result uuid;
BEGIN
 IF (select auth.role()) IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Service role required' USING ERRCODE='42501'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.products WHERE id=p_product_id AND is_active) THEN RAISE EXCEPTION 'Product unavailable'; END IF;
 DELETE FROM public.free_grant_contexts WHERE email=lower(trim(p_email)) AND expires_at<now();
 IF (SELECT count(DISTINCT product_id) FROM public.free_grant_contexts WHERE email=lower(trim(p_email)) AND claimed_at IS NULL)>=20 AND NOT EXISTS(SELECT 1 FROM public.free_grant_contexts WHERE email=lower(trim(p_email)) AND product_id=p_product_id AND claimed_at IS NULL) THEN RAISE EXCEPTION 'Too many pending products'; END IF;
 INSERT INTO public.free_grant_contexts(email,product_id,custom_field_values) VALUES(lower(trim(p_email)),p_product_id,p_values) RETURNING id INTO result;
 RETURN result;
END $$;


ALTER FUNCTION public.prepare_free_grant(p_email text, p_product_id uuid, p_values jsonb) OWNER TO postgres;

--
-- Name: prevent_delete_user_with_active_subscription(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prevent_delete_user_with_active_subscription() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.subscriptions
    WHERE user_id = OLD.id
      AND status IN ('trialing', 'active', 'past_due', 'incomplete')
  ) THEN
    RAISE EXCEPTION 'Cannot delete user: an active Stripe subscription exists for this account. Cancel it in Stripe first, then delete the account.';
  END IF;
  RETURN OLD;
END;
$$;


ALTER FUNCTION public.prevent_delete_user_with_active_subscription() OWNER TO postgres;

--
-- Name: process_refund_request(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.process_refund_request(request_id_param uuid, action_param text, admin_response_param text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '10s'
    AS $$
DECLARE
    current_admin_id UUID;
    request_record RECORD;
BEGIN
    current_admin_id := auth.uid();

    -- Check admin permission
    IF NOT (select public.is_admin()) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Admin privileges required');
    END IF;

    IF action_param NOT IN ('approve', 'reject') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Invalid action. Must be "approve" or "reject"');
    END IF;

    -- Get request details
    SELECT rr.*, pt.stripe_payment_intent_id, p.name as product_name
    INTO request_record
    FROM public.refund_requests rr
    JOIN public.payment_transactions pt ON rr.transaction_id = pt.id
    JOIN public.products p ON rr.product_id = p.id
    WHERE rr.id = request_id_param;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Refund request not found');
    END IF;

    IF request_record.status != 'pending' THEN
        RETURN jsonb_build_object('success', false, 'error', 'Request already processed', 'current_status', request_record.status);
    END IF;

    -- Update request status
    UPDATE public.refund_requests
    SET
        status = CASE WHEN action_param = 'approve' THEN 'approved' ELSE 'rejected' END,
        admin_id = current_admin_id,
        admin_response = admin_response_param,
        processed_at = NOW(),
        updated_at = NOW()
    WHERE id = request_id_param;

    IF action_param = 'approve' THEN
        RETURN jsonb_build_object(
            'success', true,
            'status', 'approved',
            'message', 'Refund request approved. Process refund via Stripe.',
            'transaction_id', request_record.transaction_id,
            'stripe_payment_intent_id', request_record.stripe_payment_intent_id,
            'amount', request_record.requested_amount,
            'currency', request_record.currency
        );
    ELSE
        RETURN jsonb_build_object(
            'success', true,
            'status', 'rejected',
            'message', 'Refund request rejected',
            'admin_response', admin_response_param
        );
    END IF;
END;
$$;


ALTER FUNCTION public.process_refund_request(request_id_param uuid, action_param text, admin_response_param text) OWNER TO postgres;

--
-- Name: FUNCTION process_refund_request(request_id_param uuid, action_param text, admin_response_param text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.process_refund_request(request_id_param uuid, action_param text, admin_response_param text) IS '@graphql({"include": false})';


--
-- Name: process_stripe_payment_completion_with_bump(text, uuid, text, numeric, text, text, uuid, uuid[], uuid, numeric, boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.process_stripe_payment_completion_with_bump(session_id_param text, product_id_param uuid, customer_email_param text, amount_total numeric, currency_param text, stripe_payment_intent_id text DEFAULT NULL::text, user_id_param uuid DEFAULT NULL::uuid, bump_product_ids_param uuid[] DEFAULT NULL::uuid[], coupon_id_param uuid DEFAULT NULL::uuid, amount_subtotal_param numeric DEFAULT NULL::numeric, allow_inactive_product_param boolean DEFAULT false, cart_version_param integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  pi_param text := stripe_payment_intent_id;
  tx public.payment_transactions%ROWTYPE;
  result jsonb;
  full_bumps uuid[];
BEGIN
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(coalesce(pi_param, session_id_param)));
  SELECT pt.* INTO tx FROM public.payment_transactions pt
    WHERE pt.session_id = session_id_param OR (pi_param IS NOT NULL AND pt.stripe_payment_intent_id = pi_param)
    ORDER BY (pt.session_id = session_id_param) DESC LIMIT 1 FOR UPDATE;

  IF tx.id IS NOT NULL THEN
    IF tx.payment_provider <> 'stripe'
       OR tx.product_id IS DISTINCT FROM product_id_param
       OR upper(tx.currency) IS DISTINCT FROM upper(currency_param)
       OR (tx.stripe_payment_intent_id IS NOT NULL AND tx.stripe_payment_intent_id IS DISTINCT FROM pi_param)
       OR (tx.session_id LIKE 'cs_%' AND session_id_param LIKE 'cs_%' AND tx.session_id <> session_id_param)
       OR tx.status NOT IN ('pending', 'abandoned', 'completed')
       OR (tx.status = 'completed' AND (tx.amount IS DISTINCT FROM amount_total OR lower(tx.customer_email) IS DISTINCT FROM lower(trim(customer_email_param))))
    THEN
      RETURN jsonb_build_object('success', false, 'error', 'Order details do not match', 'error_kind', 'data');
    END IF;
    IF EXISTS (SELECT 1 FROM public.payment_transactions pt
      WHERE pt.id <> tx.id AND (pt.session_id = session_id_param OR pt.stripe_payment_intent_id = pi_param)) THEN
      RETURN jsonb_build_object('success', false, 'error', 'Order records need review', 'error_kind', 'data');
    END IF;
    -- The cart Stripe charged (no version in the session metadata = the cart the order was placed with).
    IF tx.status IN ('pending', 'abandoned') AND EXISTS (SELECT 1 FROM public.checkout_cart_versions v
      WHERE v.transaction_id = tx.id AND v.version = coalesce(cart_version_param, 1)) THEN
      PERFORM public._apply_cart_version(tx.id, coalesce(cart_version_param, 1));
      SELECT pt.* INTO tx FROM public.payment_transactions pt WHERE pt.id = tx.id;
    END IF;
    IF tx.session_id LIKE 'cs_%' THEN session_id_param := tx.session_id; END IF;
    IF jsonb_typeof(tx.metadata->'bump_product_ids_full') = 'array' THEN
      SELECT array_agg(value::uuid) INTO full_bumps
        FROM jsonb_array_elements_text(tx.metadata->'bump_product_ids_full');
      IF coalesce(cardinality(full_bumps), 0) > coalesce(cardinality(bump_product_ids_param), 0) THEN
        bump_product_ids_param := full_bumps;
      END IF;
    END IF;
  END IF;

  -- Attach the order and complete it within one savepoint.
  BEGIN
    IF tx.id IS NOT NULL THEN
      UPDATE public.payment_transactions SET
        stripe_payment_intent_id = coalesce(pi_param, tx.stripe_payment_intent_id),
        session_id = session_id_param,
        status = CASE WHEN status = 'abandoned' THEN 'pending' ELSE status END,
        amount = CASE WHEN status IN ('pending', 'abandoned') THEN amount_total ELSE amount END,
        currency = upper(currency_param)
      WHERE id = tx.id;
      IF tx.session_id <> session_id_param THEN
        UPDATE public.guest_purchases SET session_id = session_id_param
        WHERE session_id = tx.session_id AND product_id = tx.product_id;
      END IF;
    END IF;
    result := public._process_stripe_payment_completion_with_bump_impl(
      session_id_param, product_id_param, lower(trim(customer_email_param)), amount_total,
      currency_param, pi_param, user_id_param, bump_product_ids_param, coupon_id_param, amount_subtotal_param,
      allow_inactive_product_param
    );
    IF NOT coalesce((result->>'success')::boolean, false) THEN
      RAISE EXCEPTION USING MESSAGE = 'Completion not accepted', DETAIL = result::text;
    END IF;
  EXCEPTION WHEN raise_exception THEN
    IF SQLERRM = 'Completion not accepted' THEN
      GET STACKED DIAGNOSTICS result = PG_EXCEPTION_DETAIL;
      RETURN result::jsonb || jsonb_build_object('error_kind', CASE WHEN result->>'error' = 'Rate limit exceeded' OR result->>'code' IN ('40001','40P01','57014') THEN 'transient' ELSE 'data' END);
    END IF;
    RAISE;
  END;

  SELECT pt.* INTO tx FROM public.payment_transactions pt WHERE pt.session_id = session_id_param;
  IF result->>'message' = 'Payment already processed (idempotent)'
     OR result->>'scenario' = 'idempotent_claimed_for_logged_in_user' THEN
    result := result || jsonb_build_object('already_had_access', true);
  END IF;
  RETURN result || jsonb_build_object('transaction_id', tx.id, 'session_id', tx.session_id,
    'bump_product_ids', coalesce(bump_product_ids_param, '{}'::uuid[]),
    'pricing_source', CASE WHEN tx.pricing_snapshot_version IS NULL THEN 'legacy' ELSE 'snapshot' END);
END;
$$;


ALTER FUNCTION public.process_stripe_payment_completion_with_bump(session_id_param text, product_id_param uuid, customer_email_param text, amount_total numeric, currency_param text, stripe_payment_intent_id text, user_id_param uuid, bump_product_ids_param uuid[], coupon_id_param uuid, amount_subtotal_param numeric, allow_inactive_product_param boolean, cart_version_param integer) OWNER TO postgres;

