--
-- Name: purchase_attribution_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.purchase_attribution_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  -- Allowed: erasing the click id (retention) and FK ON DELETE SET NULL (deleted account/product/partner).
  IF (to_jsonb(NEW) - ARRAY['click_id','click_id_expires_at','user_id','product_id','affiliate_member_id'])
       IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['click_id','click_id_expires_at','user_id','product_id','affiliate_member_id'])
     OR (NEW.click_id IS NOT NULL AND NEW.click_id IS DISTINCT FROM OLD.click_id)
     OR (NEW.user_id IS NOT NULL AND NEW.user_id IS DISTINCT FROM OLD.user_id)
     OR (NEW.product_id IS NOT NULL AND NEW.product_id IS DISTINCT FROM OLD.product_id)
     OR (NEW.affiliate_member_id IS NOT NULL AND NEW.affiliate_member_id IS DISTINCT FROM OLD.affiliate_member_id) THEN
    RAISE EXCEPTION 'purchase attribution is immutable' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.purchase_attribution_immutable() OWNER TO postgres;

--
-- Name: purge_attribution_click_ids(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.purge_attribution_click_ids() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE n integer;
BEGIN
  UPDATE public.purchase_attribution SET click_id = NULL, click_id_expires_at = NULL
    WHERE click_id IS NOT NULL AND click_id_expires_at <= now();
  GET DIAGNOSTICS n = ROW_COUNT;
  DELETE FROM public.checkout_attribution WHERE created_at < now() - interval '7 days';
  RETURN n;
END $$;


ALTER FUNCTION public.purge_attribution_click_ids() OWNER TO postgres;

--
-- Name: queue_auth_mail_retry(text, text, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.queue_auth_mail_retry(p_email text, p_redirect_to text, p_data jsonb, p_kind text, p_error text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  INSERT INTO public.auth_mail_retries(email, redirect_to, data, kind, next_attempt_at, last_error)
  VALUES (lower(btrim(p_email)), p_redirect_to, coalesce(p_data, '{}'::jsonb), p_kind, now() + interval '2 minutes', left(p_error, 40))
  ON CONFLICT (email, redirect_to) DO UPDATE SET data = CASE WHEN public.auth_mail_retries.kind='license' AND EXCLUDED.kind='post_checkout' THEN public.auth_mail_retries.data ELSE EXCLUDED.data END,
    kind = CASE WHEN public.auth_mail_retries.kind='license' THEN 'license' ELSE EXCLUDED.kind END, last_error = EXCLUDED.last_error,
    given_up_at = NULL,
    attempts = CASE WHEN public.auth_mail_retries.given_up_at IS NULL THEN public.auth_mail_retries.attempts
      WHEN public.auth_mail_retries.kind = 'post_checkout' AND EXCLUDED.kind = 'post_checkout' THEN public.auth_mail_retries.attempts
      ELSE 0 END,
    next_attempt_at = CASE WHEN public.auth_mail_retries.given_up_at IS NULL THEN public.auth_mail_retries.next_attempt_at
      ELSE greatest(public.auth_mail_retries.next_attempt_at, EXCLUDED.next_attempt_at) END;
$$;


ALTER FUNCTION public.queue_auth_mail_retry(p_email text, p_redirect_to text, p_data jsonb, p_kind text, p_error text) OWNER TO postgres;

--
-- Name: queue_pending_free_grant(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.queue_pending_free_grant(p_email text, p_product_slug text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_product_id UUID;
  v_email TEXT := lower(trim(p_email));
BEGIN
  SELECT p.id INTO v_product_id FROM public.products p WHERE p.slug = p_product_slug;
  IF v_product_id IS NULL OR NOT public.is_free_claimable_product(v_product_id) THEN
    RETURN FALSE;
  END IF;

  UPDATE auth.users u
  SET raw_app_meta_data = jsonb_set(
        COALESCE(u.raw_app_meta_data, '{}'::jsonb),
        '{pending_free_grants}',
        COALESCE(u.raw_app_meta_data -> 'pending_free_grants', '[]'::jsonb) || to_jsonb(v_product_id::TEXT)
      )
  WHERE lower(u.email) = v_email
    AND NOT (COALESCE(u.raw_app_meta_data -> 'pending_free_grants', '[]'::jsonb) ? v_product_id::TEXT)
    AND jsonb_array_length(COALESCE(u.raw_app_meta_data -> 'pending_free_grants', '[]'::jsonb)) < 20
    AND NOT EXISTS (
      SELECT 1 FROM public.user_product_access upa
      WHERE upa.user_id = u.id
        AND upa.product_id = v_product_id
        AND (upa.access_expires_at IS NULL OR upa.access_expires_at > now())
    );

  -- TRUE whenever the account now carries the intent (freshly or already).
  RETURN EXISTS (
    SELECT 1 FROM auth.users u
    WHERE lower(u.email) = v_email
      AND COALESCE(u.raw_app_meta_data -> 'pending_free_grants', '[]'::jsonb) ? v_product_id::TEXT
  );
END;
$$;


ALTER FUNCTION public.queue_pending_free_grant(p_email text, p_product_slug text) OWNER TO postgres;

--
-- Name: reconcile_refunded_subscription_access(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reconcile_refunded_subscription_access(p_transaction_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE a public.user_product_access;
BEGIN
  IF (select auth.role()) IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Service role required' USING ERRCODE = '42501';
  END IF;
  FOR a IN SELECT access.* FROM public.user_product_access access
    JOIN public.payment_transactions t ON t.subscription_id = access.subscription_id
    WHERE t.id = p_transaction_id ORDER BY access.id FOR UPDATE OF access
  LOOP
    UPDATE public.user_product_access SET subscription_id = NULL WHERE id = a.id;
    PERFORM public.revoke_order_product_access(p_transaction_id, a.user_id, a.product_id);
  END LOOP;
END $$;


ALTER FUNCTION public.reconcile_refunded_subscription_access(p_transaction_id uuid) OWNER TO postgres;

--
-- Name: record_business_event(text, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_business_event(p_event text, p_product uuid, p_payload jsonb, p_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE product jsonb;
BEGIN
  SELECT jsonb_build_object('id',p.id,'name',p.name,'slug',p.slug) INTO product FROM public.products p WHERE p.id=p_product;
  INSERT INTO public.business_events(event_type,product_id,payload,deduplication_key)
  VALUES(p_event,p_product,p_payload||jsonb_build_object(
    'product',CASE WHEN p_product IS NULL THEN NULL ELSE coalesce(product,jsonb_build_object('id',p_product)) END,
    'actor',public.business_event_actor(),'occurredAt',clock_timestamp()),p_key)
  ON CONFLICT(deduplication_key) DO NOTHING;
END $$;


ALTER FUNCTION public.record_business_event(p_event text, p_product uuid, p_payload jsonb, p_key text) OWNER TO postgres;

--
-- Name: record_free_attribution(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_free_attribution(p_product uuid, p_user uuid, p_payload jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF p_product IS NULL OR p_user IS NULL OR (p_payload IS NOT NULL AND (jsonb_typeof(p_payload) <> 'object' OR octet_length(p_payload::text) > 16384)) THEN
    RAISE EXCEPTION 'Invalid attribution payload' USING ERRCODE = '22023';
  END IF;
  PERFORM public.insert_purchase_attribution(NULL, p_product, p_user, 'free', p_payload, NULL);
END $$;


ALTER FUNCTION public.record_free_attribution(p_product uuid, p_user uuid, p_payload jsonb) OWNER TO postgres;

--
-- Name: record_free_attribution_from_ref(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_free_attribution_from_ref(p_product uuid, p_user uuid, p_ref text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE payload jsonb;
BEGIN
  IF p_product IS NULL OR p_user IS NULL OR p_ref IS NULL OR length(p_ref) > 255 THEN
    RAISE EXCEPTION 'Invalid attribution reference' USING ERRCODE = '22023';
  END IF;
  DELETE FROM public.checkout_attribution WHERE ref = p_ref RETURNING checkout_attribution.payload INTO payload;
  PERFORM public.insert_purchase_attribution(NULL, p_product, p_user, 'free', payload, NULL);
END $$;


ALTER FUNCTION public.record_free_attribution_from_ref(p_product uuid, p_user uuid, p_ref text) OWNER TO postgres;

--
-- Name: record_invoice_correction(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_invoice_correction(p_transaction uuid, p_actor uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE tx public.payment_transactions%ROWTYPE; existing public.invoices%ROWTYPE;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.admin_users WHERE user_id=p_actor) THEN
    RETURN false;
  END IF;
  SELECT * INTO tx FROM public.payment_transactions WHERE id=p_transaction FOR UPDATE;
  IF NOT FOUND OR tx.status NOT IN ('cancelled','refunded') THEN RETURN false; END IF;
  SELECT * INTO existing FROM public.invoices WHERE transaction_id=p_transaction FOR UPDATE;
  IF FOUND THEN
    IF existing.status='corrected' THEN RETURN true; END IF;
    IF existing.status<>'issued' THEN RETURN false; END IF;
    UPDATE public.invoices SET status='corrected',updated_at=now() WHERE id=existing.id;
  ELSE
    IF tx.invoice_hold_at IS NULL THEN RETURN false; END IF;
    INSERT INTO public.invoices(transaction_id,provider,status,external_key,provider_domain)
      VALUES(p_transaction,'manual','corrected','manual:'||p_transaction::text,'');
  END IF;
  INSERT INTO public.audit_log(table_name,operation,performed_by,new_values)
    VALUES('invoices','UPDATE',p_actor,jsonb_build_object('transaction_id',p_transaction,'action','corrected'));
  RETURN true;
END $$;


ALTER FUNCTION public.record_invoice_correction(p_transaction uuid, p_actor uuid) OWNER TO postgres;

--
-- Name: record_order_access_term(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_order_access_term(p_user_id uuid, p_product_id uuid, p_duration integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  txid uuid;
  term_key text := p_user_id::text || ':' || p_product_id::text;
  restored jsonb := nullif(current_setting('sellf.event_context', true), '')::jsonb->'guest_dispute_terms'->p_product_id::text;
  term jsonb;
BEGIN
  SELECT t.id INTO txid FROM public.payment_transactions t
  WHERE t.id::text = coalesce(nullif(current_setting('sellf.transfer_order', true), ''), nullif(current_setting('sellf.paid_order', true), ''))
    AND (t.user_id = p_user_id OR EXISTS (SELECT 1 FROM auth.users u WHERE u.id = p_user_id AND lower(u.email) = lower(t.customer_email))
      OR EXISTS (SELECT 1 FROM public.guest_purchases g WHERE g.transaction_id = t.id AND g.claimed_by_user_id = p_user_id))
    AND (t.product_id = p_product_id OR EXISTS (SELECT 1 FROM public.payment_line_items l WHERE l.transaction_id = t.id AND l.product_id = p_product_id)
      OR p_product_id IN (SELECT public.order_granted_components(t.id)))
    AND EXISTS (SELECT 1 FROM public.user_product_access a WHERE a.user_id = p_user_id AND a.product_id = p_product_id)
  LIMIT 1;
  IF txid IS NULL THEN RETURN; END IF;
  SELECT CASE WHEN bool_or(duration IS NULL) THEN NULL ELSE max(duration) END INTO p_duration
  FROM (
    SELECT p_duration AS duration
    UNION ALL
    SELECT nullif(l.access_duration_override, 0) FROM public.payment_line_items l
      WHERE l.transaction_id = txid AND l.product_id = p_product_id AND l.access_duration_override IS NOT NULL
    UNION ALL
    SELECT p.auto_grant_duration_days FROM public.products p
      WHERE p.id = p_product_id AND p.id IN (SELECT public.order_granted_components(txid))
  ) periods;
  term := coalesce(restored, jsonb_build_object('grantedAt', now(), 'expiresAt',
    CASE WHEN p_duration IS NULL THEN NULL ELSE now() + make_interval(days => p_duration) END))
    || (SELECT jsonb_build_object('grantVersion', a.version, 'grantExpiresAt', a.access_expires_at)
      FROM public.user_product_access a WHERE a.user_id = p_user_id AND a.product_id = p_product_id);
  UPDATE public.payment_transactions SET access_terms = access_terms || jsonb_build_object(term_key,
    coalesce(access_terms->term_key, term) || (term - 'grantedAt' - 'expiresAt')) WHERE id = txid;
END $$;


ALTER FUNCTION public.record_order_access_term(p_user_id uuid, p_product_id uuid, p_duration integer) OWNER TO postgres;

