--
-- Name: record_template_credential_status(text, text, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_template_credential_status(template_id text, expected_key text, expected_iv text, expected_tag text, verification_state text, checked_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF (SELECT auth.role()) IS DISTINCT FROM 'service_role' OR verification_state IS NULL OR
    verification_state NOT IN ('valid','expired','revoked','invalid','unknown') OR
    checked_at IS NULL OR checked_at > clock_timestamp() + interval '5 minutes' OR
    checked_at < clock_timestamp() - interval '60 seconds' THEN
    RETURN false;
  END IF;
  UPDATE public.template_credentials AS stored SET state=verification_state,
    verified_at=CASE WHEN verification_state='unknown' THEN NULL ELSE least(checked_at, clock_timestamp()) END
    WHERE stored.template_id=record_template_credential_status.template_id AND stored.encrypted_key=expected_key AND
      stored.encryption_iv=expected_iv AND stored.encryption_tag=expected_tag AND
      (stored.verified_at IS NULL OR stored.verified_at<=checked_at) AND
      (stored.state<>'revoked' OR verification_state='revoked');
  IF NOT FOUND THEN RETURN false; END IF;
  INSERT INTO public.audit_log(table_name,operation,new_values) VALUES('template_credentials','UPDATE',
    jsonb_build_object('templateId',template_id,'state',verification_state,'source','background'));
  RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END;
$$;


ALTER FUNCTION public.record_template_credential_status(template_id text, expected_key text, expected_iv text, expected_tag text, verification_state text, checked_at timestamp with time zone) OWNER TO postgres;

--
-- Name: refuse_access_from_ended_subscription(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refuse_access_from_ended_subscription() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.subscription_id IS NOT NULL AND NEW.access_expires_at IS NULL
    AND (TG_OP = 'INSERT' OR OLD.subscription_id IS DISTINCT FROM NEW.subscription_id)
    AND EXISTS (SELECT 1 FROM public.subscriptions s
      WHERE s.id = NEW.subscription_id AND s.status IN ('canceled', 'incomplete_expired')) THEN
    IF TG_OP = 'INSERT' THEN RETURN NULL; END IF;
    RETURN OLD;
  END IF;
  RETURN NEW;
END $$;


