--
-- Name: revoke_issued_licenses(uuid[], uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.revoke_issued_licenses(p_license_ids uuid[], p_actor uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text) RETURNS TABLE(id uuid, changed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE item record; why text;
BEGIN
  IF (select auth.role()) IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Service role required' USING ERRCODE='42501'; END IF;
  IF cardinality(p_license_ids)>100 THEN RAISE EXCEPTION 'Too many license identifiers'; END IF;
  why:=coalesce(p_reason,CASE WHEN p_actor IS NOT NULL THEN 'manual' ELSE NULL END);
  IF why IS NOT NULL AND why NOT IN ('refund','manual','subscription_cancelled','expired') THEN
    RAISE EXCEPTION 'Invalid revocation reason' USING ERRCODE='22023';
  END IF;
  FOR item IN SELECT l.id,l.product_id,l.email,l.order_id,l.revoked_at,l.revoked_by_dispute_id,l.revocation_reason
    FROM public.issued_licenses l WHERE l.id=ANY(p_license_ids) ORDER BY l.id FOR UPDATE
  LOOP
    -- A permanent decision takes over a dispute-owned revocation; an earlier permanent reason stays.
    UPDATE public.issued_licenses l SET revoked_at=coalesce(item.revoked_at,now()),revoked_by_dispute_id=NULL,
      revocation_reason=CASE WHEN item.revoked_at IS NULL OR item.revoked_by_dispute_id IS NOT NULL THEN why
        ELSE coalesce(item.revocation_reason,why) END
      WHERE l.id=item.id;
    IF p_actor IS NOT NULL THEN
      INSERT INTO public.audit_log(table_name,operation,performed_by,old_values,new_values)
        VALUES('issued_licenses','UPDATE',p_actor,
          jsonb_build_object('license_id',item.id,'product_id',item.product_id,'email',item.email,'order_id',item.order_id,'revoked_at',item.revoked_at),
          jsonb_build_object('action','license_revoked','license_id',item.id,'permanent',true,'reason',why));
    END IF;
    id:=item.id;changed:=item.revoked_at IS NULL;RETURN NEXT;
  END LOOP;
END $$;


ALTER FUNCTION public.revoke_issued_licenses(p_license_ids uuid[], p_actor uuid, p_reason text) OWNER TO postgres;

--
-- Name: revoke_license_for_disputed_order(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.revoke_license_for_disputed_order() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE tx public.payment_transactions; dispute_id text;
BEGIN
  SELECT t.* INTO tx FROM public.payment_transactions t
    WHERE t.id=CASE WHEN NEW.order_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN NEW.order_id::uuid END
      OR t.session_id=NEW.order_id OR t.stripe_payment_intent_id=NEW.order_id OR t.stripe_invoice_id=NEW.order_id
    ORDER BY (t.product_id=NEW.product_id) DESC,t.created_at LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN RETURN NEW; END IF;
  IF tx.status IN ('refunded','cancelled') OR (tx.amount>0 AND tx.refunded_amount>=tx.amount) THEN
    NEW.revoked_at:=coalesce(NEW.revoked_at,now());
    NEW.revoked_by_dispute_id:=NULL;
    NEW.revocation_reason:=CASE WHEN tx.status='cancelled' THEN 'manual' ELSE 'refund' END;
  ELSIF tx.status='disputed' THEN
    SELECT d.stripe_dispute_id INTO dispute_id FROM public.payment_disputes d
      WHERE d.transaction_id=tx.id AND d.status<>'won' AND d.suspended_at IS NOT NULL ORDER BY d.suspended_at,d.stripe_dispute_id LIMIT 1 FOR UPDATE;
    IF dispute_id IS NOT NULL THEN
      NEW.revoked_at:=coalesce(NEW.revoked_at,now());
      NEW.revoked_by_dispute_id:=dispute_id;
      UPDATE public.payment_disputes SET revoked_license_ids=array_append(revoked_license_ids,NEW.id)
        WHERE stripe_dispute_id=dispute_id AND NOT NEW.id=ANY(revoked_license_ids);
    END IF;
  END IF;
  RETURN NEW;
END $_$;


ALTER FUNCTION public.revoke_license_for_disputed_order() OWNER TO postgres;

--
-- Name: revoke_order_bundle_components(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.revoke_order_bundle_components(p_transaction_id uuid, p_user_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE t public.payment_transactions; removed integer := 0; candidate uuid;
BEGIN
  IF (select auth.role()) IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Service role required' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO t FROM public.payment_transactions WHERE id = p_transaction_id;
  IF NOT FOUND OR p_user_id IS NULL THEN RETURN 0; END IF;
  FOR candidate IN
    SELECT a.product_id FROM public.user_product_access a
  WHERE a.user_id = p_user_id
    AND a.product_id IN (SELECT public.order_granted_components(t.id))
    AND a.product_id IS DISTINCT FROM t.product_id
    AND a.subscription_id IS NULL
  LOOP
    IF public.revoke_order_product_access(t.id, p_user_id, candidate) THEN removed := removed + 1; END IF;
  END LOOP;
  RETURN removed;
END $$;


ALTER FUNCTION public.revoke_order_bundle_components(p_transaction_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: revoke_order_licenses(uuid, text[], text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.revoke_order_licenses(p_product_id uuid, p_order_ids text[], p_reason text) RETURNS TABLE(id uuid, changed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE refs text[]; item record;
BEGIN
  IF (select auth.role()) IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Service role required' USING ERRCODE='42501'; END IF;
  PERFORM t.id FROM public.payment_transactions t
    WHERE t.product_id=p_product_id AND public.license_order_references(t) && p_order_ids ORDER BY t.id FOR UPDATE;
  SELECT array_agg(DISTINCT ref) INTO refs FROM public.payment_transactions t
    CROSS JOIN LATERAL unnest(public.license_order_references(t)) ref
    WHERE t.product_id=p_product_id AND public.license_order_references(t) && p_order_ids;
  FOR item IN SELECT l.id FROM public.issued_licenses l
    WHERE (refs IS NOT NULL AND l.order_id=ANY(refs))
      OR (l.product_id=p_product_id AND l.order_id=ANY(p_order_ids))
    ORDER BY l.id FOR UPDATE
  LOOP
    RETURN QUERY SELECT * FROM public.revoke_issued_licenses(ARRAY[item.id],NULL,p_reason);
  END LOOP;
END $$;


ALTER FUNCTION public.revoke_order_licenses(p_product_id uuid, p_order_ids text[], p_reason text) OWNER TO postgres;

--
-- Name: revoke_order_product_access(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.revoke_order_product_access(p_transaction_id uuid, p_user_id uuid, p_product_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE t public.payment_transactions; current_access public.user_product_access;
  remaining integer; permanent boolean; expires timestamptz; removed integer; suspended boolean; pending_disputes text[]; next_version integer;
BEGIN
  IF (select auth.role()) IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Service role required' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO t FROM public.payment_transactions WHERE id = p_transaction_id;
  IF NOT FOUND OR p_user_id IS NULL THEN RETURN false; END IF;
  PERFORM 1 FROM public.payment_disputes d
  WHERE NOT d.closed AND EXISTS (SELECT 1 FROM jsonb_array_elements(d.account_access) item
    WHERE item->>'user_id' = p_user_id::text AND item->>'product_id' = p_product_id::text)
  ORDER BY d.stripe_dispute_id FOR UPDATE;
  SELECT * INTO current_access FROM public.user_product_access WHERE user_id = p_user_id AND product_id = p_product_id FOR UPDATE;
  IF NOT FOUND THEN RETURN false; END IF;
  SELECT array_agg(d.stripe_dispute_id) INTO pending_disputes FROM public.payment_disputes d
  WHERE NOT d.closed AND d.status <> 'won' AND EXISTS (
    SELECT 1 FROM jsonb_array_elements(d.account_access) item WHERE item->>'id' = current_access.id::text
      AND (d.suspended_at = current_access.access_expires_at
        OR ((item->>'retainedVersion')::integer = current_access.version
          AND current_access.access_expires_at IS NOT DISTINCT FROM (item->>'retainedExpiresAt')::timestamptz)
        OR EXISTS (SELECT 1 FROM public.payment_transactions o
          WHERE (o.access_terms->(p_user_id::text || ':' || p_product_id::text)->>'grantVersion')::integer = current_access.version
            AND (o.access_terms->(p_user_id::text || ':' || p_product_id::text)->>'grantedAt')::timestamptz = current_access.access_granted_at
            AND current_access.access_expires_at IS NOT DISTINCT FROM
              (o.access_terms->(p_user_id::text || ':' || p_product_id::text)->>'grantExpiresAt')::timestamptz)));
  suspended := coalesce(cardinality(pending_disputes), 0) > 0;
  WITH sources AS (
    SELECT (current_access.independent_access->>'expiresAt')::timestamptz AS ends_at
    WHERE current_access.independent_access IS NOT NULL
    UNION ALL
    SELECT public.order_access_expiry(o.id, p_user_id, p_product_id) AS ends_at
    FROM public.payment_transactions o
    WHERE o.id <> t.id AND o.subscription_id IS NULL
      AND (o.status IN ('completed', 'partially_refunded')
        OR (o.status = 'awaiting_payment' AND coalesce((o.metadata->>'access_on_placement')::boolean, false)))
      AND (o.amount = 0 OR coalesce(o.refunded_amount, 0) < o.amount)
      AND (o.user_id = p_user_id OR EXISTS (
        SELECT 1 FROM public.guest_purchases g WHERE g.claimed_by_user_id = p_user_id
          AND (g.transaction_id = o.id OR (g.transaction_id IS NULL AND g.session_id = o.session_id))))
      AND (o.product_id = p_product_id
        OR EXISTS (SELECT 1 FROM public.payment_line_items l WHERE l.transaction_id = o.id AND l.product_id = p_product_id)
        OR p_product_id IN (SELECT public.order_granted_components(o.id)))
    UNION ALL
    SELECT CASE WHEN s.status = 'canceled' THEN s.paid_access_expires_at ELSE NULL END
    FROM public.subscriptions s WHERE s.user_id = p_user_id AND s.product_id = p_product_id
      AND s.id IS DISTINCT FROM t.subscription_id
      AND ((s.status IN ('active', 'trialing', 'past_due') AND (s.current_period_end IS NULL OR s.current_period_end > now()))
        OR (s.status = 'canceled' AND s.paid_access_expires_at > now()))
    UNION ALL
    SELECT least(other.access_expires_at, CASE WHEN component.auto_grant_duration_days IS NULL THEN NULL
      ELSE other.access_granted_at + make_interval(days => component.auto_grant_duration_days) END)
    FROM public.user_product_access other
    JOIN public.bundle_items b ON b.bundle_product_id = other.product_id
    JOIN public.products component ON component.id = b.component_product_id
    WHERE other.user_id = p_user_id AND other.product_id IS DISTINCT FROM t.product_id
      AND b.component_product_id = p_product_id
      AND NOT EXISTS (
        SELECT 1 FROM public.payment_transactions o WHERE o.product_id = other.product_id
          AND (o.status IN ('completed', 'partially_refunded', 'disputed')
            OR (o.status = 'awaiting_payment' AND coalesce((o.metadata->>'access_on_placement')::boolean, false)))
          AND (o.user_id = p_user_id OR EXISTS (
            SELECT 1 FROM public.guest_purchases g WHERE g.claimed_by_user_id = p_user_id
              AND (g.transaction_id = o.id OR (g.transaction_id IS NULL AND g.session_id = o.session_id)))))
  )
  SELECT count(*), bool_or(ends_at IS NULL), max(ends_at) INTO remaining, permanent, expires
  FROM sources WHERE ends_at IS NULL OR ends_at > now();
  IF remaining > 0 THEN
    expires := CASE WHEN permanent THEN NULL ELSE expires END;
    IF NOT suspended THEN expires := least(current_access.access_expires_at, expires); END IF;
  ELSIF suspended THEN
    SELECT max(greatest(current_access.access_granted_at, d.suspended_at)) INTO expires
    FROM public.payment_disputes d JOIN public.payment_transactions o ON o.id = d.transaction_id
    WHERE d.stripe_dispute_id = ANY(pending_disputes) AND d.transaction_id <> t.id AND o.status = 'disputed';
  END IF;
  IF remaining > 0 OR expires IS NOT NULL THEN
    next_version := current_access.version + CASE WHEN current_access.access_expires_at IS DISTINCT FROM expires THEN 1 ELSE 0 END;
    UPDATE public.user_product_access SET access_expires_at = expires, expiry_notified_at = NULL, version = next_version
    WHERE user_id = p_user_id AND product_id = p_product_id AND access_expires_at IS DISTINCT FROM expires;
    IF suspended THEN
      UPDATE public.payment_disputes d SET account_access = (
        SELECT jsonb_agg(CASE WHEN item->>'id' = current_access.id::text THEN
          jsonb_set(item, '{access_expires_at}', coalesce(to_jsonb(least((item->>'access_expires_at')::timestamptz,
            public.order_access_expiry(d.transaction_id, p_user_id, p_product_id))), 'null'::jsonb))
            || jsonb_build_object('retainedVersion', next_version, 'retainedExpiresAt', expires, 'retainedDuration', current_access.access_duration_days) ELSE item END)
        FROM jsonb_array_elements(d.account_access) item)
      WHERE d.stripe_dispute_id = ANY(pending_disputes);
    END IF;
    RETURN false;
  END IF;
  DELETE FROM public.user_product_access WHERE user_id = p_user_id AND product_id = p_product_id;
  GET DIAGNOSTICS removed = ROW_COUNT;
  RETURN removed > 0;
END $$;


ALTER FUNCTION public.revoke_order_product_access(p_transaction_id uuid, p_user_id uuid, p_product_id uuid) OWNER TO postgres;

--
-- Name: revoke_terminal_order_licenses(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.revoke_terminal_order_licenses() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE refs text[];
BEGIN
  IF NEW.status IN ('refunded','cancelled') OR (NEW.amount>0 AND NEW.refunded_amount>=NEW.amount) THEN
    refs:=public.license_order_references(NEW);
    PERFORM l.id FROM public.issued_licenses l WHERE l.order_id=ANY(refs) ORDER BY l.id FOR UPDATE;
    UPDATE public.issued_licenses l SET revoked_at=coalesce(l.revoked_at,now()),revoked_by_dispute_id=NULL,
      revocation_reason=CASE WHEN NEW.status='cancelled' THEN 'manual' ELSE 'refund' END
      WHERE l.order_id=ANY(refs)
        AND (l.revoked_at IS NULL OR l.revoked_by_dispute_id IS NOT NULL);
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.revoke_terminal_order_licenses() OWNER TO postgres;

--
-- Name: rotate_webhook_secret(uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rotate_webhook_secret(p_endpoint_id uuid, p_secret text, p_actor_id uuid, p_api_key_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.admin_users WHERE user_id = p_actor_id) THEN
    RAISE EXCEPTION 'Admin required';
  END IF;
  IF p_secret IS NULL OR p_secret NOT LIKE 'enc:v1:%' THEN
    RAISE EXCEPTION 'Encrypted secret required';
  END IF;

  UPDATE public.webhook_endpoints
  SET secret = p_secret, updated_at = now()
  WHERE id = p_endpoint_id;
  IF NOT FOUND THEN RETURN false; END IF;

  INSERT INTO public.audit_log (table_name, operation, new_values, performed_by)
  VALUES ('webhook_endpoints', 'UPDATE', jsonb_build_object(
    'id', p_endpoint_id,
    'action', 'secret_rotated',
    'api_key_id', p_api_key_id
  ), p_actor_id);
  RETURN true;
END;
$$;


ALTER FUNCTION public.rotate_webhook_secret(p_endpoint_id uuid, p_secret text, p_actor_id uuid, p_api_key_id uuid) OWNER TO postgres;

--
-- Name: save_attribution_config(integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_attribution_config(p_retention_days integer, p_rules jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE r jsonb; n integer := 0;
BEGIN
  IF NOT ((select auth.role()) = 'service_role' OR (select public.is_admin())) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;
  IF p_retention_days IS NULL OR p_retention_days NOT BETWEEN 1 AND 365 OR jsonb_typeof(p_rules) IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_rules) > 200 THEN
    RAISE EXCEPTION 'Invalid attribution config' USING ERRCODE = '22023';
  END IF;
  UPDATE public.attribution_settings SET click_id_retention_days = p_retention_days, updated_at = now() WHERE id = 1;
  DELETE FROM public.attribution_channel_rules WHERE NOT is_default;
  FOR r IN SELECT value FROM jsonb_array_elements(p_rules) LOOP
    IF jsonb_typeof(r) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Invalid rule' USING ERRCODE = '22023'; END IF;
    IF r ? 'id' AND EXISTS (SELECT 1 FROM public.attribution_channel_rules WHERE id::text = r->>'id' AND is_default) THEN
      UPDATE public.attribution_channel_rules SET is_active = coalesce((r->>'is_active')::boolean, true) WHERE id::text = r->>'id';
    ELSE
      INSERT INTO public.attribution_channel_rules(priority, channel, field, operator, value, is_active)
      VALUES ((r->>'priority')::integer, lower(r->>'channel'), r->>'field', r->>'operator', nullif(btrim(r->>'value'), ''),
        coalesce((r->>'is_active')::boolean, true));
      n := n + 1;
    END IF;
  END LOOP;
  PERFORM public.log_admin_action('save_attribution_config', 'attribution_settings', '1',
    jsonb_build_object('click_id_retention_days', p_retention_days, 'custom_rules', n));
  RETURN jsonb_build_object('success', true, 'custom_rules', n);
END $$;


ALTER FUNCTION public.save_attribution_config(p_retention_days integer, p_rules jsonb) OWNER TO postgres;

--
-- Name: save_bank_transfer_config(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_bank_transfer_config(p_config jsonb, p_actor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE cfg public.bank_transfer_config%ROWTYPE; cur public.bank_transfer_config%ROWTYPE;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM public.admin_users WHERE user_id=p_actor) THEN RAISE EXCEPTION 'Administrator required' USING ERRCODE='42501'; END IF;
  SELECT * INTO STRICT cur FROM public.bank_transfer_config WHERE id;
  cfg:=jsonb_populate_record(cur,p_config);
  UPDATE public.bank_transfer_config SET bank_transfer_enabled=cfg.bank_transfer_enabled,bank_account_holder=cfg.bank_account_holder,
    bank_account_number=cfg.bank_account_number,bank_name=cfg.bank_name,bank_transfer_title_template=cfg.bank_transfer_title_template,
    bank_transfer_due_days=cfg.bank_transfer_due_days,bank_transfer_grant_access_on_placement=cfg.bank_transfer_grant_access_on_placement,
    bank_transfer_max_unpaid_per_email=cfg.bank_transfer_max_unpaid_per_email,reservation_enabled=cfg.reservation_enabled,
    reservation_reminder_hours=cfg.reservation_reminder_hours,reservation_release_hours=cfg.reservation_release_hours,
    declared_hold_hours=cfg.declared_hold_hours WHERE id;
  INSERT INTO public.audit_log(table_name,operation,performed_by,user_id,new_values) VALUES('bank_transfer_config','UPDATE',p_actor,p_actor,
    jsonb_build_object('action','bank_transfer.settings','enabled',cfg.bank_transfer_enabled,'reservation_enabled',cfg.reservation_enabled,
      'reminder_hours',cfg.reservation_reminder_hours,'release_hours',cfg.reservation_release_hours,'declared_hold_hours',cfg.declared_hold_hours));
END $$;


ALTER FUNCTION public.save_bank_transfer_config(p_config jsonb, p_actor uuid) OWNER TO postgres;

--
-- Name: save_invoicing_config(jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_invoicing_config(p_settings jsonb, p_token jsonb, p_performed_by uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF (SELECT auth.role()) IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Service role required' USING ERRCODE='42501'; END IF;
  IF p_performed_by IS NULL OR jsonb_typeof(p_settings) IS DISTINCT FROM 'object'
     OR (p_token IS NOT NULL AND jsonb_typeof(p_token) <> 'object') THEN
    RAISE EXCEPTION 'Invalid invoice settings' USING ERRCODE='22023';
  END IF;
  UPDATE public.invoicing_config SET
    provider = p_settings->>'provider', domain = p_settings->>'domain', mode = p_settings->>'mode',
    exemption = p_settings->>'exemption', template = p_settings->>'template',
    token = CASE WHEN p_token IS NULL THEN token ELSE p_token END
  WHERE id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Invoice settings unavailable' USING ERRCODE='P0002'; END IF;
  INSERT INTO public.audit_log(table_name, operation, performed_by, new_values)
    VALUES('invoicing_config', 'UPDATE', p_performed_by, jsonb_build_object('provider', p_settings->>'provider'));
END $$;


ALTER FUNCTION public.save_invoicing_config(p_settings jsonb, p_token jsonb, p_performed_by uuid) OWNER TO postgres;

--
-- Name: save_template_credential(text, text, text, text, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_template_credential(template_id text, encrypted_key text, encryption_iv text, encryption_tag text, actor_user_id uuid DEFAULT NULL::uuid, actor_method text DEFAULT NULL::text, actor_api_key_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE owner_id uuid; key_record public.api_keys%ROWTYPE;
BEGIN
  IF (SELECT auth.role()) IS DISTINCT FROM 'service_role' THEN RETURN jsonb_build_object('success',false,'code','FORBIDDEN'); END IF;
  SELECT id INTO owner_id FROM public.admin_users WHERE user_id=actor_user_id FOR SHARE;
  IF owner_id IS NULL OR actor_method IS NULL OR actor_method NOT IN ('session','api_key') OR
    (actor_method='session' AND actor_api_key_id IS NOT NULL) THEN
    RETURN jsonb_build_object('success',false,'code','FORBIDDEN');
  END IF;
  IF actor_method='api_key' THEN
    SELECT * INTO key_record FROM public.api_keys WHERE id=actor_api_key_id FOR SHARE;
    IF NOT FOUND OR key_record.admin_user_id IS DISTINCT FROM owner_id OR key_record.revoked_at IS NOT NULL OR
      (NOT key_record.is_active AND (key_record.rotation_grace_until IS NULL OR key_record.rotation_grace_until<=clock_timestamp())) OR
      (key_record.expires_at IS NOT NULL AND key_record.expires_at<=clock_timestamp()) OR
      NOT (key_record.scopes @> '["templates:write"]'::jsonb) THEN
      RETURN jsonb_build_object('success',false,'code','FORBIDDEN');
    END IF;
  END IF;
  IF template_id IS NULL OR template_id NOT IN ('storefront-a','storefront-b','storefront-c') OR
    encrypted_key IS NULL OR encryption_iv IS NULL OR encryption_tag IS NULL THEN
    RETURN jsonb_build_object('success',false,'code','INVALID');
  END IF;
  INSERT INTO public.template_credentials AS stored(template_id,encrypted_key,encryption_iv,encryption_tag,state,verified_at)
    VALUES(template_id,encrypted_key,encryption_iv,encryption_tag,'unknown',NULL)
    ON CONFLICT ON CONSTRAINT template_credentials_pkey DO UPDATE SET encrypted_key=EXCLUDED.encrypted_key,
      encryption_iv=EXCLUDED.encryption_iv,encryption_tag=EXCLUDED.encryption_tag,state='unknown',verified_at=NULL,updated_at=clock_timestamp();
  INSERT INTO public.audit_log(table_name,operation,user_id,performed_by,new_values)
    VALUES('template_credentials','UPDATE',actor_user_id,actor_user_id,jsonb_build_object(
      'templateId',template_id,'state','unknown','scope','templates:write','actor_method',actor_method,'actor_api_key_id',actor_api_key_id));
  RETURN jsonb_build_object('success',true,'status',jsonb_build_object('templateId',template_id,'state','unknown','verifiedAt',NULL));
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success',false,'code','UNAVAILABLE');
END;
$$;


ALTER FUNCTION public.save_template_credential(template_id text, encrypted_key text, encryption_iv text, encryption_tag text, actor_user_id uuid, actor_method text, actor_api_key_id uuid) OWNER TO postgres;

--
-- Name: search_order_accesses(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.search_order_accesses(p_search text) RETURNS SETOF public.user_product_access
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
BEGIN
  IF p_search IS NULL OR length(p_search) > 200 THEN
    RAISE EXCEPTION 'Search must contain at most 200 characters' USING ERRCODE = '22023';
  END IF;
  RETURN QUERY SELECT a.* FROM public.user_product_access a
  WHERE EXISTS (SELECT 1 FROM public.user_access_stats u WHERE u.user_id = a.user_id AND strpos(lower(u.email), lower(p_search)) > 0)
    OR EXISTS (SELECT 1 FROM public.products p WHERE p.id = a.product_id
      AND (strpos(lower(p.name), lower(p_search)) > 0 OR strpos(lower(p.slug), lower(p_search)) > 0));
END;
$$;


ALTER FUNCTION public.search_order_accesses(p_search text) OWNER TO postgres;

--
-- Name: search_order_leads(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.search_order_leads(p_search text) RETURNS SETOF public.lead_submissions
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
BEGIN
  IF p_search IS NULL OR length(p_search) > 200 THEN
    RAISE EXCEPTION 'Search must contain at most 200 characters' USING ERRCODE = '22023';
  END IF;
  RETURN QUERY SELECT l.* FROM public.lead_submissions l
  WHERE strpos(lower(l.email), lower(p_search)) > 0
    OR EXISTS (SELECT 1 FROM public.products p WHERE p.id = l.product_id
      AND (strpos(lower(p.name), lower(p_search)) > 0 OR strpos(lower(p.slug), lower(p_search)) > 0));
END;
$$;


ALTER FUNCTION public.search_order_leads(p_search text) OWNER TO postgres;

--
-- Name: search_payment_transactions(text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.search_payment_transactions(p_search text, p_include_identifiers boolean DEFAULT true) RETURNS SETOF public.payment_transactions
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $_$
BEGIN
  IF p_search IS NULL OR length(p_search) > 200 THEN
    RAISE EXCEPTION 'Search must contain at most 200 characters' USING ERRCODE = '22023';
  END IF;
  RETURN QUERY SELECT t.* FROM public.payment_transactions t
  WHERE strpos(lower(t.customer_email), lower(p_search)) > 0
    OR (p_include_identifiers AND (strpos(lower(t.session_id), lower(p_search)) > 0
      OR strpos(lower(t.stripe_payment_intent_id), lower(p_search)) > 0))
    OR (trim(p_search) ~ '^#?[0-9]{1,15}$' AND t.order_number::text = ltrim(trim(p_search), '#0'))
    OR EXISTS (SELECT 1 FROM public.products p WHERE p.id = t.product_id
      AND (strpos(lower(p.name), lower(p_search)) > 0 OR strpos(lower(p.slug), lower(p_search)) > 0));
END;
$_$;


ALTER FUNCTION public.search_payment_transactions(p_search text, p_include_identifiers boolean) OWNER TO postgres;

--
-- Name: seller_license_public_keys(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.seller_license_public_keys(seller uuid) RETURNS TABLE(kid text, public_key text, alg text, status text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT k.kid, k.public_key, k.alg,
         CASE WHEN k.is_active THEN 'active' ELSE 'retired' END
  FROM public.seller_license_keys k
  WHERE k.original_seller_id = seller
  ORDER BY k.is_active DESC, k.created_at DESC, k.kid;
$$;


ALTER FUNCTION public.seller_license_public_keys(seller uuid) OWNER TO postgres;

--
-- Name: FUNCTION seller_license_public_keys(seller uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.seller_license_public_keys(seller uuid) IS 'Public keys (kid, public_key, alg, status) for a seller: the active signing key first, then retired keys that still verify licenses signed before a key change. Never exposes encrypted private-key columns.';


--
-- Name: seller_revoked_orders(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.seller_revoked_orders(seller uuid, hash_prefix text) RETURNS TABLE(order_hash text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  SELECT h.order_hash FROM public.issued_licenses l
  CROSS JOIN LATERAL (
    SELECT encode(extensions.digest(convert_to(l.order_id,'UTF8'),'sha256'),'hex') AS order_hash
  ) h WHERE l.original_seller_id=seller
    AND (l.revoked_at IS NOT NULL OR (l.expires_at<=now() AND EXISTS(
      SELECT 1 FROM public.payment_transactions t JOIN public.subscriptions s ON s.id=t.subscription_id
      WHERE t.product_id=l.product_id AND t.stripe_invoice_id=l.order_id AND s.status='canceled')))
    AND hash_prefix ~ '^[0-9a-f]{1,64}$' AND h.order_hash LIKE hash_prefix||'%';
$_$;


ALTER FUNCTION public.seller_revoked_orders(seller uuid, hash_prefix text) OWNER TO postgres;

--
-- Name: FUNCTION seller_revoked_orders(seller uuid, hash_prefix text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.seller_revoked_orders(seller uuid, hash_prefix text) IS 'k-anonymity CRL range query: returns revoked SHA-256 order hashes matching a hex prefix for a seller. Service-role only; never exposes raw order ids, tokens, or PII columns.';


--
-- Name: send_monitoring_email(text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.send_monitoring_email(alert_type text, alert_details jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '1s'
    AS $$
BEGIN
    -- Security check: Only allow service_role and authenticated users
    IF (select auth.role()) NOT IN ('service_role', 'authenticated') THEN
        RAISE EXCEPTION 'Unauthorized';
    END IF;
    
    -- TODO: Integrate with email service (SMTP, SendGrid, etc.)
    -- For now, we'll use pg_notify to send to external service
    
    PERFORM pg_notify(
        'monitoring_alerts',
        jsonb_build_object(
            'alert_type', alert_type,
            'alert_details', alert_details,
            'timestamp', extract(epoch from NOW()),
            'urgent', CASE 
                WHEN alert_type = 'critical_errors' THEN true
                ELSE false
            END
        )::text
    );
    
EXCEPTION 
    WHEN OTHERS THEN
        -- If email fails, don't break anything
        NULL;
END;
$$;


ALTER FUNCTION public.send_monitoring_email(alert_type text, alert_details jsonb) OWNER TO postgres;

--
-- Name: set_access_grant_source(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_access_grant_source() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  NEW.grant_source := coalesce(
    NEW.grant_source,
    CASE WHEN NEW.transfer_transaction_id IS NOT NULL THEN 'bank_transfer'
         WHEN NEW.subscription_id IS NOT NULL THEN 'subscription' END,
    nullif(current_setting('sellf.grant_source', true), ''),
    'unknown');
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.set_access_grant_source() OWNER TO postgres;

--
-- Name: set_business_event_actor(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_business_event_actor(p_actor jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF (select auth.role()) IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Service role required' USING ERRCODE='42501'; END IF;
  IF p_actor IS NULL OR jsonb_typeof(p_actor) <> 'object' OR coalesce(p_actor->>'type','') NOT IN ('user','api_key') OR p_actor->>'id' IS NULL THEN
    RAISE EXCEPTION 'Actor required' USING ERRCODE='22023';
  END IF;
  PERFORM (p_actor->>'id')::uuid;
  PERFORM set_config('sellf.event_context',jsonb_build_object('actor',jsonb_build_object('type',p_actor->>'type','id',p_actor->>'id'))::text,true);
END $$;


ALTER FUNCTION public.set_business_event_actor(p_actor jsonb) OWNER TO postgres;

--
-- Name: set_invoice_recipient_enabled(boolean, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_invoice_recipient_enabled(p_enabled boolean, p_performed_by uuid, p_details jsonb DEFAULT '{}'::jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_row public.shop_config;
  v_previous BOOLEAN;
BEGIN
  IF (select auth.role()) IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Service role required' USING ERRCODE = '42501';
  END IF;
  IF p_enabled IS NULL OR p_performed_by IS NULL
     OR (p_details IS NOT NULL AND jsonb_typeof(p_details) <> 'object') THEN
    RAISE EXCEPTION 'Invalid setting change' USING ERRCODE = '22023';
  END IF;

  -- Fresh install: create the singleton row (shop_config_singleton_idx) without racing another call.
  INSERT INTO public.shop_config DEFAULT VALUES ON CONFLICT DO NOTHING;
  SELECT * INTO v_row FROM public.shop_config LIMIT 1 FOR UPDATE;

  v_previous := coalesce(v_row.custom_settings -> 'invoice_recipient_enabled' = 'true'::jsonb, false);

  UPDATE public.shop_config
  SET custom_settings = jsonb_set(
        CASE WHEN jsonb_typeof(custom_settings) = 'object' THEN custom_settings ELSE '{}'::jsonb END,
        '{invoice_recipient_enabled}', to_jsonb(p_enabled), true),
      updated_at = now()
  WHERE id = v_row.id;

  INSERT INTO public.audit_log (table_name, operation, user_id, performed_by, old_values, new_values)
  VALUES (
    'shop_config', 'UPDATE', p_performed_by, p_performed_by,
    jsonb_build_object('invoice_recipient_enabled', v_previous),
    coalesce(p_details, '{}'::jsonb) || jsonb_build_object('invoice_recipient_enabled', p_enabled)
  );

  RETURN v_previous;
END;
$$;


ALTER FUNCTION public.set_invoice_recipient_enabled(p_enabled boolean, p_performed_by uuid, p_details jsonb) OWNER TO postgres;

--
-- Name: set_invoicing_auto_since(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_invoicing_auto_since() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.mode <> 'auto' THEN NEW.auto_since := NULL;
  ELSIF TG_OP = 'INSERT' THEN NEW.auto_since := now();
  ELSIF OLD.mode IS DISTINCT FROM NEW.mode OR OLD.provider IS DISTINCT FROM NEW.provider
    OR OLD.domain IS DISTINCT FROM NEW.domain THEN NEW.auto_since := now();
  ELSE NEW.auto_since := OLD.auto_since;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.set_invoicing_auto_since() OWNER TO postgres;

--
-- Name: set_maintenance_mode(boolean, text, timestamp with time zone, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_maintenance_mode(p_enabled boolean, p_message text, p_expected_end_at timestamp with time zone, p_performed_by uuid, p_details jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_row public.maintenance_mode;
  v_message text := nullif(btrim(p_message), '');
  v_previous jsonb;
  v_next jsonb;
BEGIN
  IF (select auth.role()) IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Service role required' USING ERRCODE = '42501';
  END IF;
  IF p_enabled IS NULL OR p_performed_by IS NULL
     OR (v_message IS NOT NULL AND char_length(v_message) > 500)
     OR (p_details IS NOT NULL AND jsonb_typeof(p_details) <> 'object') THEN
    RAISE EXCEPTION 'Invalid maintenance mode change' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.maintenance_mode (id) VALUES (true) ON CONFLICT (id) DO NOTHING;
  SELECT * INTO v_row FROM public.maintenance_mode WHERE id FOR UPDATE;

  v_previous := jsonb_build_object('enabled', v_row.enabled, 'message', v_row.message, 'expected_end_at', v_row.expected_end_at);
  v_next := jsonb_build_object('enabled', p_enabled, 'message', v_message, 'expected_end_at', p_expected_end_at);

  UPDATE public.maintenance_mode
  SET enabled = p_enabled,
      message = v_message,
      expected_end_at = p_expected_end_at,
      changed_at = now(),
      changed_by = p_performed_by
  WHERE id;

  INSERT INTO public.audit_log (table_name, operation, user_id, performed_by, old_values, new_values)
  VALUES ('maintenance_mode', 'UPDATE', p_performed_by, p_performed_by, v_previous, coalesce(p_details, '{}'::jsonb) || v_next);

  RETURN v_previous;
END;
$$;


ALTER FUNCTION public.set_maintenance_mode(p_enabled boolean, p_message text, p_expected_end_at timestamp with time zone, p_performed_by uuid, p_details jsonb) OWNER TO postgres;

--
-- Name: set_payment_order_buyer(jsonb, text, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_payment_order_buyer(p_buyer jsonb, p_session_id text DEFAULT NULL::text, p_payment_intent_id text DEFAULT NULL::text, p_only_if_missing boolean DEFAULT false) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_rows integer;
BEGIN
  IF p_buyer IS NULL OR jsonb_typeof(p_buyer) <> 'object' THEN
    RAISE EXCEPTION 'buyer must be a JSON object' USING ERRCODE = '22023';
  END IF;
  IF p_session_id IS NULL AND p_payment_intent_id IS NULL THEN
    RAISE EXCEPTION 'session or payment intent id is required' USING ERRCODE = '22023';
  END IF;

  UPDATE public.payment_transactions
  SET order_details = coalesce(order_details, '{}'::jsonb) || jsonb_build_object('buyer', p_buyer),
      updated_at = now()
  WHERE (session_id = p_session_id OR stripe_payment_intent_id = p_payment_intent_id)
    AND CASE
          WHEN p_only_if_missing THEN order_details -> 'buyer' IS NULL
          ELSE status = 'pending'
        END;

  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN v_rows;
END;
$$;


ALTER FUNCTION public.set_payment_order_buyer(p_buyer jsonb, p_session_id text, p_payment_intent_id text, p_only_if_missing boolean) OWNER TO postgres;

--
-- Name: set_payment_order_details(jsonb, uuid, integer, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_payment_order_details(p_details jsonb, p_product_id uuid, p_quantity integer, p_session_id text DEFAULT NULL::text, p_payment_intent_id text DEFAULT NULL::text, p_custom_field_values jsonb DEFAULT NULL::jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE tx public.payment_transactions; v_quantity integer; v_merged jsonb;
BEGIN
  IF (select auth.role()) IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Service role required' USING ERRCODE = '42501'; END IF;
  IF p_details IS NULL OR jsonb_typeof(p_details) <> 'object'
     OR p_product_id IS NULL OR p_quantity IS NULL OR p_quantity NOT BETWEEN 1 AND 100
     OR (p_session_id IS NULL) = (p_payment_intent_id IS NULL)
     OR (p_custom_field_values IS NOT NULL AND jsonb_typeof(p_custom_field_values) <> 'object') THEN
    RAISE EXCEPTION 'Invalid order details' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO tx FROM public.payment_transactions
    WHERE (session_id = p_session_id OR stripe_payment_intent_id = p_payment_intent_id)
      AND product_id = p_product_id AND status = 'pending' FOR UPDATE;
  IF NOT FOUND THEN RETURN 0; END IF;
  SELECT quantity INTO v_quantity FROM public.payment_line_items
    WHERE transaction_id = tx.id AND product_id = p_product_id AND item_type = 'main_product';
  IF v_quantity IS DISTINCT FROM p_quantity THEN RETURN -1; END IF;
  v_merged := coalesce(tx.order_details, '{}'::jsonb) || p_details;
  -- Same measure as the payment_transactions_order_details_check constraint.
  IF octet_length(v_merged::text) > 65536 THEN
    RAISE EXCEPTION 'details_too_large' USING ERRCODE = '54000';
  END IF;
  UPDATE public.payment_transactions
  SET order_details = v_merged,
      custom_field_values = coalesce(p_custom_field_values, custom_field_values),
      updated_at = now()
  WHERE id = tx.id;
  RETURN 1;
END $$;


ALTER FUNCTION public.set_payment_order_details(p_details jsonb, p_product_id uuid, p_quantity integer, p_session_id text, p_payment_intent_id text, p_custom_field_values jsonb) OWNER TO postgres;

