--
-- Name: storefront_config_valid(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.storefront_config_valid(config jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO ''
    AS $_$
BEGIN
  IF public.jsonschema_subset_matches(public.storefront_config_schema(), config) IS DISTINCT FROM true THEN RETURN false; END IF;
  IF EXISTS (
    WITH RECURSIVE nodes(value, depth) AS (
      SELECT config, 0 UNION ALL
      SELECT child.value, nodes.depth + 1 FROM nodes CROSS JOIN LATERAL (
        SELECT value FROM pg_catalog.jsonb_each(CASE WHEN jsonb_typeof(nodes.value)='object' THEN nodes.value ELSE '{}'::jsonb END)
        UNION ALL SELECT value FROM pg_catalog.jsonb_array_elements(CASE WHEN jsonb_typeof(nodes.value)='array' THEN nodes.value ELSE '[]'::jsonb END)
      ) child WHERE nodes.depth <= 12
    ) SELECT 1 FROM nodes WHERE depth > 12 OR
      (jsonb_typeof(value)='string' AND (value #>> '{}') ~ U&'[\FEFF\FFFD]') OR
      (jsonb_typeof(value)='object' AND value ?| ARRAY['__proto__','prototype','constructor'])
  ) THEN RETURN false; END IF;
  IF EXISTS (
    SELECT 1 FROM pg_catalog.jsonb_each(config->'content') slot CROSS JOIN LATERAL pg_catalog.jsonb_each(slot.value) locale
    CROSS JOIN LATERAL pg_catalog.jsonb_array_elements(COALESCE(locale.value->'items','[]'::jsonb)) item
    WHERE locale.key IN ('en','pl') GROUP BY slot.key, locale.key
    HAVING count(*) <> count(DISTINCT CASE WHEN slot.key = 'home.paths' THEN lower(item->>'productId') WHEN (locale.value->>'kind' = 'comparison' OR slot.key = 'home.featured') THEN item->>'productId' ELSE item->>'id' END)
  ) THEN RETURN false; END IF;
  IF EXISTS (
    SELECT 1 FROM pg_catalog.jsonb_each(config->'settingsByTemplate') settings
    CROSS JOIN LATERAL pg_catalog.jsonb_each(settings.value) field
    CROSS JOIN LATERAL pg_catalog.jsonb_array_elements_text(CASE WHEN jsonb_typeof(field.value)='array' THEN field.value ELSE '[]'::jsonb END) item
    GROUP BY settings.key, field.key HAVING count(*) <> count(DISTINCT item)
  ) THEN RETURN false; END IF;
  IF EXISTS (
    SELECT 1 FROM pg_catalog.jsonb_each(config#>'{content,home.search}') locale
    CROSS JOIN LATERAL pg_catalog.jsonb_array_elements(COALESCE(locale.value->'items','[]'::jsonb)) item
    WHERE locale.key IN ('en','pl') GROUP BY locale.key HAVING count(*) <> count(DISTINCT item->>'categoryId')
  ) THEN RETURN false; END IF;
  IF EXISTS (
    SELECT 1 FROM pg_catalog.jsonb_each(config#>'{content,home.paths}') locale
    CROSS JOIN LATERAL pg_catalog.jsonb_array_elements(COALESCE(locale.value->'items','[]'::jsonb)) item
    WHERE locale.key IN ('en','pl') GROUP BY locale.key HAVING count(*) <> count(DISTINCT item->>'id')
  ) THEN RETURN false; END IF;
  IF EXISTS (
    SELECT 1 FROM pg_catalog.jsonb_each(config#>'{content,home.projects}') locale
    CROSS JOIN LATERAL pg_catalog.jsonb_array_elements(COALESCE(locale.value->'items','[]'::jsonb)) item
    WHERE locale.key IN ('en','pl') AND item->>'url' ~ '^https://([^/]+\.)?(localhost|local|internal|home|lan|google\.internal)(:443)?(/|$)'
  ) THEN RETURN false; END IF;
  RETURN true;
END;
$_$;


ALTER FUNCTION public.storefront_config_valid(config jsonb) OWNER TO postgres;

--
-- Name: submit_order_participants(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.submit_order_participants(p_order_id uuid, p_people jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE tx public.payment_transactions; prod public.products; qty integer; person jsonb;
BEGIN
  IF (select auth.role()) IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Service role required' USING ERRCODE = '42501'; END IF;
  SELECT * INTO tx FROM public.payment_transactions WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'code', 'not_found'); END IF;
  SELECT * INTO prod FROM public.products WHERE id = tx.product_id;
  IF tx.status <> 'completed' THEN RETURN jsonb_build_object('ok', false, 'code', 'not_paid'); END IF;
  IF NOT EXISTS (SELECT 1 FROM jsonb_array_elements(coalesce(prod.checkout_profile->'modules', '[]')) m
      WHERE m->>'id' = 'participants' AND m->'allow_later' = 'true'::jsonb) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'not_allowed');
  END IF;
  IF coalesce(jsonb_array_length(tx.order_details->'participants'->'people'), 0) > 0 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'already_complete');
  END IF;
  qty := coalesce((tx.order_details->'quantity'->>'value')::integer, 1);
  IF p_people IS NULL OR jsonb_typeof(p_people) <> 'array' OR jsonb_array_length(p_people) <> qty THEN
    RETURN jsonb_build_object('ok', false, 'code', 'participant_count');
  END IF;
  FOR person IN SELECT * FROM jsonb_array_elements(p_people) LOOP
    IF jsonb_typeof(person) <> 'object' OR (SELECT count(*) FROM jsonb_object_keys(person)) <> 3
       OR jsonb_typeof(person->'first_name') <> 'string' OR jsonb_typeof(person->'last_name') <> 'string'
       OR jsonb_typeof(person->'email') <> 'string' OR length(person->>'email') > 254 THEN
      RETURN jsonb_build_object('ok', false, 'code', 'invalid');
    END IF;
  END LOOP;
  UPDATE public.payment_transactions SET
    order_details = coalesce(order_details, '{}'::jsonb) || jsonb_build_object('participants', jsonb_build_object('v', 1, 'people', p_people)),
    participants_completed_at = now(), updated_at = now()
  WHERE id = tx.id;
  INSERT INTO public.business_events(event_type, product_id, payload, deduplication_key)
  VALUES ('order.participants_updated', tx.product_id, jsonb_build_object(
    'customer', jsonb_build_object('userId', tx.user_id, 'email', tx.customer_email),
    'order', jsonb_build_object('orderId', tx.id, 'orderNumber', tx.order_number, 'status', tx.status),
    'product', jsonb_build_object('id', prod.id, 'name', prod.name, 'slug', prod.slug),
    'orderDetails', jsonb_build_object('quantity', tx.order_details->'quantity', 'participants', jsonb_build_object('v', 1, 'people', p_people)),
    'reason', 'participants_added_after_payment',
    'actor', jsonb_build_object('type', 'customer', 'id', NULL),
    'occurredAt', clock_timestamp()), 'order.participants_updated:' || tx.id)
  ON CONFLICT (deduplication_key) DO NOTHING;
  RETURN jsonb_build_object('ok', true);
END $$;


ALTER FUNCTION public.submit_order_participants(p_order_id uuid, p_people jsonb) OWNER TO postgres;

--
-- Name: telemetry_claim_send(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.telemetry_claim_send(p_window_ms bigint, p_lease_ms bigint) RETURNS TABLE(instance_id uuid, report_id uuid)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  UPDATE public.telemetry_state
     SET last_attempt_at = now(),
         report_id = COALESCE(report_id, gen_random_uuid())
   WHERE id = 'singleton'
     AND (last_sent_at IS NULL OR last_sent_at < now() - make_interval(secs => p_window_ms / 1000.0))
     AND (last_attempt_at IS NULL OR last_attempt_at < now() - make_interval(secs => p_lease_ms / 1000.0))
   RETURNING instance_id, report_id;
$$;


ALTER FUNCTION public.telemetry_claim_send(p_window_ms bigint, p_lease_ms bigint) OWNER TO postgres;

