--
-- Name: validate_bundle_item(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.validate_bundle_item() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  parent public.products;
  component public.products;
BEGIN
  PERFORM 1 FROM public.products WHERE id IN (NEW.bundle_product_id, NEW.component_product_id) ORDER BY id FOR SHARE;
  SELECT * INTO parent FROM public.products WHERE id = NEW.bundle_product_id;
  SELECT * INTO component FROM public.products WHERE id = NEW.component_product_id;
  IF parent.is_bundle IS NOT TRUE OR component.id IS NULL OR component.is_bundle
    OR component.product_type <> 'one_time' THEN
    RAISE EXCEPTION 'Invalid bundle component' USING ERRCODE = '23514';
  END IF;
  IF component.archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'Archived products cannot be bundle components' USING ERRCODE = '23514', DETAIL = 'bundle_component_archived';
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.validate_bundle_item() OWNER TO postgres;

--
-- Name: validate_lead_consent_version(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.validate_lead_consent_version() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF (NEW.lead_consent_text_pl, NEW.lead_consent_text_en) IS DISTINCT FROM
     (OLD.lead_consent_text_pl, OLD.lead_consent_text_en)
     AND NEW.lead_consent_version = OLD.lead_consent_version THEN
    RAISE EXCEPTION 'A wording change requires a new consent version' USING ERRCODE='23514';
  END IF;
  IF EXISTS (SELECT 1 FROM public.lead_submissions s WHERE s.product_id=NEW.id AND s.marketing_consent
    AND ((s.consent_version=NEW.lead_consent_version||':pl' AND s.consent_text<>NEW.lead_consent_text_pl)
      OR (s.consent_version=NEW.lead_consent_version||':en' AND s.consent_text<>NEW.lead_consent_text_en))) THEN
    RAISE EXCEPTION 'Consent version already has different wording' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.validate_lead_consent_version() OWNER TO postgres;

--
-- Name: validate_payment_transaction(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.validate_payment_transaction(transaction_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '2s'
    AS $$
DECLARE
    transaction_record RECORD;
    current_user_id UUID;
BEGIN
    -- Enhanced UUID validation
    IF transaction_id IS NULL THEN
        RETURN FALSE;
    END IF;
    
    -- Check for null UUID or invalid patterns
    IF transaction_id = '00000000-0000-0000-0000-000000000000'::UUID THEN
        RETURN FALSE; -- Reject null UUID
    END IF;
    
    -- Additional validation: ensure UUID string format is canonical
    -- PostgreSQL automatically validates UUID format on cast, but this adds extra safety
    BEGIN
        -- This will raise an exception if transaction_id cannot be converted to text and back
        IF (transaction_id::TEXT)::UUID != transaction_id THEN
            RETURN FALSE;
        END IF;
    EXCEPTION WHEN OTHERS THEN
        RETURN FALSE; -- Invalid UUID format or conversion error
    END;
    
    -- Get current user
    current_user_id := auth.uid();
    
    -- Get transaction with access control
    SELECT * INTO transaction_record
    FROM public.payment_transactions
    WHERE id = transaction_id
      AND (
        -- User can validate their own transactions
        user_id = current_user_id OR
        -- Admins can validate any transaction
        (select public.is_admin()) OR
        -- Service role can validate any transaction
        (select auth.role()) = 'service_role'
      );
    
    IF NOT FOUND THEN
        RETURN FALSE; -- Transaction not found or access denied
    END IF;
    
    -- Validate transaction integrity
    IF transaction_record.amount <= 0 THEN
        RETURN FALSE;
    END IF;
    
    IF transaction_record.refunded_amount > transaction_record.amount THEN
        RETURN FALSE;
    END IF;
    
    IF transaction_record.status = 'refunded' AND transaction_record.refunded_at IS NULL THEN
        RETURN FALSE;
    END IF;
    
    -- Validate refunded_amount is non-negative
    IF transaction_record.refunded_amount < 0 THEN
        RETURN FALSE;
    END IF;
    
    RETURN TRUE;
END;
$$;


