--
-- Name: validate_seller_embed_origins(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.validate_seller_embed_origins() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  origin text;
BEGIN
  IF COALESCE(array_length(NEW.allowed_embed_origins, 1), 0) > 20 THEN
    RAISE EXCEPTION 'Maximum 20 embed origins are allowed';
  END IF;

  FOREACH origin IN ARRAY NEW.allowed_embed_origins LOOP
    IF origin !~ '^https://[^/?#]+$' AND origin !~ '^http://(localhost|127\.0\.0\.1)(:[0-9]+)?$' THEN
      RAISE EXCEPTION 'Invalid embed origin format';
    END IF;
  END LOOP;

  RETURN NEW;
END;
$_$;


ALTER FUNCTION public.validate_seller_embed_origins() OWNER TO postgres;

--
-- Name: verify_api_key(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.verify_api_key(p_key_hash text) RETURNS TABLE(key_id uuid, admin_user_id uuid, scopes jsonb, rate_limit_per_minute integer, is_valid boolean, rejection_reason text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_key RECORD;
BEGIN
  -- Find the key
  SELECT * INTO v_key
  FROM public.api_keys ak
  WHERE ak.key_hash = p_key_hash;

  -- Key not found
  IF NOT FOUND THEN
    RETURN QUERY SELECT
      NULL::UUID, NULL::UUID, NULL::JSONB, NULL::INTEGER,
      false, 'Invalid API key'::TEXT;
    RETURN;
  END IF;

  -- Key was revoked: no grace window applies
  IF v_key.revoked_at IS NOT NULL THEN
    RETURN QUERY SELECT
      v_key.id, v_key.admin_user_id, v_key.scopes, v_key.rate_limit_per_minute,
      false, 'API key has been revoked'::TEXT;
    RETURN;
  END IF;

  -- Key is not active
  IF NOT v_key.is_active THEN
    -- Check if it's in rotation grace period
    IF v_key.rotation_grace_until IS NOT NULL AND v_key.rotation_grace_until > NOW() THEN
      -- Still in grace period, allow
    ELSE
      RETURN QUERY SELECT
        v_key.id, v_key.admin_user_id, v_key.scopes, v_key.rate_limit_per_minute,
        false, 'API key has been revoked'::TEXT;
      RETURN;
    END IF;
  END IF;

  -- Key has expired
  IF v_key.expires_at IS NOT NULL AND v_key.expires_at < NOW() THEN
    RETURN QUERY SELECT
      v_key.id, v_key.admin_user_id, v_key.scopes, v_key.rate_limit_per_minute,
      false, 'API key has expired'::TEXT;
    RETURN;
  END IF;

  -- Update usage stats (non-blocking)
  UPDATE public.api_keys
  SET
    last_used_at = NOW(),
    usage_count = usage_count + 1
  WHERE id = v_key.id;

  -- Key is valid
  RETURN QUERY SELECT
    v_key.id, v_key.admin_user_id, v_key.scopes, v_key.rate_limit_per_minute,
    true, NULL::TEXT;
END;
$$;


ALTER FUNCTION public.verify_api_key(p_key_hash text) OWNER TO postgres;

--
-- Name: verify_coupon(text, uuid, text, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.verify_coupon(code_param text, product_id_param uuid, customer_email_param text DEFAULT NULL::text, currency_param text DEFAULT 'USD'::text, reserve_param boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  coupon_record public.coupons%ROWTYPE;
  clean_email text := lower(trim(customer_email_param));
BEGIN
  IF code_param IS NOT NULL AND length(code_param) > 0 THEN
    IF NOT public.check_rate_limit(
      'verify_coupon', 5, 60,
      'code:' || lower(left(code_param, 80)) || ':' ||
        COALESCE((select auth.uid())::text, clean_email, 'anonymous')
    ) THEN
      RETURN jsonb_build_object('valid', false, 'error', 'Too many attempts. Please try again later.');
    END IF;
  END IF;
  IF NOT public.check_rate_limit('verify_coupon', 100, 60) THEN
    RETURN jsonb_build_object('valid', false, 'error', 'Too many attempts. Please try again later.');
  END IF;
  SELECT * INTO coupon_record
  FROM public.coupons
  WHERE code = code_param AND is_active = true
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('valid', false, 'error', 'Invalid code');
  END IF;
  IF coupon_record.expires_at IS NOT NULL AND coupon_record.expires_at < NOW() THEN
    RETURN jsonb_build_object('valid', false, 'error', 'Code expired');
  END IF;
  IF coupon_record.starts_at > NOW() THEN
    RETURN jsonb_build_object('valid', false, 'error', 'Code not active yet');
  END IF;
  RETURN public._reserve_coupon(coupon_record.id, product_id_param, customer_email_param, currency_param, reserve_param);
END;
$$;


ALTER FUNCTION public.verify_coupon(code_param text, product_id_param uuid, customer_email_param text, currency_param text, reserve_param boolean) OWNER TO postgres;

