--
-- Name: coupons; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.coupons (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    code text NOT NULL,
    name text,
    discount_type text NOT NULL,
    discount_value numeric NOT NULL,
    currency text,
    allowed_emails jsonb DEFAULT '[]'::jsonb NOT NULL,
    allowed_product_ids jsonb DEFAULT '[]'::jsonb NOT NULL,
    exclude_order_bumps boolean DEFAULT false NOT NULL,
    usage_limit_global integer,
    usage_limit_per_user integer DEFAULT 1,
    current_usage_count integer DEFAULT 0 NOT NULL,
    starts_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone,
    is_active boolean DEFAULT true NOT NULL,
    is_public boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    is_oto_coupon boolean DEFAULT false NOT NULL,
    oto_offer_id uuid,
    source_transaction_id uuid,
    duration text DEFAULT 'once'::text NOT NULL,
    duration_in_months integer,
    coupon_role text,
    CONSTRAINT coupons_check CHECK ((((discount_type = 'fixed'::text) AND ((currency IS NULL) OR (length(currency) = 3))) OR ((discount_type = 'percentage'::text) AND (currency IS NULL)) OR ((discount_type = 'set_price'::text) AND (currency IS NOT NULL) AND (currency ~ '^[A-Z]{3}$'::text)))),
    CONSTRAINT coupons_code_check CHECK ((length(code) >= 3)),
    CONSTRAINT coupons_coupon_role_check CHECK (((coupon_role IS NULL) OR (coupon_role = ANY (ARRAY['upsell'::text, 'downsell'::text])))),
    CONSTRAINT coupons_discount_type_check CHECK ((discount_type = ANY (ARRAY['percentage'::text, 'fixed'::text, 'set_price'::text]))),
    CONSTRAINT coupons_discount_value_check CHECK ((((discount_value > (0)::numeric) OR ((discount_type = 'set_price'::text) AND (discount_value = (0)::numeric))) AND ((discount_type <> 'set_price'::text) OR (discount_value < 'Infinity'::numeric)))),
    CONSTRAINT coupons_duration_check CHECK ((duration = ANY (ARRAY['once'::text, 'repeating'::text, 'forever'::text]))),
    CONSTRAINT coupons_duration_in_months_check CHECK (((duration_in_months IS NULL) OR (duration_in_months > 0))),
    CONSTRAINT coupons_repeating_has_months CHECK (((duration <> 'repeating'::text) OR (duration_in_months IS NOT NULL))),
    CONSTRAINT coupons_set_price_whole CHECK (((discount_type <> 'set_price'::text) OR (public.currency_minor_factor(currency) <> (1)::numeric) OR (discount_value = trunc(discount_value)))),
    CONSTRAINT valid_percentage CHECK (((discount_type <> 'percentage'::text) OR (discount_value <= (100)::numeric)))
);


ALTER TABLE public.coupons OWNER TO postgres;

