--
-- Name: oto_offers; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.oto_offers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    source_product_id uuid NOT NULL,
    oto_product_id uuid NOT NULL,
    discount_type text NOT NULL,
    discount_value numeric NOT NULL,
    duration_minutes integer DEFAULT 15 NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    display_order integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    downsell_product_id uuid,
    downsell_discount_type text,
    downsell_discount_value numeric,
    downsell_duration_minutes integer,
    CONSTRAINT no_self_oto CHECK ((source_product_id <> oto_product_id)),
    CONSTRAINT oto_offers_discount_type_check CHECK ((discount_type = ANY (ARRAY['percentage'::text, 'fixed'::text]))),
    CONSTRAINT oto_offers_discount_value_check CHECK ((discount_value > (0)::numeric)),
    CONSTRAINT oto_offers_downsell_consistency CHECK ((((downsell_product_id IS NULL) AND (downsell_discount_type IS NULL) AND (downsell_discount_value IS NULL) AND (downsell_duration_minutes IS NULL)) OR ((downsell_product_id IS NOT NULL) AND (downsell_discount_type IS NOT NULL) AND (downsell_discount_value IS NOT NULL) AND (downsell_duration_minutes IS NOT NULL)))),
    CONSTRAINT oto_offers_downsell_discount_type_check CHECK (((downsell_discount_type IS NULL) OR (downsell_discount_type = ANY (ARRAY['percentage'::text, 'fixed'::text])))),
    CONSTRAINT oto_offers_downsell_discount_value_check CHECK (((downsell_discount_value IS NULL) OR ((downsell_discount_value > (0)::numeric) AND ((downsell_discount_type <> 'percentage'::text) OR (downsell_discount_value <= (100)::numeric))))),
    CONSTRAINT oto_offers_downsell_duration_check CHECK (((downsell_duration_minutes IS NULL) OR ((downsell_duration_minutes > 0) AND (downsell_duration_minutes <= 1440)))),
    CONSTRAINT oto_offers_downsell_not_source CHECK (((downsell_product_id IS NULL) OR (downsell_product_id <> source_product_id))),
    CONSTRAINT oto_offers_downsell_not_upsell CHECK (((downsell_product_id IS NULL) OR (downsell_product_id <> oto_product_id))),
    CONSTRAINT oto_offers_duration_minutes_check CHECK (((duration_minutes > 0) AND (duration_minutes <= 1440))),
    CONSTRAINT valid_percentage_discount CHECK (((discount_type <> 'percentage'::text) OR (discount_value <= (100)::numeric)))
);


ALTER TABLE public.oto_offers OWNER TO postgres;

