    CONSTRAINT payment_line_items_total_price_check CHECK (((total_price >= (0)::numeric) AND (total_price <= (99999999)::numeric))),
    CONSTRAINT payment_line_items_unit_price_check CHECK (((unit_price >= (0)::numeric) AND (unit_price <= (99999999)::numeric))),
    CONSTRAINT valid_total_price CHECK ((total_price = (unit_price * (quantity)::numeric)))
);


