CREATE TABLE public.payment_method_config (
    id integer DEFAULT 1 NOT NULL,
    config_mode text DEFAULT 'automatic'::text NOT NULL,
    stripe_pmc_id text,
    stripe_pmc_name text,
    stripe_pmc_last_synced timestamp with time zone,
    custom_payment_methods jsonb DEFAULT '[]'::jsonb,
