    currency_overrides jsonb DEFAULT '{}'::jsonb,
    enable_express_checkout boolean DEFAULT true NOT NULL,
    enable_apple_pay boolean DEFAULT true NOT NULL,
    enable_google_pay boolean DEFAULT true NOT NULL,
    enable_link boolean DEFAULT true NOT NULL,
    available_payment_methods jsonb DEFAULT '[]'::jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    last_modified_by uuid,
    CONSTRAINT payment_method_config_available_payment_methods_check CHECK ((jsonb_typeof(available_payment_methods) = 'array'::text)),
    CONSTRAINT payment_method_config_check CHECK ((((config_mode = 'stripe_preset'::text) AND (stripe_pmc_id IS NOT NULL) AND (stripe_pmc_id ~ '^pmc_'::text)) OR (config_mode <> 'stripe_preset'::text))),
    CONSTRAINT payment_method_config_config_mode_check CHECK ((config_mode = ANY (ARRAY['automatic'::text, 'stripe_preset'::text, 'custom'::text]))),
    CONSTRAINT payment_method_config_currency_overrides_check CHECK ((jsonb_typeof(currency_overrides) = 'object'::text)),
    CONSTRAINT payment_method_config_custom_payment_methods_check CHECK ((jsonb_typeof(custom_payment_methods) = 'array'::text)),
    CONSTRAINT payment_method_config_id_check CHECK ((id = 1)),
    CONSTRAINT payment_method_config_payment_method_order_check CHECK ((jsonb_typeof(payment_method_order) = 'array'::text))
);


ALTER TABLE public.payment_method_config OWNER TO postgres;

