--
-- Name: payment_system_health; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.payment_system_health WITH (security_invoker='on') AS
 SELECT 'payment_transactions'::text AS table_name,
    count(*) AS total_records,
    count(*) FILTER (WHERE (payment_transactions.status = 'completed'::text)) AS completed_transactions,
    count(*) FILTER (WHERE (payment_transactions.status = 'refunded'::text)) AS refunded_transactions,
    count(*) FILTER (WHERE (payment_transactions.status = 'disputed'::text)) AS disputed_transactions,
    avg(payment_transactions.amount) AS avg_transaction_amount,
    count(*) FILTER (WHERE (payment_transactions.created_at > (now() - '24:00:00'::interval))) AS records_last_24h,
    now() AS snapshot_time
   FROM public.payment_transactions;


ALTER TABLE public.payment_system_health OWNER TO postgres;

