    CONSTRAINT purchase_attribution_first_channel_check CHECK (((first_channel IS NULL) OR (first_channel ~ '^[a-z0-9_]{1,40}$'::text))),
    CONSTRAINT purchase_attribution_kind_check CHECK ((kind = ANY (ARRAY['payment'::text, 'subscription'::text, 'renewal'::text, 'bank_transfer'::text, 'free'::text]))),
    CONSTRAINT purchase_attribution_mode_check CHECK ((mode = ANY (ARRAY['url'::text, 'stored'::text, 'none'::text]))),
