--
-- Name: seller_customer_stats; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.seller_customer_stats WITH (security_invoker='on') AS
 SELECT u.id AS user_id,
    u.email,
    u.created_at AS user_created_at,
    u.email_confirmed_at,
    u.last_sign_in_at,
    u.raw_user_meta_data,
    COALESCE(access_stats.total_products, (0)::bigint) AS total_products,
    COALESCE(access_stats.total_value, (0)::numeric) AS total_value,
    access_stats.last_access_granted_at,
    access_stats.first_access_granted_at
   FROM ((( SELECT user_product_access.user_id
           FROM public.user_product_access
        UNION
         SELECT payment_transactions.user_id
           FROM public.payment_transactions
          WHERE (payment_transactions.user_id IS NOT NULL)) customers
     JOIN auth.users u ON ((u.id = customers.user_id)))
     LEFT JOIN ( SELECT upa.user_id,
            count(upa.id) AS total_products,
            COALESCE(sum(p.price), (0)::numeric) AS total_value,
            max(upa.created_at) AS last_access_granted_at,
            min(upa.created_at) AS first_access_granted_at
           FROM (public.user_product_access upa
             JOIN public.products p ON ((upa.product_id = p.id)))
          GROUP BY upa.user_id) access_stats ON ((access_stats.user_id = u.id)));


ALTER TABLE public.seller_customer_stats OWNER TO postgres;

